(function () {
  var TEXT = {"ko":{"nav_label":"도감 메뉴","nav_tool":"얼굴 재기","nav_method":"측정 방법","nav_about":"소개","nav_privacy":"개인정보","nav_contact":"문의","theme_group":"화면 모드","theme_light":"화이트","theme_dark":"다크","language_group":"언어","footer":"사진은 이 브라우저 안에서만 처리되고 서버로 전송되지 않습니다. 결과는 얼굴 비율을 동물별 기준과 견준 재미있는 비교이며, 과학적 판별이나 성격 테스트가 아닙니다. 표정, 고개 각도, 안경, 조명에 따라 순위가 달라질 수 있어요.","try_tool":"이 기준으로 얼굴 재기","read_method":"열 가지 비율이 어떻게 재는지 보기","other_animals":"다른 동물 기준","animal_ratio_heading":"이 동물로 기울어지는 비율","animal_score_heading":"점수가 가깝다는 뜻","animal_photo_heading":"사진에서 흔들리는 경우","name_cat":"고양이상","name_dog":"강아지상","name_fox":"여우상","name_rabbit":"토끼상","name_owl":"부엉이상","name_bear":"곰상","name_lion":"사자상","name_deer":"사슴상","name_wolf":"늑대상","method_title":"측정 방법 — 동물상 도감","method_meta":"얼굴 가로와 세로, 눈, 코, 입, 턱의 길이 비율을 어떻게 재고 아홉 동물 기준과 비교하는지 설명합니다.","method_h1":"측정 방법","method_lead":"이 도감은 머리카락, 귀, 옷차림을 보지 않습니다. 사진 속 얼굴에서 길이를 읽고, 그 길이를 얼굴 크기로 나눈 비율만 비교합니다. 같은 사람이라도 거리가 다르면 픽셀 수는 달라지므로, 픽셀 그 자체를 점수로 쓰지 않습니다.","method_measure":"분석은 이 브라우저 안에서 이루어집니다. 사진을 서버로 보내지 않습니다. 얼굴이 여러 개면 고른 영역 안에서 가장 크게 보이는 얼굴을 기준으로 합니다. 아래 평균 자리는 이 도감이 정면 사진에서 흔하다고 잡아 둔 출발점이며, 의학적인 정상 범위가 아닙니다.","method_ratios_heading":"열 가지 비율","method_r1":"얼굴형. 얼굴 가로를 얼굴 세로로 나눕니다. 수가 크면 가로로 넓은 얼굴이고, 작으면 세로로 긴 얼굴입니다. 이 도감의 평균 자리는 0.82입니다.","method_r2":"눈 크기. 눈 가로를 얼굴 가로로 나눕니다. 0.20이면 눈 가로가 얼굴 가로의 20%라는 뜻입니다.","method_r3":"눈매. 눈 세로를 눈 가로로 나눕니다. 크면 둥근 눈이고, 작으면 가늘고 날카로운 눈입니다. 평균 자리는 0.33입니다.","method_r4":"눈 사이. 두 눈 사이 거리를 얼굴 가로로 나눕니다. 평균 자리는 0.25에 가깝습니다.","method_r5":"코 너비. 코 가로를 얼굴 가로로 나눕니다. 평균 자리는 0.28에 가깝습니다.","method_r6":"코 길이. 코 길이를 얼굴 세로로 나눕니다. 평균 자리는 0.30입니다.","method_r7":"입 너비. 입 가로를 얼굴 가로로 나눕니다. 평균 자리는 0.40에 가깝습니다.","method_r8":"턱 너비. 턱이 넓은 위치의 가로를 얼굴 가로로 나눕니다. 평균 자리는 0.80입니다.","method_r9":"턱끝. 턱끝의 가로를 얼굴 가로로 나눕니다. 평균 자리는 0.32입니다.","method_r10":"중안부. 눈에서 코끝까지의 길이를 얼굴 세로로 나눕니다. 평균 자리는 0.25입니다.","method_score_heading":"점수가 나오는 방식","method_score":"열 가지 비율을 평균에서 얼마나 떨어졌는지로 바꾼 뒤, 동물마다 정해 둔 기준과 거리를 잽니다. 눈 크기처럼 인상에 큰 항목은 조금 더 무겁게 보고, 턱끝처럼 사진마다 잘 흔들리는 항목은 가볍게 봅니다. 가장 가까운 동물에 높은 점수를 줍니다. 점수는 최대 94입니다. 100을 주지 않는 이유는, 사진 한 장의 오차를 완전한 일치처럼 보이게 하지 않기 위해서입니다.","method_photo_heading":"같은 사람도 순위가 달라질 때","method_photo":"고개를 돌리거나, 눈을 세게 감기, 활짝 웃기, 너무 어두운 조명, 얼굴이 아주 작게 찍힌 사진은 순위가 달라질 수 있습니다. 가능하면 눈이 카메라와 같은 높이인 정면에서, 입을 다문 사진으로 비교해 보세요. 안경 테두리가 눈꼬리를 가리면 눈 길이를 잘못 읽을 수 있습니다. 광각으로 아주 가까이 찍으면 얼굴 가운데가 둥글게 부풀어 보입니다.","method_animals_heading":"아홉 동물의 기준","method_animals":"동물마다 어느 비율을 크고 작게 보는지가 다릅니다. 이름을 누르면 그 동물 기준만 따로 읽을 수 있습니다. 같은 문장을 동물 이름만 바꿔 반복하지 않았습니다.","about_title":"소개 — 동물상 도감","about_meta":"동물상 도감이 무엇을 비교하고, 사진을 어디에 두는지, 결과를 어떻게 읽어야 하는지 적습니다.","about_h1":"이 도감에 대하여","about_p1":"동물상 도감은 얼굴 사진의 길이 비율을 고양이, 강아지, 여우, 토끼, 부엉이, 곰, 사자, 사슴, 늑대 기준과 비교하는 브라우저 프로그램입니다. 방문자에게 약속하는 일은 하나입니다. 고른 얼굴 영역의 비율을 재고, 아홉 기준 중 어디와 가까운지 보여 주는 일입니다.","about_p2":"사진 파일은 이 브라우저 안에서만 읽고, 분석 서버로 올리지 않습니다. 페이지를 닫으면 그 사진도 함께 사라집니다. 이 기기에 남는 것은 고른 언어와 화이트·다크 화면 모드뿐입니다.","about_p3":"결과는 재미있는 비교입니다. 성격을 알려 주거나, 의학·유전·신원 확인에 쓰라고 만든 도구가 아닙니다. 운영, 오류, 개인정보에 대한 연락은 문의 페이지로 받습니다.","privacy_title":"개인정보 — 동물상 도감","privacy_meta":"얼굴 사진, 언어 설정, 광고, 댓글, 문의 폼이 각각 어떤 정보를 다루는지 적습니다.","privacy_h1":"개인정보","privacy_photo_heading":"얼굴 사진","privacy_photo":"카메라로 찍거나 올린 얼굴 사진은 분석을 위해 이 브라우저의 메모리에서만 다룹니다. 동물상 도감의 서버로 전송하지 않고, 계정에 저장하지도 않습니다. 페이지를 닫거나 다른 사진으로 바꾸면 이전 사진은 남지 않습니다.","privacy_store_heading":"이 기기에 남는 설정","privacy_store":"고른 언어는 language_code라는 이름으로, 화이트 또는 다크 모드는 theme_mode라는 이름으로 이 브라우저의 로컬 저장소에 남습니다. 이 값은 다음 방문에 같은 화면을 보여 주기 위한 것이며, 얼굴 사진과 함께 보내지지 않습니다.","privacy_ads_heading":"광고","privacy_ads":"이 사이트는 구글 애드센스 자동 광고를 사용합니다. 광고가 표시되면 구글이 쿠키와 비슷한 식별 값을 사용해 광고를 고르고 측정할 수 있습니다. 광고가 쓰는 정보에 대한 구글의 설명은 https://policies.google.com/technologies/ads 에서 볼 수 있습니다. 사이트 소유 확인을 위해 페이지 머리의 메타 태그와 루트의 ads.txt에 게시자 번호 ca-pub-8803401825336300 을 적어 두었습니다.","privacy_disqus_heading":"댓글","privacy_disqus":"댓글은 얼굴 재기 페이지 아래에만 있으며 Disqus가 처리합니다. 댓글을 쓰려면 Disqus 쪽의 로그인이나 가입이 필요하고, Disqus가 자체 쿠키를 사용할 수 있습니다. 댓글 내용은 얼굴 사진과 따로 저장됩니다. Disqus의 개인정보 안내는 https://help.disqus.com/en/articles/1717103-disqus-privacy-policy 에 있습니다.","privacy_form_heading":"문의 폼","privacy_form":"문의 페이지에서 보내기를 누를 때만 이름, 회사 또는 브랜드, 답장 받을 이메일, 문의 내용이 Formspree(https://formspree.io)로 전달됩니다. 얼굴 사진은 이 항목에 포함되지 않습니다. 보내지 않으면 폼에 적던 글도 저장되지 않습니다.","privacy_font_heading":"글꼴","privacy_font":"화면 글꼴은 Google Fonts에서 불러옵니다. 페이지를 열 때 브라우저가 fonts.googleapis.com 과 fonts.gstatic.com 에 글꼴 파일을 요청합니다. 그 요청에는 보통 접속 중인 주소와 브라우저 정보가 포함될 수 있습니다.","privacy_ask_heading":"질문","privacy_ask":"이 안내에서 빠졌거나 잘못된 부분이 있으면 문의 페이지로 알려 주세요. 얼굴 사진은 서버에 없어 되돌려 드릴 파일이 없습니다. 댓글 삭제는 Disqus에서, 이미 보낸 문의 메일의 삭제는 받은 쪽과 문의 페이지를 통해 요청할 수 있습니다.","contact_title":"문의 — 동물상 도감","contact_meta":"동물상 도감의 제휴, 오류, 개인정보 질문을 받는 문의 페이지입니다.","contact_h1":"문의","contact_help":"제휴, 오류, 개인정보 질문을 남겨 주세요. 얼굴 사진은 이 폼에 붙지 않습니다. 답변은 적어 주신 이메일로 갑니다.","contact_name":"이름","contact_company":"회사 또는 브랜드","contact_email":"답장 받을 이메일","contact_message":"문의 내용","contact_send":"문의 보내기","contact_subject":"동물상 도감 문의","contact_invalid":"이름, 답장 받을 이메일, 문의 내용을 입력한 뒤 다시 보내 주세요.","contact_sending":"문의를 보내는 중이에요.","contact_sent":"문의가 전달됐어요. 남겨 주신 메일로 답변드릴게요.","contact_fail":"문의를 보내지 못했어요. 잠시 후 다시 시도해 주세요.","contact_network":"문의를 보내지 못했어요. 인터넷 연결을 확인한 뒤 다시 시도해 주세요.","contact_teaser_title":"문의","contact_teaser":"제휴, 오류, 개인정보와 관련된 질문은 문의 페이지에 남겨 주세요. 답변은 적어 주신 이메일로 갑니다. 얼굴 사진은 문의에 포함되지 않습니다.","atlas_help":"동물 이름을 누르면 그 기준을 글로 읽을 수 있습니다. 얼굴 사진 없이도 도감을 볼 수 있어요.","lead":"비교에 쓰는 값은 머리카락이나 귀가 아니라 얼굴 가로·세로와 눈, 코, 입, 턱의 길이 비율입니다. 점수는 아홉 동물 기준과의 거리이며, 성격 테스트나 과학적 판별이 아닙니다.","cat_title":"고양이상 — 동물상 도감","cat_meta":"눈이 크고 코와 입이 작아, 이목구비가 얼굴 가운데로 모여 보이는 기준입니다.","cat_h1":"고양이상","cat_p1":"고양이상은 눈과 코, 입이 얼굴 한가운데로 모여 보이는 인상입니다. 도감의 고양이 기준은 얼굴이 조금 둥글고, 눈이 크며, 코와 입이 평균보다 작을 때 가까워집니다.","cat_p2":"얼굴 가로가 세로에 비해 넉넉하고, 눈 가로가 얼굴에서 차지하는 비율이 큽니다. 코 가로, 코 길이, 입 가로는 평균보다 작은 쪽을 고양이 쪽으로 봅니다. 눈에서 코끝까지의 중안부도 짧은 편입니다.","cat_p3":"점수가 높다는 것은 이 열 가지를 함께 봤을 때 고양이 기준과의 거리가 가장 짧다는 뜻입니다. 눈만 크다고 고양이상이 되지는 않습니다. 코와 입이 넓으면 곰이나 사자 기준이 더 가까울 수 있습니다.","cat_p4":"웃으면 입이 넓어져 강아지나 사자 쪽으로 기울 수 있습니다. 고개를 옆으로 돌리면 눈 크기가 실제보다 작아 보입니다. 정면에서 입을 다문 사진이 이 기준과 비교하기 좋습니다.","dog_title":"강아지상 — 동물상 도감","dog_meta":"눈이 둥글고 입이 넓어, 표정이 순하고 친근해 보이는 기준입니다.","dog_h1":"강아지상","dog_p1":"강아지상은 눈이 둥글고 입이 넓어 표정이 순해 보이는 인상입니다. 코는 평균 근처에 두고, 얼굴 전체는 약간 둥근 쪽을 강아지 기준에 가깝다고 봅니다.","dog_p2":"눈매, 곧 눈 세로를 눈 가로로 나눈 값이 둥근 편이고 입 가로가 얼굴에서 넓을 때 강아지 기준에 가깝습니다. 눈 사이도 약간 넓은 쪽을 함께 봅니다.","dog_p3":"입이 넓다고 바로 강아지상은 아닙니다. 코와 턱까지 넓으면 사자나 곰이 더 가깝고, 눈매가 가늘면 여우나 늑대 쪽으로 갑니다.","dog_p4":"활짝 웃는 사진은 입 비율이 커집니다. 평소 인상이 알고 싶다면 입을 다문 사진도 한 장 같이 재 보세요.","fox_title":"여우상 — 동물상 도감","fox_meta":"얼굴 선이 길고 턱끝이 가늘며 눈매가 날렵한 기준입니다.","fox_h1":"여우상","fox_p1":"여우상은 얼굴 선이 길고 턱끝이 가늘며 눈매가 날렵한 인상입니다. 사슴처럼 눈만 큰 긴 얼굴과는 눈의 모양으로 갈라집니다.","fox_p2":"얼굴 세로가 가로보다 길고, 눈매가 가늘며, 턱끝 가로가 좁을 때 여우 기준에 가깝습니다. 코는 가로가 좁고 길이는 긴 쪽, 눈 사이는 약간 가까운 쪽입니다.","fox_p3":"사슴상도 얼굴이 길고 턱이 가늘지만, 사슴은 눈이 큰 쪽을 보고 여우는 눈매가 가늘고 날카로운 쪽을 봅니다. 둘의 점수가 비슷하면 눈 모양을 같이 보세요.","fox_p4":"옆얼굴은 턱끝이 더 가늘어 보입니다. 머리카락으로 턱을 가리면 턱끝 비율을 읽지 못합니다. 턱선이 보이는 정면 사진이 맞습니다.","rabbit_title":"토끼상 — 동물상 도감","rabbit_meta":"눈이 크고 코와 입이 작아, 인상이 둥글고 부드러운 기준입니다.","rabbit_h1":"토끼상","rabbit_p1":"토끼상은 눈이 크고 코와 입이 작아 인상이 둥글고 부드러운 쪽입니다. 이 도감에서 눈 크기를 크게 보는 기준 가운데 하나입니다.","rabbit_p2":"얼굴은 둥글고, 눈 가로와 눈매의 둥글기가 크며, 눈 사이도 약간 넓습니다. 코 가로와 코 길이, 입 가로는 작고, 중안부는 짧습니다.","rabbit_p3":"부엉이상도 눈이 크고 얼굴이 둥급니다. 부엉이는 눈 사이가 더 넓고 얼굴 윤곽이 더 원형인 쪽이고, 토끼는 코와 입이 작으면서 눈이 큰 쪽입니다.","rabbit_p4":"눈을 크게 뜨면 눈 세로가 늘어 토끼나 부엉이 쪽으로 움직일 수 있습니다. 평소 크기라면 자연스럽게 뜬 사진이 맞습니다.","owl_title":"부엉이상 — 동물상 도감","owl_meta":"얼굴이 아주 둥글고 눈이 크며 눈 사이가 넓은 기준입니다.","owl_h1":"부엉이상","owl_p1":"부엉이상은 얼굴이 아주 둥글고 눈이 커서 이목구비가 동그랗게 띄는 인상입니다. 아홉 기준 가운데 얼굴 둥글기를 가장 크게 봅니다.","owl_p2":"얼굴 둥글기, 눈 크기, 눈매의 둥글기, 눈 사이 간격을 모두 큰 쪽으로 봅니다. 코와 입은 작고 짧으며, 턱끝은 부드러운 넓은 쪽입니다. 중안부는 짧습니다.","owl_p3":"토끼와 점수가 겹치기 쉽습니다. 눈 사이가 넓고 얼굴 윤곽이 원에 가까우면 부엉이 쪽입니다. 코와 입만 작고 얼굴 길이가 남아 있으면 토끼나 고양이를 같이 봅니다.","owl_p4":"광각 렌즈로 아주 가까이 찍으면 얼굴 가운데가 둥글게 왜곡됩니다. 팔을 편 거리 이상에서 찍으면 윤곽이 덜 부풀습니다.","bear_title":"곰상 — 동물상 도감","bear_meta":"얼굴과 코, 턱이 넓고 눈은 작은 기준입니다.","bear_h1":"곰상","bear_p1":"곰상은 얼굴과 코, 턱이 넓고 눈은 작아 든든하고 너그러워 보이는 인상입니다. 눈의 크기보다 얼굴의 폭을 더 봅니다.","bear_p2":"코 가로, 턱 가로, 턱끝이 평균보다 넓고 눈 크기는 작은 쪽입니다. 입도 약간 넓습니다. 중안부는 평균 근처에 둡니다.","bear_p3":"사자상도 코와 턱이 넓습니다. 사자는 입과 턱의 존재감이 더 크고, 눈이 아주 작을 필요는 없습니다. 눈이 작고 얼굴 폭이 전체적으로 넓으면 곰에 더 가깝습니다.","bear_p4":"수염이나 마스크, 손은 코와 턱의 경계를 가립니다. 코끝과 턱선이 보이게 찍어 주세요.","lion_title":"사자상 — 동물상 도감","lion_meta":"코와 입, 턱이 넓어 이목구비의 폭이 큰 기준입니다.","lion_h1":"사자상","lion_p1":"사자상은 코와 입, 턱이 넓어 이목구비가 진하고 존재감이 커 보이는 인상입니다. 눈의 크기나 얼굴의 길이보다 아래쪽 폭을 봅니다.","lion_p2":"코 가로, 입 가로, 턱 가로를 넓은 쪽으로 봅니다. 눈 크기는 평균보다 약간 작고, 얼굴 전체의 둥글기는 평균에서 크게 벗어나지 않습니다.","lion_p3":"강아지상도 입이 넓지만 눈매가 둥글고 친근한 쪽입니다. 사자상은 눈보다 코, 입, 턱의 폭이 점수를 끌어갑니다.","lion_p4":"웃거나 말을 하는 순간은 입이 더 넓어집니다. 입을 다문 사진과 비교하면 표정이 만든 차이인지 알 수 있습니다.","deer_title":"사슴상 — 동물상 도감","deer_meta":"얼굴이 길고 눈은 크며 턱과 턱끝이 가는 기준입니다.","deer_h1":"사슴상","deer_p1":"사슴상은 얼굴이 길고 눈은 크며 턱이 가늘어 선이 가늘고 순해 보이는 인상입니다. 긴 얼굴 가운데서 눈이 큰 쪽을 사슴으로 봅니다.","deer_p2":"얼굴 세로는 길고, 눈은 크며, 코는 좁고, 턱과 턱끝은 가늘고, 중안부는 긴 쪽입니다. 눈매 자체는 여우처럼 가늘지 않아도 됩니다.","deer_p3":"여우와 늑대도 긴 얼굴입니다. 사슴은 눈이 크고 턱이 가는 조합이고, 늑대는 눈이 가늘고 중안부가 긴 조합입니다.","deer_p4":"위에서 내려다보는 각도는 턱을 짧게 만듭니다. 카메라와 눈이 같은 높이일 때 얼굴 세로가 덜 왜곡됩니다.","wolf_title":"늑대상 — 동물상 도감","wolf_meta":"눈매가 가늘고 중안부와 코 길이가 긴 기준입니다.","wolf_h1":"늑대상","wolf_p1":"늑대상은 눈매가 가늘고 중안부가 길어 얼굴선이 날카로워 보이는 인상입니다. 입은 평균 근처에 두고, 눈과 코의 거리로 긴 얼굴을 읽습니다.","wolf_p2":"눈 세로가 짧고, 눈 사이는 가까우며, 코 길이와 눈에서 코끝까지의 거리가 깁니다. 얼굴도 긴 편이고 턱끝은 가늘게 봅니다.","wolf_p3":"여우상과 자주 이웃합니다. 여우는 턱끝이 더 가늘고 코 가로가 더 좁은 쪽이고, 늑대는 눈매와 중안부의 길이 비중이 더 큽니다.","wolf_p4":"눈을 가늘게 뜨면 눈매 비율만으로 늑대 쪽이 올라갈 수 있습니다. 평소 뜨는 정도로 찍어 주세요."},"en":{"nav_label":"Guide menu","nav_tool":"Measure a face","nav_method":"How measuring works","nav_about":"About","nav_privacy":"Privacy","nav_contact":"Contact","theme_group":"Theme","theme_light":"Light","theme_dark":"Dark","language_group":"Language","footer":"Photos are processed only in this browser and are not uploaded. The result is a playful comparison of face proportions, not a scientific or personality test. Expression, angle, glasses, and lighting can change the ranking.","try_tool":"Measure a face with this guide","read_method":"Read how the ten ratios are measured","other_animals":"Other animal profiles","animal_ratio_heading":"Ratios that lean this way","animal_score_heading":"What a close score means","animal_photo_heading":"When the photo moves the rank","name_cat":"Cat face","name_dog":"Puppy face","name_fox":"Fox face","name_rabbit":"Rabbit face","name_owl":"Owl face","name_bear":"Bear face","name_lion":"Lion face","name_deer":"Deer face","name_wolf":"Wolf face","method_title":"How measuring works — Animal Face Field Guide","method_meta":"Explains how face, eye, nose, mouth, and jaw length ratios are measured and compared with nine animal profiles.","method_h1":"How measuring works","method_lead":"This guide does not look at hair, ears, or clothes. It reads lengths on the face in the photo and compares only those lengths divided by the size of the face. Pixel counts change with distance, so the raw pixel count is not the score.","method_measure":"The analysis runs in this browser. The photo is not sent to a server. If several faces are in the area you chose, the largest one is used. The averages below are this guide's starting point for a front-facing photo. They are not a medical normal range.","method_ratios_heading":"The ten ratios","method_r1":"Face shape. Face width divided by face height. A larger number is a wider face, and a smaller number is a longer face. This guide's average is 0.82.","method_r2":"Eye size. Eye width divided by face width. 0.20 means the eye width is 20% of the face width.","method_r3":"Eye shape. Eye height divided by eye width. Larger is rounder, smaller is narrower and sharper. The average here is 0.33.","method_r4":"Eye gap. The distance between the eyes divided by face width. The average is near 0.25.","method_r5":"Nose width. Nose width divided by face width. The average is near 0.28.","method_r6":"Nose length. Nose length divided by face height. The average is 0.30.","method_r7":"Mouth width. Mouth width divided by face width. The average is near 0.40.","method_r8":"Jaw width. The wider part of the jaw divided by face width. The average is 0.80.","method_r9":"Chin. Chin width divided by face width. The average is 0.32.","method_r10":"Midface. The length from the eyes to the tip of the nose divided by face height. The average is 0.25.","method_score_heading":"How the score is made","method_score":"Each ratio is turned into a distance from the average, then compared with the profile set for each animal. Features that shape the impression, such as eye size, count a little more. Features that shift easily from photo to photo, such as the chin tip, count less. The closest animal gets the higher score. The score stops at 94. It never shows 100, so one photo's error is not presented as a perfect match.","method_photo_heading":"When the same person gets another rank","method_photo":"Turning the head, squeezing the eyes, a wide smile, very dim light, or a tiny face in the frame can change the rank. A front-facing photo, with the eyes level with the camera and the mouth closed, is easier to compare. Glasses frames that cover the outer eye can make the eye length wrong. A very close wide-angle shot makes the middle of the face look rounder.","method_animals_heading":"The nine animal profiles","method_animals":"Each animal looks for a different mix of larger and smaller ratios. Select a name to read that profile on its own. The pages do not repeat one paragraph with only the animal name changed.","about_title":"About — Animal Face Field Guide","about_meta":"What Animal Face Field Guide compares, where the photo stays, and how to read the result.","about_h1":"About this guide","about_p1":"Animal Face Field Guide is a browser program that compares length ratios in a face photo with profiles for a cat, puppy, fox, rabbit, owl, bear, lion, deer, and wolf. It promises one thing: measure the ratios in the area you choose, and show which of the nine profiles is closest.","about_p2":"The photo file is read only in this browser and is not uploaded to an analysis server. When you close the page, the photo goes with it. The only things kept on this device are the language you chose and the light or dark theme.","about_p3":"The result is a playful comparison. The tool was not built to describe personality, or for medicine, genetics, or identity checks. Questions about the site, errors, or privacy go to the contact page.","privacy_title":"Privacy — Animal Face Field Guide","privacy_meta":"How face photos, language settings, ads, comments, and the contact form each handle information.","privacy_h1":"Privacy","privacy_photo_heading":"Face photos","privacy_photo":"A face photo taken with the camera or uploaded for analysis is handled only in this browser's memory. It is not sent to an Animal Face Field Guide server and it is not saved to an account. When you close the page or choose another photo, the previous photo is not kept.","privacy_store_heading":"Settings kept on this device","privacy_store":"The chosen language is stored in this browser under the name language_code, and the light or dark theme under theme_mode. Those values only restore the same view on the next visit. They are not sent with the face photo.","privacy_ads_heading":"Advertising","privacy_ads":"This site uses Google AdSense auto ads. When an ad is shown, Google can use cookies or similar identifiers to choose and measure ads. Google's description of information used for ads is at https://policies.google.com/technologies/ads . For site ownership, the publisher id ca-pub-8803401825336300 is in a meta tag in the page head and in ads.txt at the site root.","privacy_disqus_heading":"Comments","privacy_disqus":"Comments appear only at the bottom of the measure page and are handled by Disqus. Writing a comment needs a Disqus login or signup, and Disqus can use its own cookies. Comment text is stored apart from face photos. Disqus describes its privacy practices at https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Contact form","privacy_form":"Only when you press send on the contact page are your name, company or brand, reply email, and message delivered to Formspree (https://formspree.io). The face photo is not part of those fields. If you do not send the form, the text you were typing is not stored.","privacy_font_heading":"Fonts","privacy_font":"The typefaces are loaded from Google Fonts. When the page opens, the browser requests font files from fonts.googleapis.com and fonts.gstatic.com. That request can include the page address and usual browser information.","privacy_ask_heading":"Questions","privacy_ask":"If something here is missing or wrong, tell us on the contact page. Face photos are not on a server, so there is no file to return. Comment removal is handled in Disqus. A request to delete an inquiry you already sent can be made through the contact page and the inbox that received it.","contact_title":"Contact — Animal Face Field Guide","contact_meta":"Contact page for partnership, error, and privacy questions about Animal Face Field Guide.","contact_h1":"Contact","contact_help":"Leave a partnership, error, or privacy question. The face photo is not attached to this form. The reply goes to the email you enter.","contact_name":"Name","contact_company":"Company or brand","contact_email":"Email for the reply","contact_message":"Message","contact_send":"Send message","contact_subject":"Animal Face Field Guide inquiry","contact_invalid":"Enter your name, reply email, and message, then send again.","contact_sending":"Sending your message.","contact_sent":"Your message was sent. We will reply to the email you entered.","contact_fail":"The message could not be sent. Please try again in a moment.","contact_network":"The message could not be sent. Check your connection and try again.","contact_teaser_title":"Contact","contact_teaser":"Questions about partnerships, errors, or privacy go on the contact page. The reply is sent to the email you enter. Face photos are not included in the message.","atlas_help":"Select an animal name to read its profile. You can browse the guide without a face photo.","lead":"The comparison uses length ratios of the face, eyes, nose, mouth, and jaw, not hair or ears. The score is the distance from nine animal profiles. It is not a personality test or a scientific classification.","cat_title":"Cat face — Animal Face Field Guide","cat_meta":"A profile for large eyes with a small nose and mouth, so the features look gathered toward the center.","cat_h1":"Cat face","cat_p1":"A cat face is the impression that the eyes, nose, and mouth sit toward the middle of the face. This guide's cat profile gets closer when the face is a little round, the eyes are large, and the nose and mouth are smaller than average.","cat_p2":"Face width is generous compared with face height, and the eyes take up more of the face width. A narrower and shorter nose, and a smaller mouth, lean toward the cat. The midface, from the eyes to the nose tip, is on the short side.","cat_p3":"A high score means that, taken together, the ten ratios are closest to the cat profile. Large eyes alone do not make a cat face. A wide nose and mouth can sit closer to the bear or lion profile.","cat_p4":"A smile widens the mouth and can lean the result toward the puppy or lion. Turning the head makes the eyes look smaller than they are. A front-facing photo with the mouth closed is the easier comparison for this profile.","dog_title":"Puppy face — Animal Face Field Guide","dog_meta":"A profile for round eyes and a wide mouth, the look this guide treats as gentle and friendly.","dog_h1":"Puppy face","dog_p1":"A puppy face is the impression of round eyes and a wide mouth, so the expression looks gentle. The nose stays near average, and a slightly round face sits closer to the puppy profile.","dog_p2":"The puppy profile is closer when the eye shape, eye height divided by eye width, is round and the mouth is wide on the face. A slightly wider gap between the eyes is part of the same reading.","dog_p3":"A wide mouth by itself is not a puppy face. If the nose and jaw are wide as well, the lion or bear can be closer. Narrow eyes move the result toward the fox or wolf.","dog_p4":"A big smile increases the mouth ratio. If you want the everyday impression, measure a photo with the mouth closed as well.","fox_title":"Fox face — Animal Face Field Guide","fox_meta":"A profile for a long face, a narrow chin, and sharp eyes.","fox_h1":"Fox face","fox_p1":"A fox face is a long outline, a narrow chin, and sharp eyes. It separates from a long face with large eyes, such as the deer, by the shape of the eyes.","fox_p2":"The fox profile is closer when face height exceeds face width, the eyes are narrow, and the chin tip is slim. The nose is narrow but long, and the eyes sit a little closer together.","fox_p3":"The deer profile is also a long face with a narrow jaw, but the deer looks for larger eyes and the fox looks for narrow, sharp eyes. If the two scores are close, read the eye shape with them.","fox_p4":"A side view makes the chin look even narrower. Hair that covers the chin hides the chin ratio. A front-facing photo with the jawline visible is the one to use.","rabbit_title":"Rabbit face — Animal Face Field Guide","rabbit_meta":"A profile for large eyes and a small nose and mouth, read here as a round, soft impression.","rabbit_h1":"Rabbit face","rabbit_p1":"A rabbit face has large eyes and a small nose and mouth, so the impression is round and soft. It is one of the profiles in this guide that looks hardest at eye size.","rabbit_p2":"The face is round, the eyes are wide, the eye shape is round, and the gap between the eyes is a little wide. Nose width, nose length, and mouth width are small, and the midface is short.","rabbit_p3":"The owl profile also has large eyes and a round face. The owl leans further toward a wide eye gap and a more circular outline. The rabbit leans toward large eyes with a small nose and mouth.","rabbit_p4":"Opening the eyes very wide increases eye height and can move the result toward the rabbit or owl. For an everyday size, a photo with the eyes open naturally is the better one.","owl_title":"Owl face — Animal Face Field Guide","owl_meta":"A profile for a very round face, large eyes, and a wide gap between the eyes.","owl_h1":"Owl face","owl_p1":"An owl face is a very round face with large eyes, so the features read as circular. Among the nine profiles, this one gives face roundness the strongest pull.","owl_p2":"Face roundness, eye size, round eye shape, and the gap between the eyes are all read on the large side. The nose and mouth are small and short, the chin tip is softly wide, and the midface is short.","owl_p3":"The score often sits near the rabbit. A wide eye gap and an outline close to a circle lean owl. If only the nose and mouth are small and some face length remains, read the rabbit and cat alongside it.","owl_p4":"A very close wide-angle shot distorts the middle of the face into a rounder shape. From at least an arm's length, the outline inflates less.","bear_title":"Bear face — Animal Face Field Guide","bear_meta":"A profile for a wide face, nose, and jaw with smaller eyes.","bear_h1":"Bear face","bear_p1":"A bear face is a wide face, nose, and jaw with smaller eyes, the impression this guide reads as solid and easygoing. It looks more at the width of the face than at eye size.","bear_p2":"Nose width, jaw width, and the chin are wider than average, and eye size is on the small side. The mouth is a little wide. The midface stays near the average.","bear_p3":"The lion profile also has a wide nose and jaw. The lion puts more weight on the mouth and jaw, and the eyes do not need to be very small. Small eyes with width across the whole face sit closer to the bear.","bear_p4":"A beard, a mask, or a hand hides the edge of the nose and jaw. Take the photo so the nose tip and jawline are visible.","lion_title":"Lion face — Animal Face Field Guide","lion_meta":"A profile for a wide nose, mouth, and jaw, so the features read as broad.","lion_h1":"Lion face","lion_p1":"A lion face has a wide nose, mouth, and jaw, so the features look strong. This profile looks at the width of the lower face more than at eye size or face length.","lion_p2":"Nose width, mouth width, and jaw width are read on the wide side. Eye size is a little smaller than average, and the roundness of the whole face does not leave the average by much.","lion_p3":"The puppy profile also has a wide mouth, but with round, friendly eyes. The lion score is pulled by the width of the nose, mouth, and jaw more than by the eyes.","lion_p4":"Smiling or speaking makes the mouth wider. Compare it with a closed-mouth photo to see whether the expression created the difference.","deer_title":"Deer face — Animal Face Field Guide","deer_meta":"A profile for a long face, large eyes, and a narrow jaw and chin.","deer_h1":"Deer face","deer_p1":"A deer face is a long face with large eyes and a narrow jaw, a fine and gentle line in this guide. Among long faces, the one with larger eyes is read as the deer.","deer_p2":"Face height is long, the eyes are large, the nose is narrow, the jaw and chin tip are slim, and the midface is long. The eye shape does not have to be as narrow as the fox.","deer_p3":"The fox and the wolf are long faces too. The deer is the combination of large eyes and a slim jaw. The wolf is the combination of narrow eyes and a long midface.","deer_p4":"A camera looking down shortens the jaw. When the camera is level with the eyes, face height is distorted less.","wolf_title":"Wolf face — Animal Face Field Guide","wolf_meta":"A profile for narrow eyes and a long midface and nose.","wolf_h1":"Wolf face","wolf_p1":"A wolf face has narrow eyes and a long midface, so the outline looks sharp. The mouth stays near average, and the long face is read from the distance between the eyes and the nose.","wolf_p2":"Eye height is short, the eyes sit closer together, and both the nose and the span from the eyes to the nose tip are long. The face is on the long side, and the chin tip is read as narrow.","wolf_p3":"The fox profile is often the neighbor. The fox puts more weight on a slimmer chin tip and a narrower nose. The wolf puts more weight on narrow eyes and midface length.","wolf_p4":"Squinting can raise the wolf side from the eye-shape ratio alone. Take the photo with the eyes open as they usually are."},"ja":{"nav_label":"図鑑メニュー","nav_tool":"顔を測る","nav_method":"測り方","nav_about":"紹介","nav_privacy":"個人情報","nav_contact":"問い合わせ","theme_group":"画面モード","theme_light":"ライト","theme_dark":"ダーク","language_group":"言語","footer":"写真はこのブラウザの中だけで処理され、サーバーには送られません。結果は顔の比率を動物の基準と比べた遊びであり、科学的な判定や性格テストではありません。表情、角度、眼鏡、照明で順位は変わることがあります。","try_tool":"この基準で顔を測る","read_method":"10個の比率の測り方を読む","other_animals":"ほかの動物の基準","animal_ratio_heading":"この動物に傾く比率","animal_score_heading":"点数が高いという意味","animal_photo_heading":"写真で順位が揺れるとき","name_cat":"猫顔","name_dog":"犬顔","name_fox":"狐顔","name_rabbit":"兎顔","name_owl":"フクロウ顔","name_bear":"熊顔","name_lion":"ライオン顔","name_deer":"鹿顔","name_wolf":"狼顔","method_title":"測り方 — 動物顔図鑑","method_meta":"顔の縦横、目、鼻、口、顎の長さの比率をどう測り、9種の動物基準と比べるかを説明します。","method_h1":"測り方","method_lead":"この図鑑は髪、耳、服装を見ません。写真の顔から長さを読み、その長さを顔の大きさで割った比率だけを比べます。同じ人でも距離が変わると画素数は変わるので、画素そのものは点数にしません。","method_measure":"分析はこのブラウザの中で行われ、写真はサーバーへ送りません。選んだ範囲に顔が複数あれば、いちばん大きく見える顔を基準にします。下の平均は、正面写真でよくある出発点としてこの図鑑が置いた値であり、医学的な正常範囲ではありません。","method_ratios_heading":"10個の比率","method_r1":"顔の形。顔の横幅を縦の長さで割ります。数が大きいと横に広い顔、小さいと縦に長い顔です。この図鑑の平均は0.82です。","method_r2":"目の大きさ。目の横幅を顔の横幅で割ります。0.20は、目の横幅が顔の横幅の20%という意味です。","method_r3":"目つき。目の縦を横で割ります。大きいと丸い目、小さいと細く鋭い目です。平均は0.33です。","method_r4":"目と目の間。両目の間の距離を顔の横幅で割ります。平均は0.25に近いです。","method_r5":"鼻の幅。鼻の横幅を顔の横幅で割ります。平均は0.28に近いです。","method_r6":"鼻の長さ。鼻の長さを顔の縦で割ります。平均は0.30です。","method_r7":"口の幅。口の横幅を顔の横幅で割ります。平均は0.40に近いです。","method_r8":"顎の幅。顎の広い位置の横幅を顔の横幅で割ります。平均は0.80です。","method_r9":"あご先。あご先の横幅を顔の横幅で割ります。平均は0.32です。","method_r10":"中顔面。目から鼻先までの長さを顔の縦で割ります。平均は0.25です。","method_score_heading":"点数の出方","method_score":"10個の比率を平均からの距離に変えて、動物ごとに決めた基準との距離を測ります。目の大きさのように印象を左右する項目は少し重く、あご先のように写真ごとに揺れやすい項目は軽く見ます。いちばん近い動物に高い点数を出します。点数の上限は94です。100にしないのは、写真1枚の誤差を完全な一致のように見せないためです。","method_photo_heading":"同じ人でも順位が変わるとき","method_photo":"顔を横に向ける、目を細める、大きく笑う、暗すぎる照明、顔がとても小さく写った写真では順位が変わることがあります。できれば目がカメラと同じ高さの正面で、口を閉じた写真と比べてください。眼鏡の縁が目尻を隠すと、目の長さを読み間違えることがあります。広角でごく近くから撮ると、顔の中央が丸く膨らんで見えます。","method_animals_heading":"9種の動物の基準","method_animals":"動物ごとに、どの比率を大きく、または小さく見るかが違います。名前を押すと、その動物の基準だけを読めます。同じ文の動物名だけを入れ替えたページにはしていません。","about_title":"紹介 — 動物顔図鑑","about_meta":"動物顔図鑑が何を比べ、写真をどこに置くか、結果をどう読むかを書きます。","about_h1":"この図鑑について","about_p1":"動物顔図鑑は、顔写真の長さの比率を猫、犬、狐、兎、フクロウ、熊、ライオン、鹿、狼の基準と比べるブラウザのプログラムです。訪れた人に約束することは一つです。選んだ顔の範囲の比率を測り、9つの基準のどこに近いかを見せることです。","about_p2":"写真ファイルはこのブラウザの中だけで読み、分析サーバーには上げません。ページを閉じると、その写真も一緒に消えます。この機器に残るのは、選んだ言語とライト・ダークの画面モードだけです。","about_p3":"結果は遊びとしての比較です。性格を教えたり、医学、遺伝、本人確認に使うために作った道具ではありません。運営、不具合、個人情報についての連絡は問い合わせページで受けます。","privacy_title":"個人情報 — 動物顔図鑑","privacy_meta":"顔写真、言語設定、広告、コメント、問い合わせフォームがそれぞれどの情報を扱うかを書きます。","privacy_h1":"個人情報","privacy_photo_heading":"顔写真","privacy_photo":"カメラで撮った、または読み込んだ顔写真は、分析のためにこのブラウザのメモリの中だけで扱います。動物顔図鑑のサーバーへは送らず、アカウントにも保存しません。ページを閉じるか別の写真に替えると、前の写真は残りません。","privacy_store_heading":"この機器に残る設定","privacy_store":"選んだ言語は language_code という名前で、ライトまたはダークは theme_mode という名前で、このブラウザのローカルストレージに残ります。これは次の訪問で同じ画面を出すための値であり、顔写真と一緒には送りません。","privacy_ads_heading":"広告","privacy_ads":"このサイトは Google アドセンスの自動広告を使います。広告が表示されると、Google はクッキーに似た識別値を使って広告を選び、測定することがあります。広告に使う情報についての Google の説明は https://policies.google.com/technologies/ads にあります。サイトの所有者確認のため、ページ先頭のメタタグとルートの ads.txt にパブリッシャー番号 ca-pub-8803401825336300 を書いてあります。","privacy_disqus_heading":"コメント","privacy_disqus":"コメントは顔を測るページの下だけにあり、Disqus が処理します。コメントを書くには Disqus 側のログインまたは登録が必要で、Disqus が独自のクッキーを使うことがあります。コメントの内容は顔写真とは別に保存されます。Disqus の個人情報の案内は https://help.disqus.com/en/articles/1717103-disqus-privacy-policy にあります。","privacy_form_heading":"問い合わせフォーム","privacy_form":"問い合わせページで送信を押したときだけ、名前、会社またはブランド、返信先メール、内容が Formspree（https://formspree.io）へ届きます。顔写真はこの項目に含まれません。送らなければ、フォームに書いていた文も保存されません。","privacy_font_heading":"フォント","privacy_font":"画面のフォントは Google Fonts から読み込みます。ページを開くとき、ブラウザは fonts.googleapis.com と fonts.gstatic.com にフォントファイルを要求します。その要求には、通常、見ているアドレスとブラウザの情報が含まれることがあります。","privacy_ask_heading":"質問","privacy_ask":"この案内に抜けや誤りがあれば、問い合わせページで知らせてください。顔写真はサーバーにないので、返すファイルはありません。コメントの削除は Disqus で、すでに送った問い合わせメールの削除は、受け取った側と問い合わせページから依頼できます。","contact_title":"問い合わせ — 動物顔図鑑","contact_meta":"動物顔図鑑の提携、不具合、個人情報についての質問を受ける問い合わせページです。","contact_h1":"問い合わせ","contact_help":"提携、不具合、個人情報についての質問を残してください。顔写真はこのフォームには付きません。返信は記入したメールへ届きます。","contact_name":"名前","contact_company":"会社またはブランド","contact_email":"返信先メール","contact_message":"問い合わせ内容","contact_send":"送信する","contact_subject":"動物顔図鑑 問い合わせ","contact_invalid":"名前、返信先メール、内容を入力してからもう一度送ってください。","contact_sending":"問い合わせを送っています。","contact_sent":"問い合わせを送りました。記入したメールへ返信します。","contact_fail":"問い合わせを送れませんでした。しばらくしてからもう一度試してください。","contact_network":"問い合わせを送れませんでした。通信を確認してからもう一度試してください。","contact_teaser_title":"問い合わせ","contact_teaser":"提携、不具合、個人情報についての質問は問い合わせページに残してください。返信は記入したメールへ届きます。顔写真は問い合わせに含まれません。","atlas_help":"動物の名前を押すと、その基準を文章で読めます。顔写真がなくても図鑑を見られます。","lead":"比べる値は髪や耳ではなく、顔の縦横と目、鼻、口、顎の長さの比率です。点数は9種の動物基準との距離であり、性格テストや科学的な判定ではありません。","cat_title":"猫顔 — 動物顔図鑑","cat_meta":"目が大きく鼻と口が小さく、パーツが顔の中央に集まる基準です。","cat_h1":"猫顔","cat_p1":"猫顔は、目と鼻と口が顔の中央に集まって見える印象です。この図鑑の猫の基準は、顔が少し丸く、目が大きく、鼻と口が平均より小さいときに近くなります。","cat_p2":"顔の横幅が縦に比べて余裕があり、目の横幅が顔に占める割合が大きいです。鼻の幅、鼻の長さ、口の幅は平均より小さいほうを猫に寄せます。目から鼻先までの中顔面も短めです。","cat_p3":"点数が高いのは、10個を一緒に見たとき猫の基準との距離がいちばん短いという意味です。目が大きいだけでは猫顔になりません。鼻と口が広いと、熊やライオンの基準のほうが近いことがあります。","cat_p4":"笑うと口が広がり、犬やライオンのほうへ傾くことがあります。顔を横に向けると、目の大きさが実際より小さく見えます。正面で口を閉じた写真が、この基準とは比べやすいです。","dog_title":"犬顔 — 動物顔図鑑","dog_meta":"目が丸く口が広く、表情が穏やかで親しみやすく見える基準です。","dog_h1":"犬顔","dog_p1":"犬顔は、目が丸く口が広く、表情が穏やかに見える印象です。鼻は平均の近くに置き、顔全体が少し丸いほうを犬の基準に近いと見ます。","dog_p2":"目つき、つまり目の縦を横で割った値が丸めで、口の横幅が顔の中で広いときに犬の基準に近くなります。目と目の間が少し広いほうも一緒に見ます。","dog_p3":"口が広いだけでは犬顔にはなりません。鼻と顎まで広いとライオンや熊のほうが近く、目つきが細いと狐や狼のほうへ行きます。","dog_p4":"大きく笑った写真は口の比率が大きくなります。いつもの印象を知りたければ、口を閉じた写真も一枚一緒に測ってください。","fox_title":"狐顔 — 動物顔図鑑","fox_meta":"顔の線が長く、あご先が細く、目つきが鋭い基準です。","fox_h1":"狐顔","fox_p1":"狐顔は、顔の線が長く、あご先が細く、目つきが鋭い印象です。鹿のように目だけが大きい長い顔とは、目の形で分かれます。","fox_p2":"顔の縦が横より長く、目つきが細く、あご先の横幅が狭いときに狐の基準に近くなります。鼻は幅が狭く長さは長いほう、目と目の間は少し近いほうです。","fox_p3":"鹿顔も顔が長く顎が細いですが、鹿は目が大きいほうを見て、狐は目つきが細く鋭いほうを見ます。二つの点数が近いときは、目の形も一緒に見てください。","fox_p4":"横顔はあご先がさらに細く見えます。髪であごを隠すと、あご先の比率は読めません。顎の線が見える正面の写真が向いています。","rabbit_title":"兎顔 — 動物顔図鑑","rabbit_meta":"目が大きく鼻と口が小さく、印象が丸く柔らかい基準です。","rabbit_h1":"兎顔","rabbit_p1":"兎顔は、目が大きく鼻と口が小さく、印象が丸く柔らかいほうです。この図鑑で目の大きさを大きく見る基準の一つです。","rabbit_p2":"顔は丸く、目の横幅と目つきの丸みが大きく、目と目の間も少し広いです。鼻の幅と長さ、口の幅は小さく、中顔面は短いです。","rabbit_p3":"フクロウ顔も目が大きく顔が丸いです。フクロウは目と目の間がさらに広く、顔の輪郭がより円に近いほうです。兎は鼻と口が小さく、目が大きいほうです。","rabbit_p4":"目を大きく見開くと目の縦が伸び、兎やフクロウのほうへ動くことがあります。いつもの大きさなら、自然に開いた写真が向いています。","owl_title":"フクロウ顔 — 動物顔図鑑","owl_meta":"顔がとても丸く、目が大きく、目と目の間が広い基準です。","owl_h1":"フクロウ顔","owl_p1":"フクロウ顔は、顔がとても丸く目が大きく、パーツが丸く目立つ印象です。9つの基準の中で、顔の丸みをいちばん大きく見ます。","owl_p2":"顔の丸み、目の大きさ、目つきの丸み、目と目の間隔をすべて大きいほうに見ます。鼻と口は小さく短く、あご先は柔らかく広いほうです。中顔面は短いです。","owl_p3":"兎と点数が重なりやすいです。目と目の間が広く、顔の輪郭が円に近いとフクロウのほうです。鼻と口だけが小さく、顔の長さが残るなら兎や猫も一緒に見てください。","owl_p4":"広角レンズでごく近くから撮ると、顔の中央が丸く歪みます。腕を伸ばした距離以上から撮ると、輪郭は膨らみにくくなります。","bear_title":"熊顔 — 動物顔図鑑","bear_meta":"顔と鼻、顎が広く、目は小さい基準です。","bear_h1":"熊顔","bear_p1":"熊顔は、顔と鼻、顎が広く目は小さく、どっしりしておおらかに見える印象です。目の大きさより顔の幅をよく見ます。","bear_p2":"鼻の幅、顎の幅、あご先が平均より広く、目の大きさは小さいほうです。口も少し広いです。中顔面は平均の近くに置きます。","bear_p3":"ライオン顔も鼻と顎が広いです。ライオンは口と顎の存在感がより大きく、目がとても小さい必要はありません。目が小さく、顔の幅が全体に広いと熊に近くなります。","bear_p4":"ひげ、マスク、手は鼻と顎の境目を隠します。鼻先と顎の線が見えるように撮ってください。","lion_title":"ライオン顔 — 動物顔図鑑","lion_meta":"鼻と口、顎が広く、パーツの幅が大きい基準です。","lion_h1":"ライオン顔","lion_p1":"ライオン顔は、鼻と口、顎が広く、パーツが濃く存在感が大きく見える印象です。目の大きさや顔の長さより、下のほうの幅を見ます。","lion_p2":"鼻の幅、口の幅、顎の幅を広いほうに見ます。目の大きさは平均より少し小さく、顔全体の丸みは平均から大きく離れません。","lion_p3":"犬顔も口は広いですが、目つきが丸く親しみやすいほうです。ライオン顔は、目より鼻、口、顎の幅が点数を引き寄せます。","lion_p4":"笑ったり話したりする瞬間は口がさらに広くなります。口を閉じた写真と比べると、表情が作った差かどうかが分かります。","deer_title":"鹿顔 — 動物顔図鑑","deer_meta":"顔が長く、目は大きく、顎とあご先が細い基準です。","deer_h1":"鹿顔","deer_p1":"鹿顔は、顔が長く目は大きく顎が細く、線が細く穏やかに見える印象です。長い顔の中で、目が大きいほうを鹿と見ます。","deer_p2":"顔の縦は長く、目は大きく、鼻は狭く、顎とあご先は細く、中顔面は長いほうです。目つきそのものは、狐のように細くなくてもかまいません。","deer_p3":"狐と狼も長い顔です。鹿は目が大きく顎が細い組み合わせで、狼は目が細く中顔面が長い組み合わせです。","deer_p4":"上から見下ろす角度は顎を短くします。カメラと目が同じ高さのとき、顔の縦は歪みにくくなります。","wolf_title":"狼顔 — 動物顔図鑑","wolf_meta":"目つきが細く、中顔面と鼻の長さが長い基準です。","wolf_h1":"狼顔","wolf_p1":"狼顔は、目つきが細く中顔面が長く、顔の線が鋭く見える印象です。口は平均の近くに置き、目と鼻の距離で長い顔を読みます。","wolf_p2":"目の縦が短く、目と目の間は近く、鼻の長さと目から鼻先までの距離が長いです。顔も長めで、あご先は細く見ます。","wolf_p3":"狐顔と隣り合うことが多いです。狐はあご先がさらに細く鼻の幅がさらに狭いほうで、狼は目つきと中顔面の長さの比重がより大きいです。","wolf_p4":"目を細めると、目つきの比率だけで狼のほうが高くなることがあります。いつもの開き方で撮ってください。"},"zh":{"nav_label":"图鉴菜单","nav_tool":"测量脸部","nav_method":"测量方法","nav_about":"介绍","nav_privacy":"隐私","nav_contact":"联系","theme_group":"画面模式","theme_light":"浅色","theme_dark":"深色","language_group":"语言","footer":"照片只在这个浏览器里处理，不会上传。结果是把脸的比例和动物基准做的趣味比较，不是科学鉴定，也不是性格测试。表情、角度、眼镜和光线都可能改变排名。","try_tool":"用这个基准测量脸部","read_method":"看看十个比例是怎么量的","other_animals":"其他动物基准","animal_ratio_heading":"偏向这种动物的比例","animal_score_heading":"分数接近是什么意思","animal_photo_heading":"照片会让排名晃动的时候","name_cat":"猫相","name_dog":"小狗相","name_fox":"狐相","name_rabbit":"兔相","name_owl":"猫头鹰相","name_bear":"熊相","name_lion":"狮相","name_deer":"鹿相","name_wolf":"狼相","method_title":"测量方法 — 动物面相图鉴","method_meta":"说明脸的宽高，以及眼、鼻、嘴、下颌的长度比例如何测量，并和九种动物基准比较。","method_h1":"测量方法","method_lead":"这本图鉴不看头发、耳朵或衣服。它只读取照片里脸上的长度，再把这些长度除以脸的大小来比较。距离一变，像素数就会变，所以原始像素数不是分数。","method_measure":"分析在这个浏览器里进行。照片不会送到服务器。如果选中的区域里有好几张脸，就用最大的一张。下面的平均值是这本图鉴为正面照片设的起点，不是医学上的正常范围。","method_ratios_heading":"十个比例","method_r1":"脸型。脸宽除以脸高。数字大是更宽的脸，数字小是更长的脸。这本图鉴的平均是 0.82。","method_r2":"眼睛大小。眼宽除以脸宽。0.20 表示眼宽是脸宽的 20%。","method_r3":"眼型。眼高除以眼宽。更大更圆，更小更细更锐。这里的平均是 0.33。","method_r4":"眼距。两眼距离除以脸宽。平均接近 0.25。","method_r5":"鼻宽。鼻宽除以脸宽。平均接近 0.28。","method_r6":"鼻长。鼻长除以脸高。平均是 0.30。","method_r7":"嘴宽。嘴宽除以脸宽。平均接近 0.40。","method_r8":"下颌宽度。下颌较宽处的宽度除以脸宽。平均是 0.80。","method_r9":"下巴。下巴宽度除以脸宽。平均是 0.32。","method_r10":"中面部。眼睛到鼻尖的长度除以脸高。平均是 0.25。","method_score_heading":"分数是怎么来的","method_score":"每个比例先换成离平均有多远，再和每种动物设定的基准比距离。眼睛大小这类影响印象的项目权重大一点。下巴尖这类每张照片都容易晃的项目权重小一点。最接近的动物分数更高。分数到 94 为止。它不会显示 100，这样一张照片的误差就不会被看成完全吻合。","method_photo_heading":"同一个人排名也会变的时候","method_photo":"转头、眯眼、大笑、光线很暗，或画面里的脸很小，排名都可能变。眼睛和相机同一高度、嘴巴闭上的正面照片更好比较。镜框挡住眼尾时，眼睛长度可能读错。贴得很近的广角会让脸的中部看起来更圆。","method_animals_heading":"九种动物的基准","method_animals":"每种动物看的是不同的偏大和偏小组合。点名字可以单独读那个基准。这些页面不是只换动物名字、重复同一段话。","about_title":"介绍 — 动物面相图鉴","about_meta":"动物面相图鉴比较什么、照片留在哪里，以及结果该怎么读。","about_h1":"关于这本图鉴","about_p1":"动物面相图鉴是一个浏览器程序，把脸部照片里的长度比例和猫、小狗、狐狸、兔子、猫头鹰、熊、狮子、鹿、狼的基准比较。它对访客只承诺一件事：测量你选中区域的比例，并显示九个基准里哪一个最近。","about_p2":"照片文件只在这个浏览器里读取，不会上传到分析服务器。关掉页面，照片也一起消失。这台设备上留下的只有你选的语言，以及浅色或深色模式。","about_p3":"结果是一种趣味比较。这个工具不是为了描述性格，也不是为了医学、遗传或身份核验。网站、错误或隐私方面的问题请到联系页。","privacy_title":"隐私 — 动物面相图鉴","privacy_meta":"脸部照片、语言设置、广告、评论和联系表单各自如何处理信息。","privacy_h1":"隐私","privacy_photo_heading":"脸部照片","privacy_photo":"用相机拍下或为分析而上传的脸部照片，只在这个浏览器的内存里处理。它不会送到动物面相图鉴的服务器，也不会存进账户。关掉页面或换一张照片后，上一张不会留下。","privacy_store_heading":"留在这台设备上的设置","privacy_store":"所选语言以 language_code 存在这个浏览器里，浅色或深色模式以 theme_mode 保存。这些值只为下次打开时恢复同样的画面，不会和脸部照片一起发送。","privacy_ads_heading":"广告","privacy_ads":"本站使用 Google AdSense 自动广告。广告显示时，Google 可能用 Cookie 或类似标识来选择和衡量广告。Google 对广告所用信息的说明在 https://policies.google.com/technologies/ads 。为确认站点所有权，发布商编号 ca-pub-8803401825336300 写在页面头部的 meta 标签和站点根目录的 ads.txt 里。","privacy_disqus_heading":"评论","privacy_disqus":"评论只出现在测量页底部，由 Disqus 处理。写评论需要 Disqus 的登录或注册，Disqus 也可能使用自己的 Cookie。评论内容和脸部照片分开保存。Disqus 的隐私说明在 https://help.disqus.com/en/articles/1717103-disqus-privacy-policy 。","privacy_form_heading":"联系表单","privacy_form":"只有在联系页按下发送时，姓名、公司或品牌、回复邮箱和内容才会交给 Formspree（https://formspree.io）。脸部照片不在这些字段里。如果没有发送，正在输入的文字也不会被保存。","privacy_font_heading":"字体","privacy_font":"字体从 Google Fonts 加载。打开页面时，浏览器会向 fonts.googleapis.com 和 fonts.gstatic.com 请求字体文件。这个请求通常可能包含正在访问的地址和浏览器信息。","privacy_ask_heading":"提问","privacy_ask":"如果这里有遗漏或错误，请在联系页告诉我们。脸部照片不在服务器上，所以没有可以交还的文件。删除评论在 Disqus 里处理。已经发出的咨询邮件，可以通过联系页和收到邮件的收件箱申请删除。","contact_title":"联系 — 动物面相图鉴","contact_meta":"接收动物面相图鉴的合作、错误和隐私问题的联系页。","contact_h1":"联系","contact_help":"请留下合作、错误或隐私方面的问题。脸部照片不会附在这个表单上。回复会发到你填写的邮箱。","contact_name":"姓名","contact_company":"公司或品牌","contact_email":"回复邮箱","contact_message":"内容","contact_send":"发送","contact_subject":"动物面相图鉴咨询","contact_invalid":"请填写姓名、回复邮箱和内容，然后再发送。","contact_sending":"正在发送。","contact_sent":"已经发出。我们会回复到你填写的邮箱。","contact_fail":"没有发出去。请稍后再试。","contact_network":"没有发出去。请检查网络后再试。","contact_teaser_title":"联系","contact_teaser":"合作、错误或隐私方面的问题请写在联系页。回复会发到你填写的邮箱。脸部照片不会写进这封信。","atlas_help":"点动物名字可以读它的基准说明。没有脸部照片也可以浏览图鉴。","lead":"比较用的是脸的宽高，以及眼、鼻、嘴、下颌的长度比例，不是头发或耳朵。分数是和九种动物基准的距离，不是性格测试，也不是科学鉴定。","cat_title":"猫相 — 动物面相图鉴","cat_meta":"眼睛大，鼻子和嘴巴小，五官看起来往脸的中间聚拢的基准。","cat_h1":"猫相","cat_p1":"猫相是眼睛、鼻子和嘴巴往脸的中间靠的印象。这本图鉴的猫基准，在脸稍圆、眼睛大、鼻子和嘴巴比平均更小时会更近。","cat_p2":"脸宽相对脸高比较宽裕，眼睛占脸宽的比例更大。更窄更短的鼻子，以及更小的嘴巴，会偏向猫。从眼睛到鼻尖的中面部偏短。","cat_p3":"分数高，表示十个比例合在一起时离猫的基准最近。只有眼睛大并不会变成猫相。鼻子和嘴巴很宽时，可能更接近熊或狮子。","cat_p4":"一笑嘴巴变宽，结果可能偏向小狗或狮子。转头会让眼睛看起来比实际更小。嘴巴闭上的正面照片更容易和这个基准比较。","dog_title":"小狗相 — 动物面相图鉴","dog_meta":"眼睛圆、嘴巴宽，这本图鉴把它读成温和亲切的基准。","dog_h1":"小狗相","dog_p1":"小狗相是眼睛圆、嘴巴宽，所以表情看起来温和。鼻子留在平均附近，稍微偏圆的脸更接近小狗基准。","dog_p2":"眼型，也就是眼高除以眼宽，偏圆，而且嘴巴在脸上偏宽时，更接近小狗基准。两眼间距稍宽也算在同一次阅读里。","dog_p3":"只有嘴巴宽还不是小狗相。如果鼻子和下颌也宽，狮子或熊可能更近。眼睛细长会把结果推向狐狸或狼。","dog_p4":"大笑会增大嘴巴的比例。如果想看平时的印象，也用一张嘴巴闭上的照片量一次。","fox_title":"狐相 — 动物面相图鉴","fox_meta":"脸长、下巴尖窄、眼睛锐利的基准。","fox_h1":"狐相","fox_p1":"狐相是轮廓长、下巴尖窄、眼睛锐利。它和鹿那种眼睛很大的长脸，是靠眼睛的形状分开的。","fox_p2":"脸高超过脸宽、眼睛细、下巴尖瘦时，更接近狐的基准。鼻子窄但长，两眼也靠得稍近。","fox_p3":"鹿的基准也是长脸加窄下颌，但鹿看的是更大的眼睛，狐看的是细而锐的眼睛。如果两个分数接近，请一起看眼型。","fox_p4":"侧脸会让下巴看起来更窄。头发挡住下巴时，下巴比例读不到。请用能看见下颌线的正面照片。","rabbit_title":"兔相 — 动物面相图鉴","rabbit_meta":"眼睛大，鼻子和嘴巴小，这里把它读成圆而柔和的印象。","rabbit_h1":"兔相","rabbit_p1":"兔相是眼睛大、鼻子和嘴巴小，所以印象圆而柔和。它是这本图鉴里最看重眼睛大小的基准之一。","rabbit_p2":"脸圆，眼睛宽，眼型圆，两眼间距也稍宽。鼻宽、鼻长和嘴宽都小，中面部短。","rabbit_p3":"猫头鹰基准也是大眼睛和圆脸。猫头鹰更偏向宽眼距和更接近圆形的轮廓。兔子更偏向大眼睛加上小鼻子和小嘴巴。","rabbit_p4":"把眼睛睁得很大会增加眼高，结果可能移向兔子或猫头鹰。想看平时的大小，自然睁开眼睛的照片更好。","owl_title":"猫头鹰相 — 动物面相图鉴","owl_meta":"脸很圆、眼睛大、两眼间距宽的基准。","owl_h1":"猫头鹰相","owl_p1":"猫头鹰相是脸很圆、眼睛很大，所以五官读起来像圆形。九个基准里，这个对脸的圆度拉力最强。","owl_p2":"脸的圆度、眼睛大小、圆眼型，以及两眼间距，都按偏大来读。鼻子和嘴巴又小又短，下巴尖柔和偏宽，中面部短。","owl_p3":"分数常常和兔子接近。眼距宽、轮廓接近圆，就偏向猫头鹰。如果只是鼻子和嘴巴小，脸还留着一些长度，请同时看兔子和猫。","owl_p4":"贴得很近的广角会把脸的中部扭成更圆的形状。至少在一臂远的地方拍，轮廓没那么容易鼓起来。","bear_title":"熊相 — 动物面相图鉴","bear_meta":"脸、鼻子和下颌都宽，眼睛较小的基准。","bear_h1":"熊相","bear_p1":"熊相是宽脸、宽鼻子、宽下颌，加上较小的眼睛。这本图鉴把它读成稳重、宽和的印象。它更看脸的宽度，而不是眼睛大小。","bear_p2":"鼻宽、下颌宽和下巴都比平均更宽，眼睛大小偏小。嘴巴也稍宽。中面部留在平均附近。","bear_p3":"狮子基准也有宽鼻子和宽下颌。狮子更看重嘴巴和下颌，眼睛不必很小。眼睛小、整张脸都宽时，更接近熊。","bear_p4":"胡子、口罩或手会挡住鼻子和下颌的边缘。请让鼻尖和下颌线露出来再拍。","lion_title":"狮相 — 动物面相图鉴","lion_meta":"鼻子、嘴巴和下颌都宽，五官读起来开阔的基准。","lion_h1":"狮相","lion_p1":"狮相是鼻子、嘴巴和下颌都宽，所以五官看起来有存在感。这个基准更看下半张脸的宽度，而不是眼睛大小或脸的长短。","lion_p2":"鼻宽、嘴宽和下颌宽都按偏宽来读。眼睛比平均稍小，整张脸的圆度离平均不太远。","lion_p3":"小狗基准的嘴巴也宽，但眼睛圆而亲切。狮子的分数更多被鼻子、嘴巴和下颌的宽度拉过去，而不是眼睛。","lion_p4":"笑或说话会让嘴巴更宽。和一张闭嘴的照片比一比，就能看出是不是表情造成的差别。","deer_title":"鹿相 — 动物面相图鉴","deer_meta":"脸长、眼睛大、下颌和下巴窄的基准。","deer_h1":"鹿相","deer_p1":"鹿相是长脸、大眼睛、窄下颌，在这本图鉴里是细而温和的线条。长脸之中，眼睛更大的被读成鹿。","deer_p2":"脸高偏长，眼睛大，鼻子窄，下颌和下巴尖瘦，中面部长。眼型不必像狐狸那样细。","deer_p3":"狐狸和狼也是长脸。鹿是大眼睛加瘦下颌。狼是细眼睛加长中面部。","deer_p4":"相机从上往下看会让下颌变短。相机和眼睛同一高度时，脸高没那么容易变形。","wolf_title":"狼相 — 动物面相图鉴","wolf_meta":"眼睛细，中面部和鼻子长的基准。","wolf_h1":"狼相","wolf_p1":"狼相是眼睛细、中面部长，所以轮廓看起来锐利。嘴巴留在平均附近，长脸是从眼睛到鼻子的距离读出来的。","wolf_p2":"眼高偏短，两眼靠得更近，鼻子以及眼睛到鼻尖的距离都长。脸偏长，下巴尖按偏窄来读。","wolf_p3":"狐的基准常常是邻居。狐更看重更瘦的下巴尖和更窄的鼻子。狼更看重细眼睛和中面部长度。","wolf_p4":"眯眼可能只凭眼型比例就把狼的一侧抬高。请按平时睁眼的样子来拍。"},"hi":{"nav_label":"गाइड मेनू","nav_tool":"चेहरा मापें","nav_method":"माप कैसे होता है","nav_about":"परिचय","nav_privacy":"गोपनीयता","nav_contact":"संपर्क","theme_group":"रूप","theme_light":"हल्का","theme_dark":"गहरा","language_group":"भाषा","footer":"फ़ोटो केवल इसी ब्राउज़र में संसाधित होती है और अपलोड नहीं होती। परिणाम चेहरे के अनुपात की खेल-सी तुलना है, वैज्ञानिक या व्यक्तित्व परीक्षा नहीं। भाव, कोण, चश्मा और रोशनी क्रम बदल सकते हैं।","try_tool":"इस मानक से चेहरा मापें","read_method":"दस अनुपात कैसे मापे जाते हैं, पढ़ें","other_animals":"अन्य पशु मानक","animal_ratio_heading":"जो अनुपात इस ओर झुकते हैं","animal_score_heading":"निकट अंक का मतलब","animal_photo_heading":"जब फ़ोटो क्रम हिला दे","name_cat":"बिल्ली चेहरा","name_dog":"पिल्ला चेहरा","name_fox":"लोमड़ी चेहरा","name_rabbit":"खरगोश चेहरा","name_owl":"उल्लू चेहरा","name_bear":"भालू चेहरा","name_lion":"शेर चेहरा","name_deer":"हिरण चेहरा","name_wolf":"भेड़िया चेहरा","method_title":"माप कैसे होता है — पशु चेहरा गाइड","method_meta":"चेहरे, आँख, नाक, मुँह और जबड़े की लंबाई के अनुपात कैसे मापे जाते हैं और नौ पशु मानकों से कैसे तुलना होती है।","method_h1":"माप कैसे होता है","method_lead":"यह गाइड बाल, कान या कपड़े नहीं देखती। यह फ़ोटो के चेहरे पर लंबाइयाँ पढ़ती है और केवल उन्हीं लंबाइयों की तुलना करती है जिन्हें चेहरे के आकार से भाग दिया गया हो। दूरी बदलने पर पिक्सेल संख्या बदलती है, इसलिए कच्ची पिक्सेल संख्या अंक नहीं है।","method_measure":"विश्लेषण इसी ब्राउज़र में चलता है। फ़ोटो सर्वर पर नहीं जाती। चुने क्षेत्र में कई चेहरे हों तो सबसे बड़ा लिया जाता है। नीचे के औसत इस गाइड का सामने की फ़ोटो के लिए शुरुआती बिंदु हैं। ये चिकित्सा का सामान्य दायरा नहीं हैं।","method_ratios_heading":"दस अनुपात","method_r1":"चेहरे का आकार। चेहरे की चौड़ाई को ऊँचाई से भाग दें। बड़ी संख्या चौड़ा चेहरा है, छोटी संख्या लंबा चेहरा। इस गाइड का औसत 0.82 है।","method_r2":"आँख का आकार। आँख की चौड़ाई को चेहरे की चौड़ाई से भाग दें। 0.20 का मतलब है कि आँख की चौड़ाई चेहरे की चौड़ाई का 20% है।","method_r3":"आँख का रूप। आँख की ऊँचाई को चौड़ाई से भाग दें। बड़ा अधिक गोल है, छोटा अधिक पतला और तीखा। यहाँ औसत 0.33 है।","method_r4":"आँखों की दूरी। आँखों के बीच की दूरी को चेहरे की चौड़ाई से भाग दें। औसत 0.25 के निकट है।","method_r5":"नाक की चौड़ाई। नाक की चौड़ाई को चेहरे की चौड़ाई से भाग दें। औसत 0.28 के निकट है।","method_r6":"नाक की लंबाई। नाक की लंबाई को चेहरे की ऊँचाई से भाग दें। औसत 0.30 है।","method_r7":"मुँह की चौड़ाई। मुँह की चौड़ाई को चेहरे की चौड़ाई से भाग दें। औसत 0.40 के निकट है।","method_r8":"जबड़े की चौड़ाई। जबड़े के चौड़े हिस्से को चेहरे की चौड़ाई से भाग दें। औसत 0.80 है।","method_r9":"ठुड्डी। ठुड्डी की चौड़ाई को चेहरे की चौड़ाई से भाग दें। औसत 0.32 है।","method_r10":"मध्य चेहरा। आँखों से नाक की नोक तक की लंबाई को चेहरे की ऊँचाई से भाग दें। औसत 0.25 है।","method_score_heading":"अंक कैसे बनता है","method_score":"हर अनुपात को औसत से दूरी में बदला जाता है, फिर हर पशु के तय मानक से तुलना होती है। आँख के आकार जैसे प्रभाव बनाने वाले लक्षण थोड़ा अधिक गिने जाते हैं। ठुड्डी की नोक जैसे हर फ़ोटो में हिलने वाले लक्षण कम गिने जाते हैं। सबसे निकट पशु को ऊँचा अंक मिलता है। अंक 94 पर रुकता है। यह कभी 100 नहीं दिखाता, ताकि एक फ़ोटो की गलती पूर्ण मेल जैसी न लगे।","method_photo_heading":"जब एक ही व्यक्ति का क्रम बदल जाए","method_photo":"सिर घुमाना, आँखें सिकोड़ना, बड़ी मुस्कान, बहुत कम रोशनी, या फ्रेम में बहुत छोटा चेहरा क्रम बदल सकता है। सामने की फ़ोटो, जिसमें आँखें कैमरे के बराबर हों और मुँह बंद हो, तुलना में आसान है। चश्मे का फ्रेम आँख के बाहरी कोने को ढके तो आँख की लंबाई गलत पढ़ी जा सकती है। बहुत पास से लिया चौड़ा कोण चेहरे के बीच को अधिक गोल दिखाता है।","method_animals_heading":"नौ पशु मानक","method_animals":"हर पशु बड़े और छोटे अनुपातों का अलग मिश्रण देखता है। नाम चुनें और वह मानक अकेले पढ़ें। ये पृष्ठ एक ही अनुच्छेद में केवल पशु का नाम बदलकर नहीं दोहराते।","about_title":"परिचय — पशु चेहरा गाइड","about_meta":"पशु चेहरा गाइड क्या तुलना करती है, फ़ोटो कहाँ रहती है, और परिणाम कैसे पढ़ें।","about_h1":"इस गाइड के बारे में","about_p1":"पशु चेहरा गाइड एक ब्राउज़र प्रोग्राम है जो चेहरे की फ़ोटो के लंबाई अनुपात की तुलना बिल्ली, पिल्ला, लोमड़ी, खरगोश, उल्लू, भालू, शेर, हिरण और भेड़िये के मानकों से करती है। यह एक बात का वादा करती है: आपके चुने क्षेत्र के अनुपात मापना, और दिखाना कि नौ मानकों में कौन सबसे निकट है।","about_p2":"फ़ोटो फ़ाइल केवल इसी ब्राउज़र में पढ़ी जाती है और विश्लेषण सर्वर पर नहीं जाती। पृष्ठ बंद करते ही फ़ोटो भी चली जाती है। इस उपकरण पर केवल चुनी भाषा और हल्का या गहरा रूप रहता है।","about_p3":"परिणाम एक खेल-सी तुलना है। यह उपकरण व्यक्तित्व बताने, या चिकित्सा, आनुवंशिकी, या पहचान जाँच के लिए नहीं बना। साइट, गलती या गोपनीयता के सवाल संपर्क पृष्ठ पर जाएँ।","privacy_title":"गोपनीयता — पशु चेहरा गाइड","privacy_meta":"चेहरे की फ़ोटो, भाषा सेटिंग, विज्ञापन, टिप्पणी और संपर्क फ़ॉर्म जानकारी को कैसे संभालते हैं।","privacy_h1":"गोपनीयता","privacy_photo_heading":"चेहरे की फ़ोटो","privacy_photo":"कैमरे से ली या विश्लेषण के लिए अपलोड की गई चेहरे की फ़ोटो केवल इस ब्राउज़र की मेमोरी में संभाली जाती है। यह पशु चेहरा गाइड के सर्वर पर नहीं जाती और खाते में नहीं बचती। पृष्ठ बंद करने या दूसरी फ़ोटो चुनने पर पिछली फ़ोटो नहीं रहती।","privacy_store_heading":"इस उपकरण पर रहने वाली सेटिंग","privacy_store":"चुनी भाषा इस ब्राउज़र में language_code नाम से रहती है, और हल्का या गहरा रूप theme_mode नाम से। ये मान केवल अगली यात्रा पर वही दृश्य लौटाते हैं। ये चेहरे की फ़ोटो के साथ नहीं भेजे जाते।","privacy_ads_heading":"विज्ञापन","privacy_ads":"यह साइट Google AdSense के स्वचालित विज्ञापन इस्तेमाल करती है। विज्ञापन दिखने पर Google कुकी या मिलते-जुलते पहचान चिह्न से विज्ञापन चुन और माप सकता है। विज्ञापन के लिए इस्तेमाल जानकारी का Google का विवरण https://policies.google.com/technologies/ads पर है। साइट स्वामित्व के लिए प्रकाशक संख्या ca-pub-8803401825336300 पृष्ठ के सिरे के मेटा टैग और साइट मूल के ads.txt में है।","privacy_disqus_heading":"टिप्पणियाँ","privacy_disqus":"टिप्पणियाँ केवल माप पृष्ठ के नीचे आती हैं और Disqus उन्हें संभालता है। टिप्पणी लिखने के लिए Disqus लॉगिन या साइनअप चाहिए, और Disqus अपनी कुकी इस्तेमाल कर सकता है। टिप्पणी का पाठ चेहरे की फ़ोटो से अलग रखा जाता है। Disqus अपनी गोपनीयता प्रथा https://help.disqus.com/en/articles/1717103-disqus-privacy-policy पर बताता है।","privacy_form_heading":"संपर्क फ़ॉर्म","privacy_form":"केवल संपर्क पृष्ठ पर भेजने का बटन दबाने पर नाम, कंपनी या ब्रांड, जवाब वाला ईमेल और संदेश Formspree (https://formspree.io) तक पहुँचते हैं। चेहरे की फ़ोटो इन फ़ील्ड का हिस्सा नहीं है। फ़ॉर्म न भेजें तो टाइप किया जा रहा पाठ सहेजा नहीं जाता।","privacy_font_heading":"फ़ॉन्ट","privacy_font":"अक्षर Google Fonts से लोड होते हैं। पृष्ठ खुलते ही ब्राउज़र fonts.googleapis.com और fonts.gstatic.com से फ़ॉन्ट फ़ाइल माँगता है। उस माँग में पृष्ठ का पता और सामान्य ब्राउज़र जानकारी शामिल हो सकती है।","privacy_ask_heading":"सवाल","privacy_ask":"अगर यहाँ कुछ छूटा या गलत है तो संपर्क पृष्ठ पर बताएँ। चेहरे की फ़ोटो सर्वर पर नहीं है, इसलिए लौटाने के लिए कोई फ़ाइल नहीं है। टिप्पणी हटाना Disqus में होता है। पहले भेजी पूछताछ मिटाने का अनुरोध संपर्क पृष्ठ और उस इनबॉक्स से किया जा सकता है जिसने उसे पाया।","contact_title":"संपर्क — पशु चेहरा गाइड","contact_meta":"पशु चेहरा गाइड की साझेदारी, गलती और गोपनीयता के सवालों का संपर्क पृष्ठ।","contact_h1":"संपर्क","contact_help":"साझेदारी, गलती या गोपनीयता का सवाल छोड़ें। चेहरे की फ़ोटो इस फ़ॉर्म से नहीं जुड़ती। जवाब आपके लिखे ईमेल पर जाएगा।","contact_name":"नाम","contact_company":"कंपनी या ब्रांड","contact_email":"जवाब के लिए ईमेल","contact_message":"संदेश","contact_send":"संदेश भेजें","contact_subject":"पशु चेहरा गाइड पूछताछ","contact_invalid":"नाम, जवाब वाला ईमेल और संदेश लिखकर फिर भेजें।","contact_sending":"संदेश भेजा जा रहा है।","contact_sent":"संदेश भेज दिया गया। हम आपके लिखे ईमेल पर जवाब देंगे।","contact_fail":"संदेश नहीं भेजा जा सका। थोड़ी देर बाद फिर कोशिश करें।","contact_network":"संदेश नहीं भेजा जा सका। कनेक्शन जाँचकर फिर कोशिश करें।","contact_teaser_title":"संपर्क","contact_teaser":"साझेदारी, गलती या गोपनीयता के सवाल संपर्क पृष्ठ पर लिखें। जवाब आपके लिखे ईमेल पर जाएगा। चेहरे की फ़ोटो संदेश में नहीं जाती।","atlas_help":"पशु का नाम चुनें और उसका विवरण पढ़ें। चेहरे की फ़ोटो के बिना भी गाइड देखी जा सकती है।","lead":"तुलना बाल या कान से नहीं, चेहरे की चौड़ाई-लंबाई और आँख, नाक, मुँह, जबड़े के लंबाई अनुपात से होती है। अंक नौ पशु मानकों से दूरी है। यह व्यक्तित्व परीक्षा या वैज्ञानिक पहचान नहीं है।","cat_title":"बिल्ली चेहरा — पशु चेहरा गाइड","cat_meta":"बड़ी आँखें और छोटी नाक-मुँह वाला मानक, जिससे अंग बीच की ओर इकट्ठे लगें।","cat_h1":"बिल्ली चेहरा","cat_p1":"बिल्ली चेहरा वह छाप है जिसमें आँख, नाक और मुँह चेहरे के बीच की ओर बैठे लगें। इस गाइड का बिल्ली मानक तब निकट होता है जब चेहरा थोड़ा गोल हो, आँखें बड़ी हों, और नाक व मुँह औसत से छोटे हों।","cat_p2":"चेहरे की चौड़ाई ऊँचाई की तुलना में उदार है, और आँखें चेहरे की चौड़ाई का अधिक हिस्सा लेती हैं। अधिक पतली और छोटी नाक, तथा छोटा मुँह, बिल्ली की ओर झुकते हैं। आँखों से नाक की नोक तक का मध्य चेहरा छोटे पक्ष पर है।","cat_p3":"ऊँचा अंक मतलब है कि दस अनुपात मिलकर बिल्ली मानक के सबसे निकट हैं। केवल बड़ी आँखें बिल्ली चेहरा नहीं बनातीं। चौड़ी नाक और मुँह भालू या शेर के अधिक निकट बैठ सकते हैं।","cat_p4":"मुस्कान मुँह चौड़ा करती है और परिणाम पिल्ला या शेर की ओर झुक सकता है। सिर घुमाने से आँखें वास्तविक से छोटी लगती हैं। मुँह बंद वाली सामने की फ़ोटो इस मानक से तुलना में आसान है।","dog_title":"पिल्ला चेहरा — पशु चेहरा गाइड","dog_meta":"गोल आँखें और चौड़ा मुँह, जिसे यह गाइड कोमल और मैत्रीपूर्ण मानती है।","dog_h1":"पिल्ला चेहरा","dog_p1":"पिल्ला चेहरा गोल आँखों और चौड़े मुँह की छाप है, इसलिए भाव कोमल लगता है। नाक औसत के निकट रहती है, और थोड़ा गोल चेहरा पिल्ला मानक के निकट बैठता है।","dog_p2":"पिल्ला मानक तब निकट है जब आँख का रूप, यानी आँख की ऊँचाई को चौड़ाई से भाग, गोल हो और मुँह चेहरे पर चौड़ा हो। आँखों के बीच थोड़ी अधिक दूरी भी उसी पढ़ने का हिस्सा है।","dog_p3":"केवल चौड़ा मुँह पिल्ला चेहरा नहीं है। नाक और जबड़ा भी चौड़े हों तो शेर या भालू निकट हो सकते हैं। पतली आँखें परिणाम को लोमड़ी या भेड़िये की ओर ले जाती हैं।","dog_p4":"बड़ी मुस्कान मुँह का अनुपात बढ़ाती है। रोज़ की छाप चाहिए तो मुँह बंद वाली फ़ोटो भी मापें।","fox_title":"लोमड़ी चेहरा — पशु चेहरा गाइड","fox_meta":"लंबा चेहरा, पतली ठुड्डी और तीखी आँखों का मानक।","fox_h1":"लोमड़ी चेहरा","fox_p1":"लोमड़ी चेहरा लंबी रूपरेखा, पतली ठुड्डी और तीखी आँखें हैं। यह हिरण जैसे बड़ी आँखों वाले लंबे चेहरे से आँखों के रूप से अलग होता है।","fox_p2":"लोमड़ी मानक तब निकट है जब चेहरे की ऊँचाई चौड़ाई से अधिक हो, आँखें पतली हों, और ठुड्डी की नोक दुबली हो। नाक पतली पर लंबी है, और आँखें थोड़ी अधिक पास बैठी हैं।","fox_p3":"हिरण मानक भी लंबा चेहरा और पतला जबड़ा है, पर हिरण बड़ी आँखें देखता है और लोमड़ी पतली, तीखी आँखें। दोनों अंक पास हों तो आँख का रूप भी साथ पढ़ें।","fox_p4":"बगल का दृश्य ठुड्डी को और पतला दिखाता है। ठुड्डी ढकने वाले बाल ठुड्डी का अनुपात छिपा देते हैं। जबड़े की रेखा दिखती सामने की फ़ोटो इस्तेमाल करें।","rabbit_title":"खरगोश चेहरा — पशु चेहरा गाइड","rabbit_meta":"बड़ी आँखें और छोटी नाक-मुँह, जिसे यहाँ गोल, नरम छाप पढ़ा जाता है।","rabbit_h1":"खरगोश चेहरा","rabbit_p1":"खरगोश चेहरे में बड़ी आँखें और छोटी नाक-मुँह होते हैं, इसलिए छाप गोल और नरम है। यह इस गाइड के उन मानकों में है जो आँख के आकार को सबसे अधिक देखते हैं।","rabbit_p2":"चेहरा गोल है, आँखें चौड़ी हैं, आँख का रूप गोल है, और आँखों के बीच की दूरी थोड़ी अधिक है। नाक की चौड़ाई, नाक की लंबाई और मुँह की चौड़ाई छोटी हैं, और मध्य चेहरा छोटा है।","rabbit_p3":"उल्लू मानक में भी बड़ी आँखें और गोल चेहरा है। उल्लू अधिक चौड़ी आँख-दूरी और अधिक गोल रूपरेखा की ओर झुकता है। खरगोश बड़ी आँखों के साथ छोटी नाक और मुँह की ओर झुकता है।","rabbit_p4":"आँखें बहुत अधिक खोलने से आँख की ऊँचाई बढ़ती है और परिणाम खरगोश या उल्लू की ओर जा सकता है। रोज़ के आकार के लिए आँखें स्वाभाविक खुली हों, ऐसी फ़ोटो बेहतर है।","owl_title":"उल्लू चेहरा — पशु चेहरा गाइड","owl_meta":"बहुत गोल चेहरा, बड़ी आँखें, और आँखों के बीच अधिक दूरी का मानक।","owl_h1":"उल्लू चेहरा","owl_p1":"उल्लू चेहरा बहुत गोल चेहरा और बड़ी आँखें हैं, इसलिए अंग गोलाकार पढ़े जाते हैं। नौ मानकों में यही चेहरे की गोलाई को सबसे मजबूत खिंचाव देता है।","owl_p2":"चेहरे की गोलाई, आँख का आकार, गोल आँख रूप, और आँखों के बीच की दूरी सब बड़े पक्ष पर पढ़े जाते हैं। नाक और मुँह छोटे और नाटे हैं, ठुड्डी की नोक नरम-चौड़ी है, और मध्य चेहरा छोटा है।","owl_p3":"अंक अक्सर खरगोश के पास बैठता है। चौड़ी आँख-दूरी और वृत्त के निकट रूपरेखा उल्लू की ओर झुकती है। केवल नाक और मुँह छोटे हों और कुछ चेहरे की लंबाई बची हो तो खरगोश और बिल्ली भी साथ पढ़ें।","owl_p4":"बहुत पास का चौड़ा कोण चेहरे के बीच को अधिक गोल रूप में मोड़ देता है। कम से कम एक बाँह की दूरी से रूपरेखा कम फूलती है।","bear_title":"भालू चेहरा — पशु चेहरा गाइड","bear_meta":"चौड़ा चेहरा, नाक और जबड़ा, तथा छोटी आँखों का मानक।","bear_h1":"भालू चेहरा","bear_p1":"भालू चेहरा चौड़ा चेहरा, नाक और जबड़ा तथा छोटी आँखें हैं। इस गाइड में यह ठोस और सहज छाप पढ़ी जाती है। यह आँख के आकार से अधिक चेहरे की चौड़ाई देखता है।","bear_p2":"नाक की चौड़ाई, जबड़े की चौड़ाई और ठुड्डी औसत से चौड़ी हैं, और आँख का आकार छोटे पक्ष पर है। मुँह थोड़ा चौड़ा है। मध्य चेहरा औसत के निकट रहता है।","bear_p3":"शेर मानक में भी चौड़ी नाक और जबड़ा है। शेर मुँह और जबड़े पर अधिक भार रखता है, और आँखों का बहुत छोटा होना ज़रूरी नहीं। छोटी आँखें और पूरे चेहरे की चौड़ाई भालू के अधिक निकट बैठती हैं।","bear_p4":"दाढ़ी, मास्क या हाथ नाक और जबड़े की किनारी छिपा देते हैं। फ़ोटो ऐसे लें कि नाक की नोक और जबड़े की रेखा दिखे।","lion_title":"शेर चेहरा — पशु चेहरा गाइड","lion_meta":"चौड़ी नाक, मुँह और जबड़ा, जिससे अंग चौड़े पढ़े जाएँ।","lion_h1":"शेर चेहरा","lion_p1":"शेर चेहरे में चौड़ी नाक, मुँह और जबड़ा होते हैं, इसलिए अंग मज़बूत लगते हैं। यह मानक आँख के आकार या चेहरे की लंबाई से अधिक निचले चेहरे की चौड़ाई देखता है।","lion_p2":"नाक की चौड़ाई, मुँह की चौड़ाई और जबड़े की चौड़ाई चौड़े पक्ष पर पढ़ी जाती हैं। आँख का आकार औसत से थोड़ा छोटा है, और पूरे चेहरे की गोलाई औसत से बहुत दूर नहीं जाती।","lion_p3":"पिल्ला मानक में भी चौड़ा मुँह है, पर गोल, मैत्रीपूर्ण आँखों के साथ। शेर का अंक आँखों से अधिक नाक, मुँह और जबड़े की चौड़ाई खींचता है।","lion_p4":"मुस्कुराने या बोलने से मुँह और चौड़ा होता है। बंद मुँह वाली फ़ोटो से तुलना करें कि अंतर भाव ने बनाया या नहीं।","deer_title":"हिरण चेहरा — पशु चेहरा गाइड","deer_meta":"लंबा चेहरा, बड़ी आँखें, और पतला जबड़ा-ठुड्डी का मानक।","deer_h1":"हिरण चेहरा","deer_p1":"हिरण चेहरा लंबा चेहरा, बड़ी आँखें और पतला जबड़ा है, इस गाइड में एक महीन और कोमल रेखा। लंबे चेहरों में बड़ी आँखों वाला हिरण पढ़ा जाता है।","deer_p2":"चेहरे की ऊँचाई लंबी है, आँखें बड़ी हैं, नाक पतली है, जबड़ा और ठुड्डी की नोक दुबले हैं, और मध्य चेहरा लंबा है। आँख का रूप लोमड़ी जितना पतला होना ज़रूरी नहीं।","deer_p3":"लोमड़ी और भेड़िया भी लंबे चेहरे हैं। हिरण बड़ी आँखों और दुबले जबड़े का जोड़ा है। भेड़िया पतली आँखों और लंबे मध्य चेहरे का जोड़ा है।","deer_p4":"ऊपर से देखता कैमरा जबड़े को छोटा कर देता है। कैमरा आँखों के बराबर हो तो चेहरे की ऊँचाई कम विकृत होती है।","wolf_title":"भेड़िया चेहरा — पशु चेहरा गाइड","wolf_meta":"पतली आँखें और लंबा मध्य चेहरा व नाक का मानक।","wolf_h1":"भेड़िया चेहरा","wolf_p1":"भेड़िया चेहरे में पतली आँखें और लंबा मध्य चेहरा होता है, इसलिए रूपरेखा तीखी लगती है। मुँह औसत के निकट रहता है, और लंबा चेहरा आँखों और नाक के बीच की दूरी से पढ़ा जाता है।","wolf_p2":"आँख की ऊँचाई छोटी है, आँखें अधिक पास बैठी हैं, और नाक तथा आँखों से नाक की नोक तक की दूरी दोनों लंबी हैं। चेहरा लंबे पक्ष पर है, और ठुड्डी की नोक पतली पढ़ी जाती है।","wolf_p3":"लोमड़ी मानक अक्सर पड़ोसी होता है। लोमड़ी अधिक दुबली ठुड्डी नोक और अधिक पतली नाक पर भार रखती है। भेड़िया पतली आँखों और मध्य चेहरे की लंबाई पर अधिक भार रखता है।","wolf_p4":"आँख सिकोड़ने से केवल आँख-रूप अनुपात भेड़िये का पक्ष उठा सकता है। आँखें जैसे आमतौर पर खुली रहती हैं, वैसे फ़ोटो लें।"},"zh-Hant":{"nav_label":"圖鑑選單","nav_tool":"測量臉部","nav_method":"測量方法","nav_about":"介紹","nav_privacy":"隱私","nav_contact":"聯繫","theme_group":"畫面模式","theme_light":"淺色","theme_dark":"深色","language_group":"語言","footer":"照片只在這個瀏覽器裡處理，不會上傳。結果是把臉的比例和動物基準做的趣味比較，不是科學鑑定，也不是性格測試。表情、角度、眼鏡和光線都可能改變排名。","try_tool":"用這個基準測量臉部","read_method":"看看十個比例是怎麼量的","other_animals":"其他動物基準","animal_ratio_heading":"偏向這種動物的比例","animal_score_heading":"分數接近是什麼意思","animal_photo_heading":"照片會讓排名晃動的時候","name_cat":"貓相","name_dog":"小狗相","name_fox":"狐相","name_rabbit":"兔相","name_owl":"貓頭鷹相","name_bear":"熊相","name_lion":"獅相","name_deer":"鹿相","name_wolf":"狼相","method_title":"測量方法 — 動物面相圖鑑","method_meta":"說明臉的寬高，以及眼、鼻、嘴、下頜的長度比例如何測量，並和九種動物基準比較。","method_h1":"測量方法","method_lead":"這本圖鑑不看頭髮、耳朵或衣服。它只讀取照片裡臉上的長度，再把這些長度除以臉的大小來比較。距離一變，像素數就會變，所以原始像素數不是分數。","method_measure":"分析在這個瀏覽器裡進行。照片不會送到服務器。如果選中的區域裡有好幾張臉，就用最大的一張。下面的平均值是這本圖鑑為正面照片設的起點，不是醫學上的正常範圍。","method_ratios_heading":"十個比例","method_r1":"臉型。臉寬除以臉高。數字大是更寬的臉，數字小是更長的臉。這本圖鑑的平均是 0.82。","method_r2":"眼睛大小。眼寬除以臉寬。0.20 表示眼寬是臉寬的 20%。","method_r3":"眼型。眼高除以眼寬。更大更圓，更小更細更銳。這裡的平均是 0.33。","method_r4":"眼距。兩眼距離除以臉寬。平均接近 0.25。","method_r5":"鼻寬。鼻寬除以臉寬。平均接近 0.28。","method_r6":"鼻長。鼻長除以臉高。平均是 0.30。","method_r7":"嘴寬。嘴寬除以臉寬。平均接近 0.40。","method_r8":"下頜寬度。下頜較寬處的寬度除以臉寬。平均是 0.80。","method_r9":"下巴。下巴寬度除以臉寬。平均是 0.32。","method_r10":"中面部。眼睛到鼻尖的長度除以臉高。平均是 0.25。","method_score_heading":"分數是怎麼來的","method_score":"每個比例先換成離平均有多遠，再和每種動物設定的基準比距離。眼睛大小這類影響印象的項目權重大一點。下巴尖這類每張照片都容易晃的項目權重小一點。最接近的動物分數更高。分數到 94 為止。它不會顯示 100，這樣一張照片的誤差就不會被看成完全吻合。","method_photo_heading":"同一個人排名也會變的時候","method_photo":"轉頭、瞇眼、大笑、光線很暗，或畫面裡的臉很小，排名都可能變。眼睛和相機同一高度、嘴巴閉上的正面照片更好比較。鏡框擋住眼尾時，眼睛長度可能讀錯。貼得很近的廣角會讓臉的中部看起來更圓。","method_animals_heading":"九種動物的基準","method_animals":"每種動物看的是不同的偏大和偏小組合。點名字可以單獨讀那個基準。這些頁面不是只換動物名字、重複同一段話。","about_title":"介紹 — 動物面相圖鑑","about_meta":"動物面相圖鑑比較什麼、照片留在哪裡，以及結果該怎麼讀。","about_h1":"關於這本圖鑑","about_p1":"動物面相圖鑑是一個瀏覽器程序，把臉部照片裡的長度比例和貓、小狗、狐狸、兔子、貓頭鷹、熊、獅子、鹿、狼的基準比較。它對訪客只承諾一件事：測量你選中區域的比例，並顯示九個基準裡哪一個最近。","about_p2":"照片文件只在這個瀏覽器裡讀取，不會上傳到分析服務器。關掉頁面，照片也一起消失。這臺設備上留下的只有你選的語言，以及淺色或深色模式。","about_p3":"結果是一種趣味比較。這個工具不是為了描述性格，也不是為了醫學、遺傳或身份核驗。網站、錯誤或隱私方面的問題請到聯繫頁。","privacy_title":"隱私 — 動物面相圖鑑","privacy_meta":"臉部照片、語言設置、廣告、評論和聯繫表單各自如何處理信息。","privacy_h1":"隱私","privacy_photo_heading":"臉部照片","privacy_photo":"用相機拍下或為分析而上傳的臉部照片，只在這個瀏覽器的內存裡處理。它不會送到動物面相圖鑑的服務器，也不會存進賬戶。關掉頁面或換一張照片後，上一張不會留下。","privacy_store_heading":"留在這臺設備上的設置","privacy_store":"所選語言以 language_code 存在這個瀏覽器裡，淺色或深色模式以 theme_mode 保存。這些值只為下次打開時恢復同樣的畫面，不會和臉部照片一起發送。","privacy_ads_heading":"廣告","privacy_ads":"本站使用 Google AdSense 自動廣告。廣告顯示時，Google 可能用 Cookie 或類似標識來選擇和衡量廣告。Google 對廣告所用信息的說明在 https://policies.google.com/technologies/ads 。為確認站點所有權，發佈商編號 ca-pub-8803401825336300 寫在頁面頭部的 meta 標籤和站點根目錄的 ads.txt 裡。","privacy_disqus_heading":"評論","privacy_disqus":"評論只出現在測量頁底部，由 Disqus 處理。寫評論需要 Disqus 的登錄或註冊，Disqus 也可能使用自己的 Cookie。評論內容和臉部照片分開保存。Disqus 的隱私說明在 https://help.disqus.com/en/articles/1717103-disqus-privacy-policy 。","privacy_form_heading":"聯繫表單","privacy_form":"只有在聯繫頁按下發送時，姓名、公司或品牌、回覆郵箱和內容才會交給 Formspree（https://formspree.io）。臉部照片不在這些字段裡。如果沒有發送，正在輸入的文字也不會被保存。","privacy_font_heading":"字體","privacy_font":"字體從 Google Fonts 加載。打開頁面時，瀏覽器會向 fonts.googleapis.com 和 fonts.gstatic.com 請求字體文件。這個請求通常可能包含正在訪問的地址和瀏覽器信息。","privacy_ask_heading":"提問","privacy_ask":"如果這裡有遺漏或錯誤，請在聯繫頁告訴我們。臉部照片不在服務器上，所以沒有可以交還的文件。刪除評論在 Disqus 裡處理。已經發出的諮詢郵件，可以通過聯繫頁和收到郵件的收件箱申請刪除。","contact_title":"聯繫 — 動物面相圖鑑","contact_meta":"接收動物面相圖鑑的合作、錯誤和隱私問題的聯繫頁。","contact_h1":"聯繫","contact_help":"請留下合作、錯誤或隱私方面的問題。臉部照片不會附在這個表單上。回覆會發到你填寫的郵箱。","contact_name":"姓名","contact_company":"公司或品牌","contact_email":"回覆郵箱","contact_message":"內容","contact_send":"發送","contact_subject":"動物面相圖鑑諮詢","contact_invalid":"請填寫姓名、回覆郵箱和內容，然後再發送。","contact_sending":"正在發送。","contact_sent":"已經發出。我們會回覆到你填寫的郵箱。","contact_fail":"沒有發出去。請稍後再試。","contact_network":"沒有發出去。請檢查網絡後再試。","contact_teaser_title":"聯繫","contact_teaser":"合作、錯誤或隱私方面的問題請寫在聯繫頁。回覆會發到你填寫的郵箱。臉部照片不會寫進這封信。","atlas_help":"點動物名字可以讀它的基準說明。沒有臉部照片也可以瀏覽圖鑑。","lead":"比較用的是臉的寬高，以及眼、鼻、嘴、下頜的長度比例，不是頭髮或耳朵。分數是和九種動物基準的距離，不是性格測試，也不是科學鑑定。","cat_title":"貓相 — 動物面相圖鑑","cat_meta":"眼睛大，鼻子和嘴巴小，五官看起來往臉的中間聚攏的基準。","cat_h1":"貓相","cat_p1":"貓相是眼睛、鼻子和嘴巴往臉的中間靠的印象。這本圖鑑的貓基準，在臉稍圓、眼睛大、鼻子和嘴巴比平均更小時會更近。","cat_p2":"臉寬相對臉高比較寬裕，眼睛佔臉寬的比例更大。更窄更短的鼻子，以及更小的嘴巴，會偏向貓。從眼睛到鼻尖的中面部偏短。","cat_p3":"分數高，表示十個比例合在一起時離貓的基準最近。只有眼睛大並不會變成貓相。鼻子和嘴巴很寬時，可能更接近熊或獅子。","cat_p4":"一笑嘴巴變寬，結果可能偏向小狗或獅子。轉頭會讓眼睛看起來比實際更小。嘴巴閉上的正面照片更容易和這個基準比較。","dog_title":"小狗相 — 動物面相圖鑑","dog_meta":"眼睛圓、嘴巴寬，這本圖鑑把它讀成溫和親切的基準。","dog_h1":"小狗相","dog_p1":"小狗相是眼睛圓、嘴巴寬，所以表情看起來溫和。鼻子留在平均附近，稍微偏圓的臉更接近小狗基準。","dog_p2":"眼型，也就是眼高除以眼寬，偏圓，而且嘴巴在臉上偏寬時，更接近小狗基準。兩眼間距稍寬也算在同一次閱讀裡。","dog_p3":"只有嘴巴寬還不是小狗相。如果鼻子和下頜也寬，獅子或熊可能更近。眼睛細長會把結果推向狐狸或狼。","dog_p4":"大笑會增大嘴巴的比例。如果想看平時的印象，也用一張嘴巴閉上的照片量一次。","fox_title":"狐相 — 動物面相圖鑑","fox_meta":"臉長、下巴尖窄、眼睛銳利的基準。","fox_h1":"狐相","fox_p1":"狐相是輪廓長、下巴尖窄、眼睛銳利。它和鹿那種眼睛很大的長臉，是靠眼睛的形狀分開的。","fox_p2":"臉高超過臉寬、眼睛細、下巴尖瘦時，更接近狐的基準。鼻子窄但長，兩眼也靠得稍近。","fox_p3":"鹿的基準也是長臉加窄下頜，但鹿看的是更大的眼睛，狐看的是細而銳的眼睛。如果兩個分數接近，請一起看眼型。","fox_p4":"側臉會讓下巴看起來更窄。頭髮擋住下巴時，下巴比例讀不到。請用能看見下頜線的正面照片。","rabbit_title":"兔相 — 動物面相圖鑑","rabbit_meta":"眼睛大，鼻子和嘴巴小，這裡把它讀成圓而柔和的印象。","rabbit_h1":"兔相","rabbit_p1":"兔相是眼睛大、鼻子和嘴巴小，所以印象圓而柔和。它是這本圖鑑裡最看重眼睛大小的基準之一。","rabbit_p2":"臉圓，眼睛寬，眼型圓，兩眼間距也稍寬。鼻寬、鼻長和嘴寬都小，中面部短。","rabbit_p3":"貓頭鷹基準也是大眼睛和圓臉。貓頭鷹更偏向寬眼距和更接近圓形的輪廓。兔子更偏向大眼睛加上小鼻子和小嘴巴。","rabbit_p4":"把眼睛睜得很大會增加眼高，結果可能移向兔子或貓頭鷹。想看平時的大小，自然睜開眼睛的照片更好。","owl_title":"貓頭鷹相 — 動物面相圖鑑","owl_meta":"臉很圓、眼睛大、兩眼間距寬的基準。","owl_h1":"貓頭鷹相","owl_p1":"貓頭鷹相是臉很圓、眼睛很大，所以五官讀起來像圓形。九個基準裡，這個對臉的圓度拉力最強。","owl_p2":"臉的圓度、眼睛大小、圓眼型，以及兩眼間距，都按偏大來讀。鼻子和嘴巴又小又短，下巴尖柔和偏寬，中面部短。","owl_p3":"分數常常和兔子接近。眼距寬、輪廓接近圓，就偏向貓頭鷹。如果只是鼻子和嘴巴小，臉還留著一些長度，請同時看兔子和貓。","owl_p4":"貼得很近的廣角會把臉的中部扭成更圓的形狀。至少在一臂遠的地方拍，輪廓沒那麼容易鼓起來。","bear_title":"熊相 — 動物面相圖鑑","bear_meta":"臉、鼻子和下頜都寬，眼睛較小的基準。","bear_h1":"熊相","bear_p1":"熊相是寬臉、寬鼻子、寬下頜，加上較小的眼睛。這本圖鑑把它讀成穩重、寬和的印象。它更看臉的寬度，而不是眼睛大小。","bear_p2":"鼻寬、下頜寬和下巴都比平均更寬，眼睛大小偏小。嘴巴也稍寬。中面部留在平均附近。","bear_p3":"獅子基準也有寬鼻子和寬下頜。獅子更看重嘴巴和下頜，眼睛不必很小。眼睛小、整張臉都寬時，更接近熊。","bear_p4":"鬍子、口罩或手會擋住鼻子和下頜的邊緣。請讓鼻尖和下頜線露出來再拍。","lion_title":"獅相 — 動物面相圖鑑","lion_meta":"鼻子、嘴巴和下頜都寬，五官讀起來開闊的基準。","lion_h1":"獅相","lion_p1":"獅相是鼻子、嘴巴和下頜都寬，所以五官看起來有存在感。這個基準更看下半張臉的寬度，而不是眼睛大小或臉的長短。","lion_p2":"鼻寬、嘴寬和下頜寬都按偏寬來讀。眼睛比平均稍小，整張臉的圓度離平均不太遠。","lion_p3":"小狗基準的嘴巴也寬，但眼睛圓而親切。獅子的分數更多被鼻子、嘴巴和下頜的寬度拉過去，而不是眼睛。","lion_p4":"笑或說話會讓嘴巴更寬。和一張閉嘴的照片比一比，就能看出是不是表情造成的差別。","deer_title":"鹿相 — 動物面相圖鑑","deer_meta":"臉長、眼睛大、下頜和下巴窄的基準。","deer_h1":"鹿相","deer_p1":"鹿相是長臉、大眼睛、窄下頜，在這本圖鑑裡是細而溫和的線條。長臉之中，眼睛更大的被讀成鹿。","deer_p2":"臉高偏長，眼睛大，鼻子窄，下頜和下巴尖瘦，中面部長。眼型不必像狐狸那樣細。","deer_p3":"狐狸和狼也是長臉。鹿是大眼睛加瘦下頜。狼是細眼睛加長中面部。","deer_p4":"相機從上往下看會讓下頜變短。相機和眼睛同一高度時，臉高沒那麼容易變形。","wolf_title":"狼相 — 動物面相圖鑑","wolf_meta":"眼睛細，中面部和鼻子長的基準。","wolf_h1":"狼相","wolf_p1":"狼相是眼睛細、中面部長，所以輪廓看起來銳利。嘴巴留在平均附近，長臉是從眼睛到鼻子的距離讀出來的。","wolf_p2":"眼高偏短，兩眼靠得更近，鼻子以及眼睛到鼻尖的距離都長。臉偏長，下巴尖按偏窄來讀。","wolf_p3":"狐的基準常常是鄰居。狐更看重更瘦的下巴尖和更窄的鼻子。狼更看重細眼睛和中面部長度。","wolf_p4":"瞇眼可能只憑眼型比例就把狼的一側抬高。請按平時睜眼的樣子來拍。"},"es":{"nav_label":"Menú de la guía","nav_tool":"Medir un rostro","nav_method":"Cómo se mide","nav_about":"Acerca de","nav_privacy":"Privacidad","nav_contact":"Contacto","theme_group":"Tema","theme_light":"Claro","theme_dark":"Oscuro","language_group":"Idioma","footer":"Las fotos se procesan solo en este navegador y no se suben. El resultado es una comparación lúdica de las proporciones del rostro, no un test científico ni de personalidad. La expresión, el ángulo, las gafas y la luz pueden cambiar el orden.","try_tool":"Medir un rostro con esta guía","read_method":"Leer cómo se miden las diez proporciones","other_animals":"Otros perfiles de animales","animal_ratio_heading":"Proporciones que se inclinan hacia aquí","animal_score_heading":"Qué significa una puntuación cercana","animal_photo_heading":"Cuando la foto mueve el puesto","name_cat":"Rostro de gato","name_dog":"Rostro de cachorro","name_fox":"Rostro de zorro","name_rabbit":"Rostro de conejo","name_owl":"Rostro de búho","name_bear":"Rostro de oso","name_lion":"Rostro de león","name_deer":"Rostro de ciervo","name_wolf":"Rostro de lobo","method_title":"Cómo se mide — Guía de rostros animales","method_meta":"Explica cómo se miden las proporciones de longitud del rostro, los ojos, la nariz, la boca y la mandíbula, y cómo se comparan con nueve perfiles de animales.","method_h1":"Cómo se mide","method_lead":"Esta guía no mira el pelo, las orejas ni la ropa. Lee longitudes del rostro en la foto y compara solo esas longitudes divididas por el tamaño del rostro. El número de píxeles cambia con la distancia, así que el recuento de píxeles no es la puntuación.","method_measure":"El análisis ocurre en este navegador. La foto no se envía a un servidor. Si hay varios rostros en la zona que elegiste, se usa el más grande. Las medias de abajo son el punto de partida de esta guía para una foto de frente. No son un rango médico normal.","method_ratios_heading":"Las diez proporciones","method_r1":"Forma del rostro. Ancho del rostro dividido por el alto del rostro. Un número mayor es un rostro más ancho, y uno menor es un rostro más largo. La media de esta guía es 0.82.","method_r2":"Tamaño de los ojos. Ancho del ojo dividido por el ancho del rostro. 0.20 significa que el ancho del ojo es el 20% del ancho del rostro.","method_r3":"Forma de los ojos. Alto del ojo dividido por el ancho del ojo. Mayor es más redondo, menor es más estrecho y afilado. La media aquí es 0.33.","method_r4":"Separación de los ojos. La distancia entre los ojos dividida por el ancho del rostro. La media está cerca de 0.25.","method_r5":"Ancho de la nariz. Ancho de la nariz dividido por el ancho del rostro. La media está cerca de 0.28.","method_r6":"Largo de la nariz. Largo de la nariz dividido por el alto del rostro. La media es 0.30.","method_r7":"Ancho de la boca. Ancho de la boca dividido por el ancho del rostro. La media está cerca de 0.40.","method_r8":"Ancho de la mandíbula. La parte más ancha de la mandíbula dividida por el ancho del rostro. La media es 0.80.","method_r9":"Mentón. Ancho del mentón dividido por el ancho del rostro. La media es 0.32.","method_r10":"Zona media. La longitud de los ojos a la punta de la nariz dividida por el alto del rostro. La media es 0.25.","method_score_heading":"Cómo se obtiene la puntuación","method_score":"Cada proporción se convierte en una distancia respecto a la media y luego se compara con el perfil de cada animal. Los rasgos que marcan la impresión, como el tamaño de los ojos, cuentan un poco más. Los que cambian fácil de una foto a otra, como la punta del mentón, cuentan menos. El animal más cercano recibe la puntuación más alta. La puntuación se detiene en 94. Nunca muestra 100, para que el error de una foto no parezca una coincidencia perfecta.","method_photo_heading":"Cuando la misma persona obtiene otro puesto","method_photo":"Girar la cabeza, entrecerrar los ojos, una sonrisa amplia, una luz muy tenue o un rostro diminuto en el encuadre pueden cambiar el puesto. Una foto de frente, con los ojos a la altura de la cámara y la boca cerrada, es más fácil de comparar. La montura de las gafas que tapa el rabillo puede hacer que el largo del ojo salga mal. Un gran angular muy cerca hace que el centro del rostro se vea más redondo.","method_animals_heading":"Los nueve perfiles de animales","method_animals":"Cada animal busca una mezcla distinta de proporciones mayores y menores. Elige un nombre para leer ese perfil solo. Las páginas no repiten un párrafo cambiando únicamente el nombre del animal.","about_title":"Acerca de — Guía de rostros animales","about_meta":"Qué compara la Guía de rostros animales, dónde se queda la foto y cómo leer el resultado.","about_h1":"Acerca de esta guía","about_p1":"La Guía de rostros animales es un programa del navegador que compara proporciones de longitud de una foto del rostro con perfiles de gato, cachorro, zorro, conejo, búho, oso, león, ciervo y lobo. Promete una cosa: medir las proporciones de la zona que eliges y mostrar cuál de los nueve perfiles es el más cercano.","about_p2":"El archivo de la foto se lee solo en este navegador y no se sube a un servidor de análisis. Al cerrar la página, la foto se va con ella. En este dispositivo solo se guardan el idioma que elegiste y el tema claro u oscuro.","about_p3":"El resultado es una comparación lúdica. La herramienta no se hizo para describir la personalidad, ni para medicina, genética o comprobaciones de identidad. Las preguntas sobre el sitio, los errores o la privacidad van a la página de contacto.","privacy_title":"Privacidad — Guía de rostros animales","privacy_meta":"Cómo tratan la información las fotos del rostro, el idioma, los anuncios, los comentarios y el formulario de contacto.","privacy_h1":"Privacidad","privacy_photo_heading":"Fotos del rostro","privacy_photo":"Una foto del rostro tomada con la cámara o subida para analizar se trata solo en la memoria de este navegador. No se envía a un servidor de la Guía de rostros animales ni se guarda en una cuenta. Al cerrar la página o elegir otra foto, la anterior no se conserva.","privacy_store_heading":"Ajustes que quedan en este dispositivo","privacy_store":"El idioma elegido se guarda en este navegador con el nombre language_code, y el tema claro u oscuro con theme_mode. Esos valores solo restauran la misma vista en la próxima visita. No se envían con la foto del rostro.","privacy_ads_heading":"Publicidad","privacy_ads":"Este sitio usa anuncios automáticos de Google AdSense. Cuando se muestra un anuncio, Google puede usar cookies o identificadores parecidos para elegir y medir anuncios. La descripción de Google sobre la información usada en anuncios está en https://policies.google.com/technologies/ads . Para la propiedad del sitio, el id de editor ca-pub-8803401825336300 está en una etiqueta meta de la cabecera y en ads.txt en la raíz del sitio.","privacy_disqus_heading":"Comentarios","privacy_disqus":"Los comentarios aparecen solo al final de la página de medición y los gestiona Disqus. Escribir un comentario exige iniciar sesión o registrarse en Disqus, y Disqus puede usar sus propias cookies. El texto del comentario se guarda aparte de las fotos del rostro. Disqus describe sus prácticas de privacidad en https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Formulario de contacto","privacy_form":"Solo cuando pulsas enviar en la página de contacto, tu nombre, empresa o marca, correo de respuesta y mensaje llegan a Formspree (https://formspree.io). La foto del rostro no forma parte de esos campos. Si no envías el formulario, el texto que estabas escribiendo no se guarda.","privacy_font_heading":"Fuentes","privacy_font":"Las tipografías se cargan desde Google Fonts. Al abrir la página, el navegador pide archivos de fuente a fonts.googleapis.com y fonts.gstatic.com. Esa petición puede incluir la dirección de la página y la información habitual del navegador.","privacy_ask_heading":"Preguntas","privacy_ask":"Si aquí falta algo o hay un error, dínoslo en la página de contacto. Las fotos del rostro no están en un servidor, así que no hay un archivo que devolver. La eliminación de comentarios se gestiona en Disqus. Una solicitud para borrar una consulta ya enviada puede hacerse por la página de contacto y el buzón que la recibió.","contact_title":"Contacto — Guía de rostros animales","contact_meta":"Página de contacto para preguntas de colaboración, errores y privacidad sobre la Guía de rostros animales.","contact_h1":"Contacto","contact_help":"Deja una pregunta de colaboración, error o privacidad. La foto del rostro no se adjunta a este formulario. La respuesta va al correo que escribas.","contact_name":"Nombre","contact_company":"Empresa o marca","contact_email":"Correo para la respuesta","contact_message":"Mensaje","contact_send":"Enviar mensaje","contact_subject":"Consulta de la Guía de rostros animales","contact_invalid":"Escribe tu nombre, el correo de respuesta y el mensaje, y envía de nuevo.","contact_sending":"Enviando tu mensaje.","contact_sent":"Tu mensaje se envió. Responderemos al correo que escribiste.","contact_fail":"No se pudo enviar el mensaje. Inténtalo de nuevo dentro de un momento.","contact_network":"No se pudo enviar el mensaje. Revisa la conexión e inténtalo de nuevo.","contact_teaser_title":"Contacto","contact_teaser":"Las preguntas sobre colaboraciones, errores o privacidad van en la página de contacto. La respuesta se envía al correo que escribas. Las fotos del rostro no van en el mensaje.","atlas_help":"Elige el nombre de un animal para leer su perfil. Puedes ver la guía sin una foto del rostro.","lead":"La comparación usa proporciones de longitud del rostro, los ojos, la nariz, la boca y la mandíbula, no el pelo ni las orejas. La puntuación es la distancia respecto a nueve perfiles de animales. No es un test de personalidad ni una clasificación científica.","cat_title":"Rostro de gato — Guía de rostros animales","cat_meta":"Un perfil de ojos grandes con nariz y boca pequeñas, de modo que los rasgos parecen reunirse hacia el centro.","cat_h1":"Rostro de gato","cat_p1":"Un rostro de gato es la impresión de que los ojos, la nariz y la boca se sitúan hacia el centro del rostro. El perfil de gato de esta guía se acerca cuando el rostro es un poco redondo, los ojos son grandes y la nariz y la boca son menores que la media.","cat_p2":"El ancho del rostro es generoso comparado con el alto, y los ojos ocupan más del ancho del rostro. Una nariz más estrecha y corta, y una boca más pequeña, se inclinan hacia el gato. La zona media, de los ojos a la punta de la nariz, es corta.","cat_p3":"Una puntuación alta significa que, juntas, las diez proporciones están más cerca del perfil de gato. Unos ojos grandes por sí solos no hacen un rostro de gato. Una nariz y una boca anchas pueden quedar más cerca del oso o del león.","cat_p4":"Una sonrisa ensancha la boca y puede inclinar el resultado hacia el cachorro o el león. Girar la cabeza hace que los ojos se vean más pequeños de lo que son. Una foto de frente con la boca cerrada es la comparación más fácil para este perfil.","dog_title":"Rostro de cachorro — Guía de rostros animales","dog_meta":"Un perfil de ojos redondos y boca ancha, el aspecto que esta guía trata como suave y amistoso.","dog_h1":"Rostro de cachorro","dog_p1":"Un rostro de cachorro es la impresión de ojos redondos y boca ancha, así que la expresión se ve suave. La nariz se queda cerca de la media, y un rostro algo redondo se acerca al perfil de cachorro.","dog_p2":"El perfil de cachorro se acerca cuando la forma del ojo, el alto del ojo dividido por su ancho, es redonda y la boca es ancha en el rostro. Una separación un poco mayor entre los ojos forma parte de la misma lectura.","dog_p3":"Una boca ancha por sí sola no es un rostro de cachorro. Si la nariz y la mandíbula también son anchas, el león o el oso pueden estar más cerca. Unos ojos estrechos mueven el resultado hacia el zorro o el lobo.","dog_p4":"Una gran sonrisa aumenta la proporción de la boca. Si quieres la impresión de todos los días, mide también una foto con la boca cerrada.","fox_title":"Rostro de zorro — Guía de rostros animales","fox_meta":"Un perfil de rostro largo, mentón estrecho y ojos afilados.","fox_h1":"Rostro de zorro","fox_p1":"Un rostro de zorro es un contorno largo, un mentón estrecho y ojos afilados. Se separa de un rostro largo con ojos grandes, como el ciervo, por la forma de los ojos.","fox_p2":"El perfil de zorro se acerca cuando el alto del rostro supera el ancho, los ojos son estrechos y la punta del mentón es fina. La nariz es estrecha pero larga, y los ojos quedan un poco más juntos.","fox_p3":"El perfil de ciervo también es un rostro largo con mandíbula estrecha, pero el ciervo busca ojos más grandes y el zorro busca ojos estrechos y afilados. Si las dos puntuaciones están cerca, lee la forma de los ojos con ellas.","fox_p4":"Una vista de lado hace que el mentón se vea aún más estrecho. El pelo que tapa el mentón oculta su proporción. Usa una foto de frente en la que se vea la línea de la mandíbula.","rabbit_title":"Rostro de conejo — Guía de rostros animales","rabbit_meta":"Un perfil de ojos grandes y nariz y boca pequeñas, leído aquí como una impresión redonda y suave.","rabbit_h1":"Rostro de conejo","rabbit_p1":"Un rostro de conejo tiene ojos grandes y nariz y boca pequeñas, así que la impresión es redonda y suave. Es uno de los perfiles de esta guía que más mira el tamaño de los ojos.","rabbit_p2":"El rostro es redondo, los ojos son anchos, la forma del ojo es redonda y la separación entre los ojos es un poco amplia. El ancho y el largo de la nariz y el ancho de la boca son pequeños, y la zona media es corta.","rabbit_p3":"El perfil de búho también tiene ojos grandes y un rostro redondo. El búho se inclina más hacia una separación amplia de los ojos y un contorno más circular. El conejo se inclina hacia ojos grandes con nariz y boca pequeñas.","rabbit_p4":"Abrir mucho los ojos aumenta el alto del ojo y puede mover el resultado hacia el conejo o el búho. Para un tamaño de todos los días, es mejor una foto con los ojos abiertos con naturalidad.","owl_title":"Rostro de búho — Guía de rostros animales","owl_meta":"Un perfil de rostro muy redondo, ojos grandes y una separación amplia entre los ojos.","owl_h1":"Rostro de búho","owl_p1":"Un rostro de búho es un rostro muy redondo con ojos grandes, así que los rasgos se leen como circulares. Entre los nueve perfiles, este es el que más tira de la redondez del rostro.","owl_p2":"La redondez del rostro, el tamaño de los ojos, la forma redonda del ojo y la separación entre los ojos se leen del lado grande. La nariz y la boca son pequeñas y cortas, la punta del mentón es suavemente ancha y la zona media es corta.","owl_p3":"La puntuación suele quedar cerca del conejo. Una separación amplia de los ojos y un contorno cercano a un círculo se inclinan al búho. Si solo la nariz y la boca son pequeñas y queda algo de largo del rostro, lee el conejo y el gato junto a él.","owl_p4":"Un gran angular muy cerca deforma el centro del rostro hacia una forma más redonda. Al menos a la distancia de un brazo, el contorno se infla menos.","bear_title":"Rostro de oso — Guía de rostros animales","bear_meta":"Un perfil de rostro, nariz y mandíbula anchos, con ojos más pequeños.","bear_h1":"Rostro de oso","bear_p1":"Un rostro de oso es un rostro, una nariz y una mandíbula anchos, con ojos más pequeños: la impresión que esta guía lee como sólida y tranquila. Mira más el ancho del rostro que el tamaño de los ojos.","bear_p2":"El ancho de la nariz, el de la mandíbula y el mentón son más anchos que la media, y el tamaño de los ojos es pequeño. La boca es un poco ancha. La zona media se queda cerca de la media.","bear_p3":"El perfil de león también tiene nariz y mandíbula anchas. El león pone más peso en la boca y la mandíbula, y los ojos no necesitan ser muy pequeños. Unos ojos pequeños con ancho en todo el rostro quedan más cerca del oso.","bear_p4":"Una barba, una mascarilla o una mano ocultan el borde de la nariz y la mandíbula. Haz la foto de modo que se vean la punta de la nariz y la línea de la mandíbula.","lion_title":"Rostro de león — Guía de rostros animales","lion_meta":"Un perfil de nariz, boca y mandíbula anchas, de modo que los rasgos se leen amplios.","lion_h1":"Rostro de león","lion_p1":"Un rostro de león tiene nariz, boca y mandíbula anchas, así que los rasgos se ven fuertes. Este perfil mira el ancho de la parte baja del rostro más que el tamaño de los ojos o el largo del rostro.","lion_p2":"El ancho de la nariz, de la boca y de la mandíbula se leen del lado ancho. El tamaño de los ojos es un poco menor que la media, y la redondez de todo el rostro no se aleja mucho de la media.","lion_p3":"El perfil de cachorro también tiene una boca ancha, pero con ojos redondos y amistosos. La puntuación del león la tira más el ancho de la nariz, la boca y la mandíbula que los ojos.","lion_p4":"Sonreír o hablar hace la boca más ancha. Compáralo con una foto de boca cerrada para ver si la expresión creó la diferencia.","deer_title":"Rostro de ciervo — Guía de rostros animales","deer_meta":"Un perfil de rostro largo, ojos grandes y mandíbula y mentón estrechos.","deer_h1":"Rostro de ciervo","deer_p1":"Un rostro de ciervo es un rostro largo con ojos grandes y mandíbula estrecha, una línea fina y suave en esta guía. Entre los rostros largos, el de ojos más grandes se lee como ciervo.","deer_p2":"El alto del rostro es largo, los ojos son grandes, la nariz es estrecha, la mandíbula y la punta del mentón son finas y la zona media es larga. La forma del ojo no tiene que ser tan estrecha como la del zorro.","deer_p3":"El zorro y el lobo también son rostros largos. El ciervo es la combinación de ojos grandes y mandíbula fina. El lobo es la combinación de ojos estrechos y una zona media larga.","deer_p4":"Una cámara que mira desde arriba acorta la mandíbula. Cuando la cámara está a la altura de los ojos, el alto del rostro se deforma menos.","wolf_title":"Rostro de lobo — Guía de rostros animales","wolf_meta":"Un perfil de ojos estrechos y una zona media y una nariz largas.","wolf_h1":"Rostro de lobo","wolf_p1":"Un rostro de lobo tiene ojos estrechos y una zona media larga, así que el contorno se ve afilado. La boca se queda cerca de la media, y el rostro largo se lee por la distancia entre los ojos y la nariz.","wolf_p2":"El alto del ojo es corto, los ojos quedan más juntos, y tanto la nariz como el tramo de los ojos a la punta de la nariz son largos. El rostro es alargado y la punta del mentón se lee estrecha.","wolf_p3":"El perfil de zorro suele ser el vecino. El zorro pone más peso en una punta de mentón más fina y una nariz más estrecha. El lobo pone más peso en los ojos estrechos y el largo de la zona media.","wolf_p4":"Entrecerrar los ojos puede subir el lado del lobo solo por la proporción de la forma del ojo. Haz la foto con los ojos abiertos como suelen estar."},"pt":{"nav_label":"Menu do guia","nav_tool":"Medir um rosto","nav_method":"Como a medição funciona","nav_about":"Sobre","nav_privacy":"Privacidade","nav_contact":"Contato","theme_group":"Tema","theme_light":"Claro","theme_dark":"Escuro","language_group":"Idioma","footer":"As fotos são processadas só neste navegador e não são enviadas. O resultado é uma comparação lúdica das proporções do rosto, não um teste científico nem de personalidade. Expressão, ângulo, óculos e luz podem mudar a ordem.","try_tool":"Medir um rosto com este guia","read_method":"Ler como as dez proporções são medidas","other_animals":"Outros perfis de animais","animal_ratio_heading":"Proporções que se inclinam para cá","animal_score_heading":"O que uma pontuação próxima significa","animal_photo_heading":"Quando a foto muda a posição","name_cat":"Rosto de gato","name_dog":"Rosto de filhote","name_fox":"Rosto de raposa","name_rabbit":"Rosto de coelho","name_owl":"Rosto de coruja","name_bear":"Rosto de urso","name_lion":"Rosto de leão","name_deer":"Rosto de cervo","name_wolf":"Rosto de lobo","method_title":"Como a medição funciona — Guia de rostos de animais","method_meta":"Explica como as proporções de comprimento do rosto, dos olhos, do nariz, da boca e do maxilar são medidas e comparadas com nove perfis de animais.","method_h1":"Como a medição funciona","method_lead":"Este guia não olha cabelo, orelhas nem roupa. Ele lê comprimentos no rosto da foto e compara só esses comprimentos divididos pelo tamanho do rosto. A contagem de pixels muda com a distância, então o número bruto de pixels não é a pontuação.","method_measure":"A análise acontece neste navegador. A foto não é enviada a um servidor. Se houver vários rostos na área escolhida, o maior é usado. As médias abaixo são o ponto de partida deste guia para uma foto de frente. Não são uma faixa médica normal.","method_ratios_heading":"As dez proporções","method_r1":"Formato do rosto. Largura do rosto dividida pela altura do rosto. Um número maior é um rosto mais largo, e um menor é um rosto mais comprido. A média deste guia é 0.82.","method_r2":"Tamanho dos olhos. Largura do olho dividida pela largura do rosto. 0.20 significa que a largura do olho é 20% da largura do rosto.","method_r3":"Formato dos olhos. Altura do olho dividida pela largura do olho. Maior é mais redondo, menor é mais estreito e afilado. A média aqui é 0.33.","method_r4":"Distância entre os olhos. A distância entre os olhos dividida pela largura do rosto. A média fica perto de 0.25.","method_r5":"Largura do nariz. Largura do nariz dividida pela largura do rosto. A média fica perto de 0.28.","method_r6":"Comprimento do nariz. Comprimento do nariz dividido pela altura do rosto. A média é 0.30.","method_r7":"Largura da boca. Largura da boca dividida pela largura do rosto. A média fica perto de 0.40.","method_r8":"Largura do maxilar. A parte mais larga do maxilar dividida pela largura do rosto. A média é 0.80.","method_r9":"Queixo. Largura do queixo dividida pela largura do rosto. A média é 0.32.","method_r10":"Meio do rosto. O comprimento dos olhos à ponta do nariz dividido pela altura do rosto. A média é 0.25.","method_score_heading":"Como a pontuação é feita","method_score":"Cada proporção vira uma distância em relação à média e depois é comparada com o perfil de cada animal. Traços que formam a impressão, como o tamanho dos olhos, pesam um pouco mais. Traços que mudam fácil de uma foto para outra, como a ponta do queixo, pesam menos. O animal mais próximo recebe a pontuação mais alta. A pontuação para em 94. Nunca mostra 100, para que o erro de uma foto não pareça uma combinação perfeita.","method_photo_heading":"Quando a mesma pessoa fica em outra posição","method_photo":"Virar a cabeça, apertar os olhos, um sorriso largo, uma luz muito fraca ou um rosto minúsculo no quadro podem mudar a posição. Uma foto de frente, com os olhos na altura da câmera e a boca fechada, é mais fácil de comparar. A armação dos óculos que cobre o canto externo do olho pode errar o comprimento do olho. Uma grande-angular muito perto deixa o meio do rosto mais redondo.","method_animals_heading":"Os nove perfis de animais","method_animals":"Cada animal procura uma mistura diferente de proporções maiores e menores. Escolha um nome para ler esse perfil sozinho. As páginas não repetem um parágrafo mudando só o nome do animal.","about_title":"Sobre — Guia de rostos de animais","about_meta":"O que o Guia de rostos de animais compara, onde a foto fica e como ler o resultado.","about_h1":"Sobre este guia","about_p1":"O Guia de rostos de animais é um programa do navegador que compara proporções de comprimento de uma foto do rosto com perfis de gato, filhote, raposa, coelho, coruja, urso, leão, cervo e lobo. Ele promete uma coisa: medir as proporções da área que você escolhe e mostrar qual dos nove perfis é o mais próximo.","about_p2":"O arquivo da foto é lido só neste navegador e não é enviado a um servidor de análise. Ao fechar a página, a foto vai junto. Neste dispositivo ficam só o idioma escolhido e o tema claro ou escuro.","about_p3":"O resultado é uma comparação lúdica. A ferramenta não foi feita para descrever personalidade, nem para medicina, genética ou verificação de identidade. Perguntas sobre o site, erros ou privacidade vão para a página de contato.","privacy_title":"Privacidade — Guia de rostos de animais","privacy_meta":"Como fotos do rosto, idioma, anúncios, comentários e o formulário de contato tratam as informações.","privacy_h1":"Privacidade","privacy_photo_heading":"Fotos do rosto","privacy_photo":"Uma foto do rosto tirada com a câmera ou enviada para análise é tratada só na memória deste navegador. Ela não é enviada a um servidor do Guia de rostos de animais nem salva numa conta. Ao fechar a página ou escolher outra foto, a anterior não fica guardada.","privacy_store_heading":"Ajustes que ficam neste dispositivo","privacy_store":"O idioma escolhido fica neste navegador com o nome language_code, e o tema claro ou escuro com theme_mode. Esses valores só restauram a mesma vista na próxima visita. Eles não são enviados com a foto do rosto.","privacy_ads_heading":"Publicidade","privacy_ads":"Este site usa anúncios automáticos do Google AdSense. Quando um anúncio aparece, o Google pode usar cookies ou identificadores parecidos para escolher e medir anúncios. A descrição do Google sobre informações usadas em anúncios está em https://policies.google.com/technologies/ads . Para a propriedade do site, o id de editor ca-pub-8803401825336300 está numa meta tag no cabeçalho da página e em ads.txt na raiz do site.","privacy_disqus_heading":"Comentários","privacy_disqus":"Os comentários aparecem só no fim da página de medição e são tratados pelo Disqus. Escrever um comentário exige login ou cadastro no Disqus, e o Disqus pode usar os próprios cookies. O texto do comentário fica separado das fotos do rosto. O Disqus descreve as práticas de privacidade em https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Formulário de contato","privacy_form":"Só quando você pressiona enviar na página de contato, nome, empresa ou marca, e-mail de resposta e mensagem chegam ao Formspree (https://formspree.io). A foto do rosto não faz parte desses campos. Se você não enviar o formulário, o texto que estava digitando não é guardado.","privacy_font_heading":"Fontes","privacy_font":"As fontes são carregadas do Google Fonts. Ao abrir a página, o navegador pede arquivos de fonte a fonts.googleapis.com e fonts.gstatic.com. Esse pedido pode incluir o endereço da página e as informações habituais do navegador.","privacy_ask_heading":"Perguntas","privacy_ask":"Se algo aqui estiver faltando ou errado, avise na página de contato. As fotos do rosto não estão num servidor, então não há arquivo para devolver. A remoção de comentários é tratada no Disqus. Um pedido para apagar uma consulta já enviada pode ser feito pela página de contato e pela caixa que a recebeu.","contact_title":"Contato — Guia de rostos de animais","contact_meta":"Página de contato para perguntas de parceria, erro e privacidade sobre o Guia de rostos de animais.","contact_h1":"Contato","contact_help":"Deixe uma pergunta de parceria, erro ou privacidade. A foto do rosto não é anexada a este formulário. A resposta vai para o e-mail que você escrever.","contact_name":"Nome","contact_company":"Empresa ou marca","contact_email":"E-mail para a resposta","contact_message":"Mensagem","contact_send":"Enviar mensagem","contact_subject":"Consulta do Guia de rostos de animais","contact_invalid":"Escreva seu nome, o e-mail de resposta e a mensagem, e envie de novo.","contact_sending":"Enviando sua mensagem.","contact_sent":"Sua mensagem foi enviada. Responderemos ao e-mail que você escreveu.","contact_fail":"A mensagem não pôde ser enviada. Tente de novo daqui a pouco.","contact_network":"A mensagem não pôde ser enviada. Verifique a conexão e tente de novo.","contact_teaser_title":"Contato","contact_teaser":"Perguntas sobre parcerias, erros ou privacidade vão para a página de contato. A resposta é enviada ao e-mail que você escrever. Fotos do rosto não entram na mensagem.","atlas_help":"Escolha o nome de um animal para ler o perfil. Você pode ver o guia sem uma foto do rosto.","lead":"A comparação usa proporções de comprimento do rosto, dos olhos, do nariz, da boca e do maxilar, não o cabelo nem as orelhas. A pontuação é a distância em relação a nove perfis de animais. Não é um teste de personalidade nem uma classificação científica.","cat_title":"Rosto de gato — Guia de rostos de animais","cat_meta":"Um perfil de olhos grandes com nariz e boca pequenos, de modo que os traços parecem se reunir no centro.","cat_h1":"Rosto de gato","cat_p1":"Um rosto de gato é a impressão de que olhos, nariz e boca ficam em direção ao meio do rosto. O perfil de gato deste guia se aproxima quando o rosto é um pouco redondo, os olhos são grandes e o nariz e a boca são menores que a média.","cat_p2":"A largura do rosto é generosa em relação à altura, e os olhos ocupam mais da largura do rosto. Um nariz mais estreito e curto, e uma boca menor, inclinam-se para o gato. O meio do rosto, dos olhos à ponta do nariz, é curto.","cat_p3":"Uma pontuação alta significa que, juntas, as dez proporções estão mais perto do perfil de gato. Olhos grandes sozinhos não fazem um rosto de gato. Nariz e boca largos podem ficar mais perto do urso ou do leão.","cat_p4":"Um sorriso alarga a boca e pode inclinar o resultado para o filhote ou o leão. Virar a cabeça faz os olhos parecerem menores do que são. Uma foto de frente com a boca fechada é a comparação mais fácil para este perfil.","dog_title":"Rosto de filhote — Guia de rostos de animais","dog_meta":"Um perfil de olhos redondos e boca larga, o aspecto que este guia trata como gentil e amigável.","dog_h1":"Rosto de filhote","dog_p1":"Um rosto de filhote é a impressão de olhos redondos e boca larga, então a expressão parece gentil. O nariz fica perto da média, e um rosto um pouco redondo se aproxima do perfil de filhote.","dog_p2":"O perfil de filhote se aproxima quando o formato do olho, a altura do olho dividida pela largura, é redondo e a boca é larga no rosto. Um espaço um pouco maior entre os olhos faz parte da mesma leitura.","dog_p3":"Uma boca larga sozinha não é um rosto de filhote. Se o nariz e o maxilar também forem largos, o leão ou o urso podem estar mais perto. Olhos estreitos levam o resultado para a raposa ou o lobo.","dog_p4":"Um grande sorriso aumenta a proporção da boca. Se quiser a impressão do dia a dia, meça também uma foto com a boca fechada.","fox_title":"Rosto de raposa — Guia de rostos de animais","fox_meta":"Um perfil de rosto comprido, queixo estreito e olhos afilados.","fox_h1":"Rosto de raposa","fox_p1":"Um rosto de raposa é um contorno comprido, um queixo estreito e olhos afilados. Ele se separa de um rosto comprido com olhos grandes, como o cervo, pelo formato dos olhos.","fox_p2":"O perfil de raposa se aproxima quando a altura do rosto passa da largura, os olhos são estreitos e a ponta do queixo é fina. O nariz é estreito mas comprido, e os olhos ficam um pouco mais juntos.","fox_p3":"O perfil de cervo também é um rosto comprido com maxilar estreito, mas o cervo procura olhos maiores e a raposa procura olhos estreitos e afilados. Se as duas pontuações estiverem perto, leia o formato dos olhos junto.","fox_p4":"Uma vista de lado deixa o queixo ainda mais estreito. Cabelo que cobre o queixo esconde a proporção. Use uma foto de frente em que a linha do maxilar apareça.","rabbit_title":"Rosto de coelho — Guia de rostos de animais","rabbit_meta":"Um perfil de olhos grandes e nariz e boca pequenos, lido aqui como uma impressão redonda e suave.","rabbit_h1":"Rosto de coelho","rabbit_p1":"Um rosto de coelho tem olhos grandes e nariz e boca pequenos, então a impressão é redonda e suave. É um dos perfis deste guia que mais olha o tamanho dos olhos.","rabbit_p2":"O rosto é redondo, os olhos são largos, o formato do olho é redondo e o espaço entre os olhos é um pouco amplo. Largura e comprimento do nariz e largura da boca são pequenos, e o meio do rosto é curto.","rabbit_p3":"O perfil de coruja também tem olhos grandes e um rosto redondo. A coruja se inclina mais para um espaço amplo entre os olhos e um contorno mais circular. O coelho se inclina para olhos grandes com nariz e boca pequenos.","rabbit_p4":"Abrir muito os olhos aumenta a altura do olho e pode mover o resultado para o coelho ou a coruja. Para um tamanho do dia a dia, uma foto com os olhos abertos naturalmente é melhor.","owl_title":"Rosto de coruja — Guia de rostos de animais","owl_meta":"Um perfil de rosto muito redondo, olhos grandes e um espaço amplo entre os olhos.","owl_h1":"Rosto de coruja","owl_p1":"Um rosto de coruja é um rosto muito redondo com olhos grandes, então os traços se leem como circulares. Entre os nove perfis, este é o que mais puxa a redondeza do rosto.","owl_p2":"A redondeza do rosto, o tamanho dos olhos, o formato redondo do olho e o espaço entre os olhos são lidos do lado grande. Nariz e boca são pequenos e curtos, a ponta do queixo é suavemente larga e o meio do rosto é curto.","owl_p3":"A pontuação costuma ficar perto do coelho. Um espaço amplo entre os olhos e um contorno perto de um círculo inclinam para a coruja. Se só o nariz e a boca forem pequenos e ainda restar algum comprimento do rosto, leia o coelho e o gato junto.","owl_p4":"Uma grande-angular muito perto distorce o meio do rosto para uma forma mais redonda. A pelo menos um braço de distância, o contorno infla menos.","bear_title":"Rosto de urso — Guia de rostos de animais","bear_meta":"Um perfil de rosto, nariz e maxilar largos, com olhos menores.","bear_h1":"Rosto de urso","bear_p1":"Um rosto de urso é um rosto, um nariz e um maxilar largos, com olhos menores: a impressão que este guia lê como sólida e tranquila. Ele olha mais a largura do rosto do que o tamanho dos olhos.","bear_p2":"A largura do nariz, a do maxilar e o queixo são mais largos que a média, e o tamanho dos olhos é pequeno. A boca é um pouco larga. O meio do rosto fica perto da média.","bear_p3":"O perfil de leão também tem nariz e maxilar largos. O leão põe mais peso na boca e no maxilar, e os olhos não precisam ser muito pequenos. Olhos pequenos com largura em todo o rosto ficam mais perto do urso.","bear_p4":"Uma barba, uma máscara ou uma mão esconde a borda do nariz e do maxilar. Tire a foto de modo que a ponta do nariz e a linha do maxilar apareçam.","lion_title":"Rosto de leão — Guia de rostos de animais","lion_meta":"Um perfil de nariz, boca e maxilar largos, de modo que os traços se leem amplos.","lion_h1":"Rosto de leão","lion_p1":"Um rosto de leão tem nariz, boca e maxilar largos, então os traços parecem fortes. Este perfil olha a largura da parte de baixo do rosto mais do que o tamanho dos olhos ou o comprimento do rosto.","lion_p2":"A largura do nariz, da boca e do maxilar é lida do lado largo. O tamanho dos olhos é um pouco menor que a média, e a redondeza de todo o rosto não se afasta muito da média.","lion_p3":"O perfil de filhote também tem boca larga, mas com olhos redondos e amigáveis. A pontuação do leão é puxada mais pela largura do nariz, da boca e do maxilar do que pelos olhos.","lion_p4":"Sorrir ou falar deixa a boca mais larga. Compare com uma foto de boca fechada para ver se a expressão criou a diferença.","deer_title":"Rosto de cervo — Guia de rostos de animais","deer_meta":"Um perfil de rosto comprido, olhos grandes e maxilar e queixo estreitos.","deer_h1":"Rosto de cervo","deer_p1":"Um rosto de cervo é um rosto comprido com olhos grandes e maxilar estreito, uma linha fina e suave neste guia. Entre os rostos compridos, o de olhos maiores é lido como cervo.","deer_p2":"A altura do rosto é comprida, os olhos são grandes, o nariz é estreito, o maxilar e a ponta do queixo são finos e o meio do rosto é longo. O formato do olho não precisa ser tão estreito quanto o da raposa.","deer_p3":"A raposa e o lobo também são rostos compridos. O cervo é a combinação de olhos grandes e maxilar fino. O lobo é a combinação de olhos estreitos e um meio do rosto longo.","deer_p4":"Uma câmera olhando de cima encurta o maxilar. Quando a câmera está na altura dos olhos, a altura do rosto se distorce menos.","wolf_title":"Rosto de lobo — Guia de rostos de animais","wolf_meta":"Um perfil de olhos estreitos e um meio do rosto e um nariz longos.","wolf_h1":"Rosto de lobo","wolf_p1":"Um rosto de lobo tem olhos estreitos e um meio do rosto longo, então o contorno parece afilado. A boca fica perto da média, e o rosto comprido é lido pela distância entre os olhos e o nariz.","wolf_p2":"A altura do olho é curta, os olhos ficam mais juntos, e tanto o nariz quanto o trecho dos olhos à ponta do nariz são longos. O rosto é alongado e a ponta do queixo é lida como estreita.","wolf_p3":"O perfil de raposa costuma ser o vizinho. A raposa põe mais peso numa ponta de queixo mais fina e num nariz mais estreito. O lobo põe mais peso nos olhos estreitos e no comprimento do meio do rosto.","wolf_p4":"Apertar os olhos pode elevar o lado do lobo só pela proporção do formato do olho. Tire a foto com os olhos abertos como costumam estar."},"ar":{"nav_label":"قائمة الدليل","nav_tool":"قياس الوجه","nav_method":"طريقة القياس","nav_about":"عن الدليل","nav_privacy":"الخصوصية","nav_contact":"تواصل","theme_group":"المظهر","theme_light":"فاتح","theme_dark":"داكن","language_group":"اللغة","footer":"تُعالَج الصور داخل هذا المتصفح فقط ولا تُرفع. النتيجة مقارنة مرحة لنسب الوجه، وليست اختبارًا علميًا أو للشخصية. التعبير والزاوية والنظارات والضوء قد تغيّر الترتيب.","try_tool":"قس وجهًا بهذا الدليل","read_method":"اقرأ كيف تُقاس النسب العشر","other_animals":"ملفات حيوانات أخرى","animal_ratio_heading":"النسب التي تميل إلى هذا الاتجاه","animal_score_heading":"ماذا تعني الدرجة القريبة","animal_photo_heading":"عندما تغيّر الصورة الترتيب","name_cat":"وجه قطة","name_dog":"وجه جرو","name_fox":"وجه ثعلب","name_rabbit":"وجه أرنب","name_owl":"وجه بومة","name_bear":"وجه دب","name_lion":"وجه أسد","name_deer":"وجه غزال","name_wolf":"وجه ذئب","method_title":"طريقة القياس — دليل وجوه الحيوانات","method_meta":"يشرح كيف تُقاس نسب طول الوجه والعينين والأنف والفم والفك ثم تُقارن مع تسعة ملفات حيوانية.","method_h1":"طريقة القياس","method_lead":"هذا الدليل لا ينظر إلى الشعر ولا الأذنين ولا الملابس. يقرأ أطوالًا على الوجه في الصورة ويقارن تلك الأطوال فقط بعد قسمتها على حجم الوجه. عدد البكسل يتغير مع المسافة، لذلك عدد البكسل الخام ليس درجة.","method_measure":"يجري التحليل داخل هذا المتصفح. لا تُرسل الصورة إلى خادم. إذا ظهرت عدة وجوه في المنطقة التي حددتها، يُستخدم الوجه الأكبر. المتوسطات أدناه نقطة بداية هذا الدليل لصور من الأمام. ليست نطاقًا طبيًا طبيعيًا.","method_ratios_heading":"النسب العشر","method_r1":"شكل الوجه. عرض الوجه مقسومًا على ارتفاع الوجه. الرقم الأكبر وجه أعرض، والرقم الأصغر وجه أطول. متوسط هذا الدليل هو 0.82.","method_r2":"حجم العين. عرض العين مقسومًا على عرض الوجه. 0.20 يعني أن عرض العين يساوي 20% من عرض الوجه.","method_r3":"شكل العين. ارتفاع العين مقسومًا على عرض العين. الأكبر أكثر استدارة، والأصغر أضيق وأحدّ. المتوسط هنا 0.33.","method_r4":"المسافة بين العينين. المسافة بين العينين مقسومة على عرض الوجه. المتوسط قريب من 0.25.","method_r5":"عرض الأنف. عرض الأنف مقسومًا على عرض الوجه. المتوسط قريب من 0.28.","method_r6":"طول الأنف. طول الأنف مقسومًا على ارتفاع الوجه. المتوسط 0.30.","method_r7":"عرض الفم. عرض الفم مقسومًا على عرض الوجه. المتوسط قريب من 0.40.","method_r8":"عرض الفك. الجزء الأعرض من الفك مقسومًا على عرض الوجه. المتوسط 0.80.","method_r9":"الذقن. عرض الذقن مقسومًا على عرض الوجه. المتوسط 0.32.","method_r10":"منتصف الوجه. الطول من العينين إلى طرف الأنف مقسومًا على ارتفاع الوجه. المتوسط 0.25.","method_score_heading":"كيف تُحسب الدرجة","method_score":"تتحول كل نسبة إلى مسافة عن المتوسط، ثم تُقارن بملف كل حيوان. السمات التي تصنع الانطباع، مثل حجم العين، تُوزن أكثر قليلًا. السمات التي تتغير بسهولة من صورة إلى أخرى، مثل طرف الذقن، تُوزن أقل. الحيوان الأقرب يحصل على درجة أعلى. تتوقف الدرجة عند 94. لا تظهر 100 أبدًا، حتى لا يُعرض خطأ صورة واحدة كأنه تطابق كامل.","method_photo_heading":"عندما يحصل الشخص نفسه على ترتيب مختلف","method_photo":"إدارة الرأس أو تضييق العينين أو ابتسامة عريضة أو ضوء خافت جدًا أو وجه صغير جدًا في الإطار قد يغيّر الترتيب. الصورة من الأمام، والعينان في مستوى الكاميرا، والفم مغلق، أسهل للمقارنة. إطار النظارة الذي يغطي زاوية العين قد يخطئ في طول العين. لقطة واسعة من مسافة قريبة جدًا تجعل منتصف الوجه يبدو أكثر استدارة.","method_animals_heading":"تسعة ملفات حيوانية","method_animals":"كل حيوان يبحث عن مزيج مختلف من النسب الكبيرة والصغيرة. اختر اسمًا لقراءة ذلك الملف وحده. هذه الصفحات ليست تكرار فقرة واحدة مع تبديل اسم الحيوان فقط.","about_title":"عن الدليل — دليل وجوه الحيوانات","about_meta":"ما الذي يقارنه دليل وجوه الحيوانات، وأين تبقى الصورة، وكيف تُقرأ النتيجة.","about_h1":"عن هذا الدليل","about_p1":"دليل وجوه الحيوانات برنامج في المتصفح يقارن نسب الطول في صورة الوجه مع ملفات القطة والجرو والثعلب والأرنب والبومة والدب والأسد والغزال والذئب. يعد بأمر واحد: قياس النسب داخل المنطقة التي تحددها، ثم إظهار أي ملف من التسعة هو الأقرب.","about_p2":"يُقرأ ملف الصورة داخل هذا المتصفح فقط ولا يُرفع إلى خادم تحليل. عندما تغلق الصفحة تذهب الصورة معها. على هذا الجهاز يُحفظ فقط اللغة التي اخترتها والمظهر الفاتح أو الداكن.","about_p3":"النتيجة مقارنة مرحة. الأداة ليست لوصف الشخصية، وليست للطب أو الوراثة أو التحقق من الهوية. أسئلة الموقع أو الأخطاء أو الخصوصية تُرسل من صفحة التواصل.","privacy_title":"الخصوصية — دليل وجوه الحيوانات","privacy_meta":"كيف تُعالَج صور الوجه وإعداد اللغة والإعلانات والتعليقات ونموذج التواصل.","privacy_h1":"الخصوصية","privacy_photo_heading":"صور الوجه","privacy_photo":"صورة الوجه الملتقطة بالكاميرا أو المرفوعة للتحليل تُعالَج فقط في ذاكرة هذا المتصفح. لا تُرسل إلى خادم دليل وجوه الحيوانات ولا تُحفظ في حساب. عندما تغلق الصفحة أو تختار صورة أخرى، لا تُحتفظ بالصورة السابقة.","privacy_store_heading":"إعدادات تبقى على هذا الجهاز","privacy_store":"تُحفظ اللغة المختارة في هذا المتصفح تحت الاسم language_code، والمظهر الفاتح أو الداكن تحت theme_mode. هذه القيم تعيد العرض نفسه في الزيارة التالية فقط. لا تُرسل مع صورة الوجه.","privacy_ads_heading":"الإعلانات","privacy_ads":"يستخدم هذا الموقع إعلانات Google AdSense التلقائية. عند ظهور إعلان، قد تستخدم Google ملفات تعريف الارتباط أو معرّفات مشابهة لاختيار الإعلان وقياسه. وصف Google للمعلومات المستخدمة في الإعلانات موجود في https://policies.google.com/technologies/ads . لتأكيد مالك الموقع، يظهر معرّف الناشر ca-pub-8803401825336300 في وسم meta أعلى الصفحة وفي ads.txt في جذر الموقع.","privacy_disqus_heading":"التعليقات","privacy_disqus":"تظهر التعليقات فقط أسفل صفحة القياس وتتولى Disqus معالجتها. كتابة تعليق تحتاج إلى تسجيل الدخول أو إنشاء حساب في Disqus، وقد تستخدم Disqus ملفات تعريف الارتباط الخاصة بها. يُحفظ نص التعليق منفصلًا عن صورة الوجه. تشرح Disqus طريقة تعاملها مع الخصوصية في https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"نموذج التواصل","privacy_form":"فقط عندما تضغط على الإرسال في صفحة التواصل، يُنقل الاسم والشركة أو العلامة والبريد لاستلام الرد والرسالة إلى Formspree ‏(https://formspree.io). صورة الوجه ليست ضمن هذه الحقول. إذا لم تُرسل النموذج، لا يُحفظ النص الذي تكتبه.","privacy_font_heading":"الخطوط","privacy_font":"تُحمَّل الخطوط من Google Fonts. عند فتح الصفحة يطلب المتصفح ملفات الخط من fonts.googleapis.com وfonts.gstatic.com. قد يتضمن الطلب عنوان الصفحة ومعلومات المتصفح المعتادة.","privacy_ask_heading":"أسئلة","privacy_ask":"إذا نقص شيء هنا أو وُجد خطأ، أبلغ عنه من صفحة التواصل. صورة الوجه ليست على الخادم، لذلك لا يوجد ملف لإرجاعه. حذف التعليقات يتم داخل Disqus. يمكن تمرير طلب حذف رسالة أُرسلت عبر صفحة التواصل وصندوق البريد الذي استلمها.","contact_title":"تواصل — دليل وجوه الحيوانات","contact_meta":"صفحة التواصل لأسئلة الشراكة والأخطاء والخصوصية عن دليل وجوه الحيوانات.","contact_h1":"تواصل","contact_help":"اترك سؤال شراكة أو خطأ أو خصوصية. صورة الوجه لا تُرفق بهذا النموذج. يصل الرد إلى البريد الذي تدخله.","contact_name":"الاسم","contact_company":"الشركة أو العلامة","contact_email":"البريد لاستلام الرد","contact_message":"الرسالة","contact_send":"إرسال","contact_subject":"سؤال إلى دليل وجوه الحيوانات","contact_invalid":"أدخل الاسم والبريد لاستلام الرد والرسالة، ثم أرسل مرة أخرى.","contact_sending":"جارٍ إرسال رسالتك.","contact_sent":"تم إرسال الرسالة. سنرد على البريد الذي أدخلته.","contact_fail":"تعذّر إرسال الرسالة. حاول مرة أخرى بعد لحظة.","contact_network":"تعذّر إرسال الرسالة. تحقق من الاتصال ثم حاول مرة أخرى.","contact_teaser_title":"تواصل","contact_teaser":"أسئلة الشراكة أو الأخطاء أو الخصوصية تُرسل من صفحة التواصل. يصل الرد إلى البريد الذي تدخله. صورة الوجه ليست ضمن الرسالة.","atlas_help":"اختر اسم حيوان لقراءة ملفه. يمكنك تصفح الدليل من دون صورة وجه.","lead":"المقارنة تستخدم نسب طول الوجه والعينين والأنف والفم والفك، لا الشعر ولا الأذنين. الدرجة هي المسافة إلى تسعة ملفات حيوانية. هذا ليس اختبار شخصية ولا تصنيفًا علميًا.","cat_title":"وجه قطة — دليل وجوه الحيوانات","cat_meta":"ملف لعينين كبيرتين وأنف وفم صغيرين، فتبدو ملامح الوجه مجتمعة نحو الوسط.","cat_h1":"وجه قطة","cat_p1":"وجه القطة انطباع بأن العينين والأنف والفم يجلسون أقرب إلى منتصف الوجه. يقترب ملف القطة في هذا الدليل عندما يكون الوجه مستديرًا قليلًا، والعينان كبيرتين، والأنف والفم أصغر من المتوسط.","cat_p2":"عرض الوجه وافر مقارنة بارتفاعه، والعينان تشغلان حصة أكبر من عرض الوجه. أنف أضيق وأقصر وفم أصغر يميلان إلى القطة. منتصف الوجه، من العينين إلى طرف الأنف، في الجانب القصير.","cat_p3":"الدرجة العالية تعني أن النسب العشر معًا هي الأقرب إلى ملف القطة. العينان الكبيرتان وحدهما لا تصنعان وجه قطة. الأنف والفم العريضان قد يكونان أقرب إلى الدب أو الأسد.","cat_p4":"الابتسامة توسّع الفم وقد تدفع النتيجة نحو الجرو أو الأسد. إدارة الرأس تجعل العينين تبدوان أصغر مما هما. الصورة من الأمام والفم مغلق أسهل للمقارنة مع هذا الملف.","dog_title":"وجه جرو — دليل وجوه الحيوانات","dog_meta":"ملف لعينين مستديرتين وفم عريض، وهو مظهر يقرأه هذا الدليل على أنه لطيف وودود.","dog_h1":"وجه جرو","dog_p1":"وجه الجرو انطباع بعينين مستديرتين وفم عريض، لذلك يبدو التعبير لطيفًا. يبقى الأنف قرب المتوسط، والوجه المستدير قليلًا أقرب إلى ملف الجرو.","dog_p2":"يقترب ملف الجرو عندما يكون شكل العين، أي ارتفاع العين مقسومًا على عرضها، مستديرًا ويكون الفم عريضًا على الوجه. مسافة أوسع قليلًا بين العينين تدخل في القراءة نفسها.","dog_p3":"الفم العريض وحده ليس وجه جرو. إذا كان الأنف والفك عريضين أيضًا، فقد يكون الأسد أو الدب أقرب. العينان الضيقتان تدفعان النتيجة نحو الثعلب أو الذئب.","dog_p4":"الابتسامة العريضة تزيد نسبة الفم. إذا أردت الانطباع اليومي، قس أيضًا صورة والفم مغلق.","fox_title":"وجه ثعلب — دليل وجوه الحيوانات","fox_meta":"ملف لوجه طويل وذقن ضيق وعينين حادتين.","fox_h1":"وجه ثعلب","fox_p1":"وجه الثعلب خط طويل وذقن ضيق وعينان حادتان. يفصله عن الوجه الطويل ذي العينين الكبيرتين، مثل الغزال، شكل العين.","fox_p2":"يقترب ملف الثعلب عندما يتجاوز ارتفاع الوجه عرضه، وتكون العينان ضيقتين وطرف الذقن رفيعًا. الأنف ضيق لكنه طويل، والعينان أقرب إلى بعضهما قليلًا.","fox_p3":"ملف الغزال أيضًا وجه طويل بفك ضيق، لكن الغزال يبحث عن عينين أكبر والثعلب عن عينين ضيقتين حادتين. إذا تقاربت الدرجتان، اقرأ شكل العين معهما.","fox_p4":"الزاوية الجانبية تجعل الذقن يبدو أضيق. الشعر الذي يغطي الذقن يخفي نسبته. استخدم صورة من الأمام يظهر فيها خط الفك.","rabbit_title":"وجه أرنب — دليل وجوه الحيوانات","rabbit_meta":"ملف لعينين كبيرتين وأنف وفم صغيرين، ويُقرأ هنا كانطباع مستدير وناعم.","rabbit_h1":"وجه أرنب","rabbit_p1":"لوجه الأرنب عينان كبيرتان وأنف وفم صغيران، لذلك يكون الانطباع مستديرًا وناعمًا. هذا أحد ملفات الدليل التي تنظر بقوة إلى حجم العين.","rabbit_p2":"الوجه مستدير، والعينان واسعتان، وشكل العين مستدير، والمسافة بين العينين أوسع قليلًا. عرض الأنف وطوله وعرض الفم كلها صغيرة، ومنتصف الوجه قصير.","rabbit_p3":"ملف البومة أيضًا له عينان كبيرتان ووجه مستدير. تميل البومة أكثر إلى مسافة واسعة بين العينين وخط أقرب إلى الدائرة. يميل الأرنب إلى عينين كبيرتين مع أنف وفم صغيرين.","rabbit_p4":"فتح العينين على وسعهما يزيد ارتفاع العين وقد يدفع النتيجة نحو الأرنب أو البومة. للحجم اليومي، صورة والعينان مفتوحتان بشكل طبيعي أفضل.","owl_title":"وجه بومة — دليل وجوه الحيوانات","owl_meta":"ملف لوجه شديد الاستدارة وعينين كبيرتين ومسافة واسعة بين العينين.","owl_h1":"وجه بومة","owl_p1":"وجه البومة وجه شديد الاستدارة بعينين كبيرتين، لذلك تُقرأ ملامح الوجه كدائرة. بين الملفات التسعة، يسحب هذا الملف استدارة الوجه بقوة أكبر.","owl_p2":"تُقرأ استدارة الوجه وحجم العين وشكلها المستدير والمسافة بين العينين في الجانب الكبير. الأنف والفم صغيران وقصيران، وطرف الذقن عريض بنعومة، ومنتصف الوجه قصير.","owl_p3":"تقع الدرجة غالبًا قرب الأرنب. المسافة الواسعة بين العينين والخط القريب من الدائرة يميلان إلى البومة. إذا كان الأنف والفم صغيرين فقط وما زال في الوجه طول، اقرأ الأرنب والقطة معًا.","owl_p4":"لقطة واسعة من مسافة قريبة جدًا تضغط منتصف الوجه إلى شكل أكثر استدارة. من مسافة ذراع على الأقل يقل انتفاخ الخط.","bear_title":"وجه دب — دليل وجوه الحيوانات","bear_meta":"ملف لوجه وأنف وفك عريضة مع عينين أصغر.","bear_h1":"وجه دب","bear_p1":"وجه الدب وجه وأنف وفك عريضة مع عينين أصغر، وهو انطباع يقرأه هذا الدليل على أنه متين وهادئ. ينظر إلى عرض الوجه أكثر من حجم العين.","bear_p2":"عرض الأنف وعرض الفك والذقن أعرض من المتوسط، وحجم العين في الجانب الصغير. الفم أعرض قليلًا. يبقى منتصف الوجه قرب المتوسط.","bear_p3":"ملف الأسد أيضًا له أنف وفك عريضان. يضع الأسد وزنًا أكبر على الفم والفك، ولا يلزم أن تكون العينان صغيرتين جدًا. العينان الصغيرتان مع عرض الوجه كله أقرب إلى الدب.","bear_p4":"اللحية أو القناع أو اليد تغطي حافة الأنف والفك. صوّر بحيث يظهر طرف الأنف وخط الفك.","lion_title":"وجه أسد — دليل وجوه الحيوانات","lion_meta":"ملف لأنف وفم وفك عريضة، فتُقرأ ملامح الوجه على أنها عريضة.","lion_h1":"وجه أسد","lion_p1":"لوجه الأسد أنف وفم وفك عريضة، لذلك تبدو الملامح قوية. ينظر هذا الملف إلى عرض النصف السفلي من الوجه أكثر من حجم العين أو طول الوجه.","lion_p2":"يُقرأ عرض الأنف وعرض الفم وعرض الفك في الجانب العريض. حجم العين أصغر من المتوسط قليلًا، واستدارة الوجه كله لا تبتعد كثيرًا عن المتوسط.","lion_p3":"ملف الجرو أيضًا له فم عريض، لكن مع عينين مستديرتين وودودتين. تسحب درجة الأسد عروض الأنف والفم والفك أكثر مما تسحبها العينان.","lion_p4":"الابتسامة أو الكلام يجعلان الفم أعرض. قارن بصورة والفم مغلق لترى إن كان التعبير هو الذي صنع الفرق.","deer_title":"وجه غزال — دليل وجوه الحيوانات","deer_meta":"ملف لوجه طويل وعينين كبيرتين وفك وذقن ضيقين.","deer_h1":"وجه غزال","deer_p1":"وجه الغزال وجه طويل بعينين كبيرتين وفك ضيق، وهو خط رفيع ولطيف في هذا الدليل. بين الوجوه الطويلة، يُقرأ الوجه ذو العينين الأكبر على أنه غزال.","deer_p2":"ارتفاع الوجه طويل، والعينان كبيرتان، والأنف ضيق، والفك وطرف الذقن رفيعان، ومنتصف الوجه طويل. لا يلزم أن يكون شكل العين ضيقًا مثل الثعلب.","deer_p3":"الثعلب والذئب وجهان طويلان أيضًا. الغزال هو اجتماع عينين كبيرتين وفك رفيع. الذئب هو اجتماع عينين ضيقتين ومنتصف وجه طويل.","deer_p4":"الكاميرا من الأعلى تقصّر الفك. عندما تكون الكاميرا في مستوى العينين، يقل تشوه ارتفاع الوجه.","wolf_title":"وجه ذئب — دليل وجوه الحيوانات","wolf_meta":"ملف لعينين ضيقتين ومنتصف وجه وأنف طويلين.","wolf_h1":"وجه ذئب","wolf_p1":"لوجه الذئب عينان ضيقتان ومنتصف وجه طويل، لذلك يبدو الخط حادًا. يبقى الفم قرب المتوسط، ويُقرأ الوجه الطويل من المسافة بين العينين والأنف.","wolf_p2":"ارتفاع العين قصير، والعينان أقرب إلى بعضهما، والأنف والمسافة من العينين إلى طرف الأنف طويلان. الوجه في الجانب الطويل، ويُقرأ طرف الذقن على أنه ضيق.","wolf_p3":"ملف الثعلب غالبًا جار. يضع الثعلب وزنًا أكبر على طرف ذقن أرفع وأنف أضيق. يضع الذئب وزنًا أكبر على العينين الضيقتين وطول منتصف الوجه.","wolf_p4":"تضييق العينين قد يرفع جانب الذئب من نسبة شكل العين وحدها. صوّر والعينان مفتوحتان كما في العادة."},"fr":{"nav_label":"Menu du guide","nav_tool":"Mesurer un visage","nav_method":"Comment la mesure fonctionne","nav_about":"À propos","nav_privacy":"Confidentialité","nav_contact":"Contact","theme_group":"Thème","theme_light":"Clair","theme_dark":"Sombre","language_group":"Langue","footer":"Les photos sont traitées seulement dans ce navigateur et ne sont pas envoyées. Le résultat est une comparaison ludique des proportions du visage, pas un test scientifique ni de personnalité. L'expression, l'angle, les lunettes et la lumière peuvent changer le classement.","try_tool":"Mesurer un visage avec ce guide","read_method":"Lire comment les dix rapports sont mesurés","other_animals":"Autres profils d'animaux","animal_ratio_heading":"Rapports qui penchent de ce côté","animal_score_heading":"Ce qu'un score proche signifie","animal_photo_heading":"Quand la photo déplace le rang","name_cat":"Visage de chat","name_dog":"Visage de chiot","name_fox":"Visage de renard","name_rabbit":"Visage de lapin","name_owl":"Visage de hibou","name_bear":"Visage d'ours","name_lion":"Visage de lion","name_deer":"Visage de cerf","name_wolf":"Visage de loup","method_title":"Comment la mesure fonctionne — Guide des visages d'animaux","method_meta":"Explique comment les rapports de longueur du visage, des yeux, du nez, de la bouche et de la mâchoire sont mesurés et comparés à neuf profils d'animaux.","method_h1":"Comment la mesure fonctionne","method_lead":"Ce guide ne regarde ni les cheveux, ni les oreilles, ni les vêtements. Il lit des longueurs sur le visage de la photo et ne compare que ces longueurs divisées par la taille du visage. Le nombre de pixels change avec la distance, donc le nombre brut de pixels n'est pas le score.","method_measure":"L'analyse se fait dans ce navigateur. La photo n'est pas envoyée à un serveur. S'il y a plusieurs visages dans la zone choisie, le plus grand est utilisé. Les moyennes ci-dessous sont le point de départ de ce guide pour une photo de face. Ce n'est pas une plage médicale normale.","method_ratios_heading":"Les dix rapports","method_r1":"Forme du visage. Largeur du visage divisée par la hauteur du visage. Un nombre plus grand est un visage plus large, un nombre plus petit est un visage plus long. La moyenne de ce guide est 0.82.","method_r2":"Taille des yeux. Largeur de l'œil divisée par la largeur du visage. 0.20 signifie que la largeur de l'œil fait 20% de la largeur du visage.","method_r3":"Forme des yeux. Hauteur de l'œil divisée par la largeur de l'œil. Plus grand est plus rond, plus petit est plus étroit et plus vif. La moyenne ici est 0.33.","method_r4":"Écart des yeux. La distance entre les yeux divisée par la largeur du visage. La moyenne est proche de 0.25.","method_r5":"Largeur du nez. Largeur du nez divisée par la largeur du visage. La moyenne est proche de 0.28.","method_r6":"Longueur du nez. Longueur du nez divisée par la hauteur du visage. La moyenne est 0.30.","method_r7":"Largeur de la bouche. Largeur de la bouche divisée par la largeur du visage. La moyenne est proche de 0.40.","method_r8":"Largeur de la mâchoire. La partie la plus large de la mâchoire divisée par la largeur du visage. La moyenne est 0.80.","method_r9":"Menton. Largeur du menton divisée par la largeur du visage. La moyenne est 0.32.","method_r10":"Milieu du visage. La longueur des yeux à la pointe du nez divisée par la hauteur du visage. La moyenne est 0.25.","method_score_heading":"Comment le score est obtenu","method_score":"Chaque rapport est transformé en distance par rapport à la moyenne, puis comparé au profil fixé pour chaque animal. Les traits qui forment l'impression, comme la taille des yeux, comptent un peu plus. Les traits qui bougent facilement d'une photo à l'autre, comme la pointe du menton, comptent moins. L'animal le plus proche reçoit le score le plus haut. Le score s'arrête à 94. Il ne montre jamais 100, pour qu'une erreur de photo ne soit pas présentée comme une correspondance parfaite.","method_photo_heading":"Quand la même personne change de rang","method_photo":"Tourner la tête, plisser les yeux, un large sourire, une lumière très faible ou un visage minuscule dans le cadre peuvent changer le rang. Une photo de face, les yeux à hauteur de la caméra et la bouche fermée, est plus facile à comparer. Une monture qui couvre le coin externe de l'œil peut fausser la longueur de l'œil. Un très gros plan au grand-angle rend le milieu du visage plus rond.","method_animals_heading":"Les neuf profils d'animaux","method_animals":"Chaque animal cherche un mélange différent de rapports plus grands et plus petits. Choisissez un nom pour lire ce profil seul. Les pages ne répètent pas un paragraphe en changeant seulement le nom de l'animal.","about_title":"À propos — Guide des visages d'animaux","about_meta":"Ce que le Guide des visages d'animaux compare, où reste la photo et comment lire le résultat.","about_h1":"À propos de ce guide","about_p1":"Le Guide des visages d'animaux est un programme de navigateur qui compare les rapports de longueur d'une photo de visage aux profils du chat, du chiot, du renard, du lapin, du hibou, de l'ours, du lion, du cerf et du loup. Il promet une chose : mesurer les rapports de la zone choisie et montrer lequel des neuf profils est le plus proche.","about_p2":"Le fichier photo est lu seulement dans ce navigateur et n'est pas envoyé à un serveur d'analyse. Quand vous fermez la page, la photo part avec elle. Sur cet appareil restent seulement la langue choisie et le thème clair ou sombre.","about_p3":"Le résultat est une comparaison ludique. L'outil n'a pas été fait pour décrire la personnalité, ni pour la médecine, la génétique ou les contrôles d'identité. Les questions sur le site, les erreurs ou la confidentialité vont à la page de contact.","privacy_title":"Confidentialité — Guide des visages d'animaux","privacy_meta":"Comment les photos de visage, la langue, les publicités, les commentaires et le formulaire de contact traitent les informations.","privacy_h1":"Confidentialité","privacy_photo_heading":"Photos de visage","privacy_photo":"Une photo de visage prise avec la caméra ou importée pour l'analyse est traitée seulement dans la mémoire de ce navigateur. Elle n'est pas envoyée à un serveur du Guide des visages d'animaux et n'est pas enregistrée dans un compte. Quand vous fermez la page ou choisissez une autre photo, la précédente n'est pas conservée.","privacy_store_heading":"Réglages gardés sur cet appareil","privacy_store":"La langue choisie est stockée dans ce navigateur sous le nom language_code, et le thème clair ou sombre sous theme_mode. Ces valeurs ne font que retrouver la même vue à la prochaine visite. Elles ne sont pas envoyées avec la photo de visage.","privacy_ads_heading":"Publicité","privacy_ads":"Ce site utilise les annonces automatiques Google AdSense. Quand une annonce s'affiche, Google peut utiliser des cookies ou des identifiants semblables pour choisir et mesurer les annonces. La description de Google sur les informations utilisées pour les annonces est sur https://policies.google.com/technologies/ads . Pour la propriété du site, l'identifiant d'éditeur ca-pub-8803401825336300 est dans une balise meta en tête de page et dans ads.txt à la racine du site.","privacy_disqus_heading":"Commentaires","privacy_disqus":"Les commentaires n'apparaissent qu'en bas de la page de mesure et sont gérés par Disqus. Écrire un commentaire demande une connexion ou une inscription Disqus, et Disqus peut utiliser ses propres cookies. Le texte du commentaire est stocké à part des photos de visage. Disqus décrit ses pratiques de confidentialité sur https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Formulaire de contact","privacy_form":"Seulement quand vous appuyez sur envoyer sur la page de contact, votre nom, société ou marque, e-mail de réponse et message sont remis à Formspree (https://formspree.io). La photo de visage ne fait pas partie de ces champs. Si vous n'envoyez pas le formulaire, le texte que vous tapiez n'est pas stocké.","privacy_font_heading":"Polices","privacy_font":"Les polices sont chargées depuis Google Fonts. À l'ouverture de la page, le navigateur demande des fichiers de police à fonts.googleapis.com et fonts.gstatic.com. Cette demande peut inclure l'adresse de la page et les informations habituelles du navigateur.","privacy_ask_heading":"Questions","privacy_ask":"S'il manque quelque chose ici ou si c'est inexact, dites-le sur la page de contact. Les photos de visage ne sont pas sur un serveur, donc il n'y a pas de fichier à rendre. La suppression des commentaires se fait dans Disqus. Une demande de suppression d'une question déjà envoyée peut passer par la page de contact et la boîte qui l'a reçue.","contact_title":"Contact — Guide des visages d'animaux","contact_meta":"Page de contact pour les questions de partenariat, d'erreur et de confidentialité sur le Guide des visages d'animaux.","contact_h1":"Contact","contact_help":"Laissez une question de partenariat, d'erreur ou de confidentialité. La photo de visage n'est pas jointe à ce formulaire. La réponse va à l'adresse que vous indiquez.","contact_name":"Nom","contact_company":"Société ou marque","contact_email":"E-mail pour la réponse","contact_message":"Message","contact_send":"Envoyer le message","contact_subject":"Question au Guide des visages d'animaux","contact_invalid":"Indiquez votre nom, l'e-mail de réponse et le message, puis envoyez de nouveau.","contact_sending":"Envoi de votre message.","contact_sent":"Votre message a été envoyé. Nous répondrons à l'adresse indiquée.","contact_fail":"Le message n'a pas pu être envoyé. Réessayez dans un instant.","contact_network":"Le message n'a pas pu être envoyé. Vérifiez la connexion et réessayez.","contact_teaser_title":"Contact","contact_teaser":"Les questions de partenariat, d'erreur ou de confidentialité vont sur la page de contact. La réponse est envoyée à l'adresse que vous indiquez. Les photos de visage ne sont pas dans le message.","atlas_help":"Choisissez le nom d'un animal pour lire son profil. Vous pouvez parcourir le guide sans photo de visage.","lead":"La comparaison utilise les rapports de longueur du visage, des yeux, du nez, de la bouche et de la mâchoire, pas les cheveux ni les oreilles. Le score est la distance par rapport à neuf profils d'animaux. Ce n'est ni un test de personnalité ni une classification scientifique.","cat_title":"Visage de chat — Guide des visages d'animaux","cat_meta":"Un profil d'yeux grands avec un petit nez et une petite bouche, de sorte que les traits semblent se rassembler vers le centre.","cat_h1":"Visage de chat","cat_p1":"Un visage de chat est l'impression que les yeux, le nez et la bouche se placent vers le milieu du visage. Le profil chat de ce guide se rapproche quand le visage est un peu rond, les yeux sont grands et le nez et la bouche sont plus petits que la moyenne.","cat_p2":"La largeur du visage est généreuse par rapport à la hauteur, et les yeux occupent davantage de la largeur du visage. Un nez plus étroit et plus court, et une bouche plus petite, penchent vers le chat. Le milieu du visage, des yeux à la pointe du nez, est plutôt court.","cat_p3":"Un score élevé signifie que, pris ensemble, les dix rapports sont les plus proches du profil chat. De grands yeux seuls ne font pas un visage de chat. Un nez et une bouche larges peuvent être plus proches de l'ours ou du lion.","cat_p4":"Un sourire élargit la bouche et peut faire pencher le résultat vers le chiot ou le lion. Tourner la tête rend les yeux plus petits qu'ils ne le sont. Une photo de face, bouche fermée, est la comparaison la plus simple pour ce profil.","dog_title":"Visage de chiot — Guide des visages d'animaux","dog_meta":"Un profil d'yeux ronds et de bouche large, l'allure que ce guide traite comme douce et amicale.","dog_h1":"Visage de chiot","dog_p1":"Un visage de chiot est l'impression d'yeux ronds et d'une bouche large, donc l'expression paraît douce. Le nez reste près de la moyenne, et un visage un peu rond se rapproche du profil chiot.","dog_p2":"Le profil chiot se rapproche quand la forme de l'œil, hauteur de l'œil divisée par sa largeur, est ronde et que la bouche est large sur le visage. Un écart un peu plus grand entre les yeux fait partie de la même lecture.","dog_p3":"Une bouche large à elle seule n'est pas un visage de chiot. Si le nez et la mâchoire sont larges aussi, le lion ou l'ours peuvent être plus proches. Des yeux étroits déplacent le résultat vers le renard ou le loup.","dog_p4":"Un grand sourire augmente le rapport de la bouche. Si vous voulez l'impression de tous les jours, mesurez aussi une photo bouche fermée.","fox_title":"Visage de renard — Guide des visages d'animaux","fox_meta":"Un profil de visage long, de menton étroit et d'yeux vifs.","fox_h1":"Visage de renard","fox_p1":"Un visage de renard est un contour long, un menton étroit et des yeux vifs. Il se sépare d'un visage long aux grands yeux, comme le cerf, par la forme des yeux.","fox_p2":"Le profil renard se rapproche quand la hauteur du visage dépasse la largeur, les yeux sont étroits et la pointe du menton est fine. Le nez est étroit mais long, et les yeux sont un peu plus rapprochés.","fox_p3":"Le profil cerf est aussi un visage long à mâchoire étroite, mais le cerf cherche de plus grands yeux et le renard cherche des yeux étroits et vifs. Si les deux scores sont proches, lisez la forme des yeux avec eux.","fox_p4":"Une vue de côté rend le menton encore plus étroit. Des cheveux qui couvrent le menton cachent son rapport. Utilisez une photo de face où la ligne de la mâchoire est visible.","rabbit_title":"Visage de lapin — Guide des visages d'animaux","rabbit_meta":"Un profil de grands yeux et d'un petit nez et d'une petite bouche, lu ici comme une impression ronde et douce.","rabbit_h1":"Visage de lapin","rabbit_p1":"Un visage de lapin a de grands yeux et un petit nez et une petite bouche, donc l'impression est ronde et douce. C'est l'un des profils de ce guide qui regarde le plus la taille des yeux.","rabbit_p2":"Le visage est rond, les yeux sont larges, la forme de l'œil est ronde et l'écart entre les yeux est un peu grand. La largeur et la longueur du nez, ainsi que la largeur de la bouche, sont petites, et le milieu du visage est court.","rabbit_p3":"Le profil hibou a aussi de grands yeux et un visage rond. Le hibou penche davantage vers un grand écart des yeux et un contour plus circulaire. Le lapin penche vers de grands yeux avec un petit nez et une petite bouche.","rabbit_p4":"Ouvrir très grand les yeux augmente la hauteur de l'œil et peut déplacer le résultat vers le lapin ou le hibou. Pour une taille de tous les jours, une photo avec les yeux ouverts naturellement convient mieux.","owl_title":"Visage de hibou — Guide des visages d'animaux","owl_meta":"Un profil de visage très rond, de grands yeux et d'un large écart entre les yeux.","owl_h1":"Visage de hibou","owl_p1":"Un visage de hibou est un visage très rond avec de grands yeux, donc les traits se lisent comme circulaires. Parmi les neuf profils, celui-ci tire le plus fort la rondeur du visage.","owl_p2":"La rondeur du visage, la taille des yeux, la forme ronde de l'œil et l'écart entre les yeux sont tous lus du côté grand. Le nez et la bouche sont petits et courts, la pointe du menton est doucement large et le milieu du visage est court.","owl_p3":"Le score se place souvent près du lapin. Un grand écart des yeux et un contour proche d'un cercle penchent vers le hibou. Si seuls le nez et la bouche sont petits et qu'il reste un peu de longueur de visage, lisez le lapin et le chat à côté.","owl_p4":"Un très gros plan au grand-angle déforme le milieu du visage vers une forme plus ronde. Au moins à une longueur de bras, le contour gonfle moins.","bear_title":"Visage d'ours — Guide des visages d'animaux","bear_meta":"Un profil de visage, de nez et de mâchoire larges, avec des yeux plus petits.","bear_h1":"Visage d'ours","bear_p1":"Un visage d'ours est un visage, un nez et une mâchoire larges, avec des yeux plus petits : l'impression que ce guide lit comme solide et paisible. Il regarde davantage la largeur du visage que la taille des yeux.","bear_p2":"La largeur du nez, celle de la mâchoire et le menton sont plus larges que la moyenne, et la taille des yeux est petite. La bouche est un peu large. Le milieu du visage reste près de la moyenne.","bear_p3":"Le profil lion a aussi un nez et une mâchoire larges. Le lion met plus de poids sur la bouche et la mâchoire, et les yeux n'ont pas besoin d'être très petits. De petits yeux avec de la largeur sur tout le visage sont plus proches de l'ours.","bear_p4":"Une barbe, un masque ou une main cache le bord du nez et de la mâchoire. Prenez la photo pour que la pointe du nez et la ligne de la mâchoire soient visibles.","lion_title":"Visage de lion — Guide des visages d'animaux","lion_meta":"Un profil de nez, de bouche et de mâchoire larges, de sorte que les traits se lisent comme amples.","lion_h1":"Visage de lion","lion_p1":"Un visage de lion a un nez, une bouche et une mâchoire larges, donc les traits paraissent forts. Ce profil regarde la largeur du bas du visage plus que la taille des yeux ou la longueur du visage.","lion_p2":"La largeur du nez, de la bouche et de la mâchoire est lue du côté large. La taille des yeux est un peu plus petite que la moyenne, et la rondeur de tout le visage ne s'éloigne pas beaucoup de la moyenne.","lion_p3":"Le profil chiot a aussi une bouche large, mais avec des yeux ronds et amicaux. Le score du lion est tiré par la largeur du nez, de la bouche et de la mâchoire plus que par les yeux.","lion_p4":"Sourire ou parler rend la bouche plus large. Comparez avec une photo bouche fermée pour voir si l'expression a créé la différence.","deer_title":"Visage de cerf — Guide des visages d'animaux","deer_meta":"Un profil de visage long, de grands yeux et d'une mâchoire et d'un menton étroits.","deer_h1":"Visage de cerf","deer_p1":"Un visage de cerf est un visage long avec de grands yeux et une mâchoire étroite, une ligne fine et douce dans ce guide. Parmi les visages longs, celui aux yeux plus grands est lu comme le cerf.","deer_p2":"La hauteur du visage est longue, les yeux sont grands, le nez est étroit, la mâchoire et la pointe du menton sont fines et le milieu du visage est long. La forme de l'œil n'a pas besoin d'être aussi étroite que celle du renard.","deer_p3":"Le renard et le loup sont aussi des visages longs. Le cerf est la combinaison de grands yeux et d'une mâchoire fine. Le loup est la combinaison d'yeux étroits et d'un milieu du visage long.","deer_p4":"Une caméra qui regarde d'en haut raccourcit la mâchoire. Quand la caméra est à hauteur des yeux, la hauteur du visage est moins déformée.","wolf_title":"Visage de loup — Guide des visages d'animaux","wolf_meta":"Un profil d'yeux étroits et d'un milieu du visage et d'un nez longs.","wolf_h1":"Visage de loup","wolf_p1":"Un visage de loup a des yeux étroits et un milieu du visage long, donc le contour paraît vif. La bouche reste près de la moyenne, et le visage long se lit par la distance entre les yeux et le nez.","wolf_p2":"La hauteur de l'œil est courte, les yeux sont plus rapprochés, et le nez comme la distance des yeux à la pointe du nez sont longs. Le visage est plutôt long, et la pointe du menton est lue comme étroite.","wolf_p3":"Le profil renard est souvent le voisin. Le renard met plus de poids sur une pointe de menton plus fine et un nez plus étroit. Le loup met plus de poids sur les yeux étroits et la longueur du milieu du visage.","wolf_p4":"Plisser les yeux peut faire monter le côté loup par le seul rapport de forme de l'œil. Prenez la photo avec les yeux ouverts comme d'habitude."},"id":{"nav_label":"Menu panduan","nav_tool":"Ukur wajah","nav_method":"Cara mengukur","nav_about":"Tentang","nav_privacy":"Privasi","nav_contact":"Kontak","theme_group":"Tampilan","theme_light":"Terang","theme_dark":"Gelap","language_group":"Bahasa","footer":"Foto diproses hanya di browser ini dan tidak diunggah. Hasilnya adalah perbandingan proporsi wajah yang bersifat main-main, bukan tes ilmiah atau kepribadian. Ekspresi, sudut, kacamata, dan cahaya bisa mengubah peringkat.","try_tool":"Ukur wajah dengan panduan ini","read_method":"Baca cara sepuluh rasio diukur","other_animals":"Profil hewan lain","animal_ratio_heading":"Rasio yang condong ke sini","animal_score_heading":"Arti skor yang dekat","animal_photo_heading":"Saat foto menggeser peringkat","name_cat":"Wajah kucing","name_dog":"Wajah anak anjing","name_fox":"Wajah rubah","name_rabbit":"Wajah kelinci","name_owl":"Wajah burung hantu","name_bear":"Wajah beruang","name_lion":"Wajah singa","name_deer":"Wajah rusa","name_wolf":"Wajah serigala","method_title":"Cara mengukur — Panduan Wajah Hewan","method_meta":"Menjelaskan cara rasio panjang wajah, mata, hidung, mulut, dan rahang diukur lalu dibandingkan dengan sembilan profil hewan.","method_h1":"Cara mengukur","method_lead":"Panduan ini tidak melihat rambut, telinga, atau pakaian. Ia membaca panjang pada wajah di foto dan hanya membandingkan panjang itu dibagi ukuran wajah. Jumlah piksel berubah menurut jarak, jadi jumlah piksel mentah bukan skor.","method_measure":"Analisis berjalan di browser ini. Foto tidak dikirim ke server. Jika ada beberapa wajah di area yang dipilih, yang terbesar yang dipakai. Rata-rata di bawah adalah titik awal panduan ini untuk foto dari depan. Itu bukan rentang normal medis.","method_ratios_heading":"Sepuluh rasio","method_r1":"Bentuk wajah. Lebar wajah dibagi tinggi wajah. Angka lebih besar berarti wajah lebih lebar, angka lebih kecil berarti wajah lebih panjang. Rata-rata panduan ini adalah 0.82.","method_r2":"Ukuran mata. Lebar mata dibagi lebar wajah. 0.20 berarti lebar mata adalah 20% dari lebar wajah.","method_r3":"Bentuk mata. Tinggi mata dibagi lebar mata. Lebih besar lebih bulat, lebih kecil lebih sempit dan tajam. Rata-rata di sini 0.33.","method_r4":"Jarak mata. Jarak antar mata dibagi lebar wajah. Rata-rata dekat 0.25.","method_r5":"Lebar hidung. Lebar hidung dibagi lebar wajah. Rata-rata dekat 0.28.","method_r6":"Panjang hidung. Panjang hidung dibagi tinggi wajah. Rata-rata 0.30.","method_r7":"Lebar mulut. Lebar mulut dibagi lebar wajah. Rata-rata dekat 0.40.","method_r8":"Lebar rahang. Bagian rahang yang lebih lebar dibagi lebar wajah. Rata-rata 0.80.","method_r9":"Dagu. Lebar dagu dibagi lebar wajah. Rata-rata 0.32.","method_r10":"Bagian tengah wajah. Panjang dari mata ke ujung hidung dibagi tinggi wajah. Rata-rata 0.25.","method_score_heading":"Cara skor dibuat","method_score":"Setiap rasio diubah menjadi jarak dari rata-rata, lalu dibandingkan dengan profil tiap hewan. Ciri yang membentuk kesan, seperti ukuran mata, dihitung sedikit lebih berat. Ciri yang mudah berubah antar foto, seperti ujung dagu, dihitung lebih ringan. Hewan terdekat mendapat skor lebih tinggi. Skor berhenti di 94. Skor tidak pernah 100, agar kesalahan satu foto tidak tampil seperti kecocokan sempurna.","method_photo_heading":"Saat orang yang sama mendapat peringkat lain","method_photo":"Menoleh, menyipitkan mata, senyum lebar, cahaya sangat redup, atau wajah yang sangat kecil dalam bingkai bisa mengubah peringkat. Foto dari depan, mata sejajar kamera dan mulut tertutup, lebih mudah dibandingkan. Bingkai kacamata yang menutupi sudut luar mata bisa membuat panjang mata salah. Foto sudut lebar yang sangat dekat membuat bagian tengah wajah tampak lebih bulat.","method_animals_heading":"Sembilan profil hewan","method_animals":"Setiap hewan mencari campuran rasio besar dan kecil yang berbeda. Pilih nama untuk membaca profil itu sendiri. Halaman-halaman ini tidak mengulang satu paragraf dengan hanya mengganti nama hewan.","about_title":"Tentang — Panduan Wajah Hewan","about_meta":"Apa yang dibandingkan Panduan Wajah Hewan, di mana foto berada, dan cara membaca hasilnya.","about_h1":"Tentang panduan ini","about_p1":"Panduan Wajah Hewan adalah program browser yang membandingkan rasio panjang foto wajah dengan profil kucing, anak anjing, rubah, kelinci, burung hantu, beruang, singa, rusa, dan serigala. Ia menjanjikan satu hal: mengukur rasio di area yang Anda pilih, lalu menunjukkan profil mana dari sembilan itu yang paling dekat.","about_p2":"Berkas foto hanya dibaca di browser ini dan tidak diunggah ke server analisis. Saat halaman ditutup, foto ikut hilang. Yang tersimpan di perangkat ini hanya bahasa yang dipilih dan tampilan terang atau gelap.","about_p3":"Hasilnya adalah perbandingan yang bersifat main-main. Alat ini tidak dibuat untuk menggambarkan kepribadian, atau untuk kedokteran, genetika, atau pemeriksaan identitas. Pertanyaan tentang situs, kesalahan, atau privasi masuk ke halaman kontak.","privacy_title":"Privasi — Panduan Wajah Hewan","privacy_meta":"Bagaimana foto wajah, pengaturan bahasa, iklan, komentar, dan formulir kontak masing-masing menangani informasi.","privacy_h1":"Privasi","privacy_photo_heading":"Foto wajah","privacy_photo":"Foto wajah yang diambil kamera atau diunggah untuk analisis hanya ditangani di memori browser ini. Foto tidak dikirim ke server Panduan Wajah Hewan dan tidak disimpan ke akun. Saat halaman ditutup atau foto lain dipilih, foto sebelumnya tidak disimpan.","privacy_store_heading":"Pengaturan yang tersimpan di perangkat ini","privacy_store":"Bahasa yang dipilih disimpan di browser ini dengan nama language_code, dan tampilan terang atau gelap dengan theme_mode. Nilai itu hanya mengembalikan tampilan yang sama pada kunjungan berikutnya. Nilai itu tidak dikirim bersama foto wajah.","privacy_ads_heading":"Iklan","privacy_ads":"Situs ini memakai iklan otomatis Google AdSense. Saat iklan tampil, Google dapat memakai cookie atau pengenal serupa untuk memilih dan mengukur iklan. Penjelasan Google tentang informasi yang dipakai iklan ada di https://policies.google.com/technologies/ads . Untuk kepemilikan situs, id penerbit ca-pub-8803401825336300 ada di tag meta pada kepala halaman dan di ads.txt pada akar situs.","privacy_disqus_heading":"Komentar","privacy_disqus":"Komentar hanya muncul di bawah halaman ukur dan ditangani Disqus. Menulis komentar perlu masuk atau daftar di Disqus, dan Disqus dapat memakai cookienya sendiri. Teks komentar disimpan terpisah dari foto wajah. Disqus menjelaskan praktik privasinya di https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Formulir kontak","privacy_form":"Hanya saat Anda menekan kirim di halaman kontak, nama, perusahaan atau merek, email balasan, dan pesan sampai ke Formspree (https://formspree.io). Foto wajah bukan bagian dari bidang itu. Jika formulir tidak dikirim, teks yang sedang diketik tidak disimpan.","privacy_font_heading":"Huruf","privacy_font":"Jenis huruf dimuat dari Google Fonts. Saat halaman dibuka, browser meminta berkas huruf dari fonts.googleapis.com dan fonts.gstatic.com. Permintaan itu dapat berisi alamat halaman dan informasi browser yang biasa.","privacy_ask_heading":"Pertanyaan","privacy_ask":"Jika ada yang kurang atau salah di sini, beri tahu lewat halaman kontak. Foto wajah tidak ada di server, jadi tidak ada berkas untuk dikembalikan. Penghapusan komentar ditangani di Disqus. Permintaan menghapus pertanyaan yang sudah terkirim dapat dilakukan lewat halaman kontak dan kotak masuk yang menerimanya.","contact_title":"Kontak — Panduan Wajah Hewan","contact_meta":"Halaman kontak untuk pertanyaan kerja sama, kesalahan, dan privasi tentang Panduan Wajah Hewan.","contact_h1":"Kontak","contact_help":"Tinggalkan pertanyaan kerja sama, kesalahan, atau privasi. Foto wajah tidak dilampirkan pada formulir ini. Balasan masuk ke email yang Anda isi.","contact_name":"Nama","contact_company":"Perusahaan atau merek","contact_email":"Email untuk balasan","contact_message":"Pesan","contact_send":"Kirim pesan","contact_subject":"Pertanyaan Panduan Wajah Hewan","contact_invalid":"Isi nama, email balasan, dan pesan, lalu kirim lagi.","contact_sending":"Pesan Anda sedang dikirim.","contact_sent":"Pesan terkirim. Kami akan membalas ke email yang Anda isi.","contact_fail":"Pesan tidak terkirim. Coba lagi sebentar lagi.","contact_network":"Pesan tidak terkirim. Periksa koneksi lalu coba lagi.","contact_teaser_title":"Kontak","contact_teaser":"Pertanyaan tentang kerja sama, kesalahan, atau privasi ada di halaman kontak. Balasan dikirim ke email yang Anda isi. Foto wajah tidak ikut dalam pesan.","atlas_help":"Pilih nama hewan untuk membaca profilnya. Anda bisa menelusuri panduan tanpa foto wajah.","lead":"Perbandingan memakai rasio panjang wajah, mata, hidung, mulut, dan rahang, bukan rambut atau telinga. Skor adalah jarak ke sembilan profil hewan. Ini bukan tes kepribadian atau klasifikasi ilmiah.","cat_title":"Wajah kucing — Panduan Wajah Hewan","cat_meta":"Profil mata besar dengan hidung dan mulut kecil, sehingga bagian wajah tampak berkumpul ke tengah.","cat_h1":"Wajah kucing","cat_p1":"Wajah kucing adalah kesan bahwa mata, hidung, dan mulut duduk ke arah tengah wajah. Profil kucing panduan ini mendekat saat wajah agak bulat, mata besar, serta hidung dan mulut lebih kecil dari rata-rata.","cat_p2":"Lebar wajah longgar dibanding tingginya, dan mata mengambil lebih banyak lebar wajah. Hidung yang lebih sempit dan pendek, serta mulut yang lebih kecil, condong ke kucing. Bagian tengah, dari mata ke ujung hidung, ada di sisi pendek.","cat_p3":"Skor tinggi berarti sepuluh rasio bersama-sama paling dekat dengan profil kucing. Mata besar saja tidak membuat wajah kucing. Hidung dan mulut yang lebar bisa lebih dekat ke beruang atau singa.","cat_p4":"Senyum melebarkan mulut dan bisa menggeser hasil ke anak anjing atau singa. Menoleh membuat mata tampak lebih kecil dari yang sebenarnya. Foto dari depan dengan mulut tertutup lebih mudah dibandingkan untuk profil ini.","dog_title":"Wajah anak anjing — Panduan Wajah Hewan","dog_meta":"Profil mata bulat dan mulut lebar, tampilan yang panduan ini baca sebagai lembut dan ramah.","dog_h1":"Wajah anak anjing","dog_p1":"Wajah anak anjing adalah kesan mata bulat dan mulut lebar, sehingga ekspresi tampak lembut. Hidung tetap dekat rata-rata, dan wajah yang sedikit bulat lebih dekat ke profil anak anjing.","dog_p2":"Profil anak anjing lebih dekat saat bentuk mata, tinggi mata dibagi lebar mata, bulat dan mulut lebar pada wajah. Jarak mata yang sedikit lebih lebar adalah bagian dari pembacaan yang sama.","dog_p3":"Mulut lebar saja bukan wajah anak anjing. Jika hidung dan rahang juga lebar, singa atau beruang bisa lebih dekat. Mata sempit menggeser hasil ke rubah atau serigala.","dog_p4":"Senyum besar menaikkan rasio mulut. Jika ingin kesan sehari-hari, ukur juga foto dengan mulut tertutup.","fox_title":"Wajah rubah — Panduan Wajah Hewan","fox_meta":"Profil wajah panjang, dagu sempit, dan mata tajam.","fox_h1":"Wajah rubah","fox_p1":"Wajah rubah adalah garis luar yang panjang, dagu sempit, dan mata tajam. Ia terpisah dari wajah panjang bermata besar, seperti rusa, lewat bentuk matanya.","fox_p2":"Profil rubah lebih dekat saat tinggi wajah melebihi lebar, mata sempit, dan ujung dagu ramping. Hidung sempit tetapi panjang, dan mata duduk sedikit lebih dekat.","fox_p3":"Profil rusa juga wajah panjang dengan rahang sempit, tetapi rusa mencari mata yang lebih besar dan rubah mencari mata yang sempit dan tajam. Jika kedua skor dekat, baca bentuk mata bersamanya.","fox_p4":"Tampak samping membuat dagu terlihat lebih sempit. Rambut yang menutup dagu menyembunyikan rasio dagu. Pakai foto dari depan yang garis rahangnya terlihat.","rabbit_title":"Wajah kelinci — Panduan Wajah Hewan","rabbit_meta":"Profil mata besar serta hidung dan mulut kecil, dibaca di sini sebagai kesan bulat dan lembut.","rabbit_h1":"Wajah kelinci","rabbit_p1":"Wajah kelinci punya mata besar serta hidung dan mulut kecil, sehingga kesannya bulat dan lembut. Ini salah satu profil dalam panduan yang paling memperhatikan ukuran mata.","rabbit_p2":"Wajah bulat, mata lebar, bentuk mata bulat, dan jarak antar mata agak lebar. Lebar hidung, panjang hidung, dan lebar mulut kecil, dan bagian tengah wajah pendek.","rabbit_p3":"Profil burung hantu juga punya mata besar dan wajah bulat. Burung hantu lebih condong ke jarak mata yang lebar dan garis luar yang lebih melingkar. Kelinci condong ke mata besar dengan hidung dan mulut kecil.","rabbit_p4":"Membuka mata sangat lebar menaikkan tinggi mata dan bisa menggeser hasil ke kelinci atau burung hantu. Untuk ukuran sehari-hari, foto dengan mata terbuka secara alami lebih baik.","owl_title":"Wajah burung hantu — Panduan Wajah Hewan","owl_meta":"Profil wajah sangat bulat, mata besar, dan jarak mata yang lebar.","owl_h1":"Wajah burung hantu","owl_p1":"Wajah burung hantu adalah wajah yang sangat bulat dengan mata besar, sehingga bagian wajah terbaca melingkar. Di antara sembilan profil, yang ini paling kuat menarik kebulatan wajah.","owl_p2":"Kebulatan wajah, ukuran mata, bentuk mata yang bulat, dan jarak mata semuanya dibaca di sisi besar. Hidung dan mulut kecil dan pendek, ujung dagu lembut lebar, dan bagian tengah wajah pendek.","owl_p3":"Skor sering dekat dengan kelinci. Jarak mata yang lebar dan garis luar yang dekat lingkaran condong ke burung hantu. Jika hanya hidung dan mulut yang kecil dan masih ada panjang wajah, baca kelinci dan kucing bersamanya.","owl_p4":"Sudut lebar yang sangat dekat mengubah bagian tengah wajah menjadi lebih bulat. Dari jarak setidaknya sepanjang lengan, garis luar kurang menggembung.","bear_title":"Wajah beruang — Panduan Wajah Hewan","bear_meta":"Profil wajah, hidung, dan rahang yang lebar dengan mata yang lebih kecil.","bear_h1":"Wajah beruang","bear_p1":"Wajah beruang adalah wajah, hidung, dan rahang yang lebar dengan mata lebih kecil, kesan yang panduan ini baca sebagai kokoh dan tenang. Ia lebih melihat lebar wajah daripada ukuran mata.","bear_p2":"Lebar hidung, lebar rahang, dan dagu lebih lebar dari rata-rata, dan ukuran mata di sisi kecil. Mulut agak lebar. Bagian tengah wajah tetap dekat rata-rata.","bear_p3":"Profil singa juga punya hidung dan rahang lebar. Singa lebih menitikberatkan mulut dan rahang, dan mata tidak harus sangat kecil. Mata kecil dengan lebar di seluruh wajah lebih dekat ke beruang.","bear_p4":"Janggut, masker, atau tangan menyembunyikan tepi hidung dan rahang. Ambil foto sehingga ujung hidung dan garis rahang terlihat.","lion_title":"Wajah singa — Panduan Wajah Hewan","lion_meta":"Profil hidung, mulut, dan rahang yang lebar, sehingga bagian wajah terbaca lebar.","lion_h1":"Wajah singa","lion_p1":"Wajah singa punya hidung, mulut, dan rahang yang lebar, sehingga bagian wajah tampak kuat. Profil ini lebih melihat lebar bagian bawah wajah daripada ukuran mata atau panjang wajah.","lion_p2":"Lebar hidung, lebar mulut, dan lebar rahang dibaca di sisi lebar. Ukuran mata sedikit lebih kecil dari rata-rata, dan kebulatan seluruh wajah tidak jauh dari rata-rata.","lion_p3":"Profil anak anjing juga punya mulut lebar, tetapi dengan mata bulat dan ramah. Skor singa lebih ditarik oleh lebar hidung, mulut, dan rahang daripada oleh mata.","lion_p4":"Tersenyum atau berbicara membuat mulut lebih lebar. Bandingkan dengan foto mulut tertutup untuk melihat apakah ekspresi yang membuat perbedaannya.","deer_title":"Wajah rusa — Panduan Wajah Hewan","deer_meta":"Profil wajah panjang, mata besar, serta rahang dan dagu yang sempit.","deer_h1":"Wajah rusa","deer_p1":"Wajah rusa adalah wajah panjang dengan mata besar dan rahang sempit, garis yang halus dan lembut dalam panduan ini. Di antara wajah panjang, yang matanya lebih besar dibaca sebagai rusa.","deer_p2":"Tinggi wajah panjang, mata besar, hidung sempit, rahang dan ujung dagu ramping, dan bagian tengah wajah panjang. Bentuk mata tidak harus sesempit rubah.","deer_p3":"Rubah dan serigala juga wajah panjang. Rusa adalah paduan mata besar dan rahang ramping. Serigala adalah paduan mata sempit dan bagian tengah wajah yang panjang.","deer_p4":"Kamera yang melihat dari atas memperpendek rahang. Saat kamera sejajar mata, tinggi wajah kurang terdistorsi.","wolf_title":"Wajah serigala — Panduan Wajah Hewan","wolf_meta":"Profil mata sempit serta bagian tengah wajah dan hidung yang panjang.","wolf_h1":"Wajah serigala","wolf_p1":"Wajah serigala punya mata sempit dan bagian tengah wajah yang panjang, sehingga garis luar tampak tajam. Mulut tetap dekat rata-rata, dan wajah panjang dibaca dari jarak antara mata dan hidung.","wolf_p2":"Tinggi mata pendek, mata duduk lebih dekat, dan hidung serta rentang dari mata ke ujung hidung sama-sama panjang. Wajah ada di sisi panjang, dan ujung dagu dibaca sempit.","wolf_p3":"Profil rubah sering menjadi tetangga. Rubah lebih menitikberatkan ujung dagu yang lebih ramping dan hidung yang lebih sempit. Serigala lebih menitikberatkan mata sempit dan panjang bagian tengah wajah.","wolf_p4":"Menyipitkan mata bisa menaikkan sisi serigala hanya dari rasio bentuk mata. Ambil foto dengan mata terbuka seperti biasa."},"de":{"nav_label":"Atlas-Menü","nav_tool":"Gesicht messen","nav_method":"So wird gemessen","nav_about":"Über uns","nav_privacy":"Datenschutz","nav_contact":"Kontakt","theme_group":"Darstellung","theme_light":"Hell","theme_dark":"Dunkel","language_group":"Sprache","footer":"Fotos werden nur in diesem Browser verarbeitet und nicht hochgeladen. Das Ergebnis ist ein spielerischer Vergleich der Gesichtsproportionen, kein wissenschaftlicher oder Persönlichkeitstest. Ausdruck, Winkel, Brille und Licht können die Reihenfolge ändern.","try_tool":"Ein Gesicht mit diesem Atlas messen","read_method":"Lesen, wie die zehn Verhältnisse gemessen werden","other_animals":"Andere Tierprofile","animal_ratio_heading":"Verhältnisse, die hierhin neigen","animal_score_heading":"Was eine nahe Punktzahl bedeutet","animal_photo_heading":"Wenn das Foto den Rang verschiebt","name_cat":"Katzengesicht","name_dog":"Welpengesicht","name_fox":"Fuchsgesicht","name_rabbit":"Hasengesicht","name_owl":"Eulengesicht","name_bear":"Bärengesicht","name_lion":"Löwengesicht","name_deer":"Hirschgesicht","name_wolf":"Wolfsgesicht","method_title":"So wird gemessen — Tiergesichter-Atlas","method_meta":"Erklärt, wie Längenverhältnisse von Gesicht, Augen, Nase, Mund und Kiefer gemessen und mit neun Tierprofilen verglichen werden.","method_h1":"So wird gemessen","method_lead":"Dieser Atlas sieht nicht auf Haare, Ohren oder Kleidung. Er liest Längen im Gesicht auf dem Foto und vergleicht nur diese Längen geteilt durch die Gesichtsgröße. Die Pixelzahl ändert sich mit dem Abstand, deshalb ist die rohe Pixelzahl nicht die Punktzahl.","method_measure":"Die Analyse läuft in diesem Browser. Das Foto wird nicht an einen Server gesendet. Liegen mehrere Gesichter im gewählten Bereich, wird das größte verwendet. Die Durchschnitte unten sind der Startpunkt dieses Atlas für ein Foto von vorn. Sie sind kein medizinischer Normalbereich.","method_ratios_heading":"Die zehn Verhältnisse","method_r1":"Gesichtsform. Gesichtsbreite geteilt durch Gesichtshöhe. Eine größere Zahl ist ein breiteres Gesicht, eine kleinere ein längeres. Der Durchschnitt dieses Atlas ist 0.82.","method_r2":"Augengröße. Augenbreite geteilt durch Gesichtsbreite. 0.20 bedeutet, dass die Augenbreite 20% der Gesichtsbreite ist.","method_r3":"Augenform. Augenhöhe geteilt durch Augenbreite. Größer ist runder, kleiner ist schmaler und schärfer. Der Durchschnitt hier ist 0.33.","method_r4":"Augenabstand. Der Abstand zwischen den Augen geteilt durch die Gesichtsbreite. Der Durchschnitt liegt nahe 0.25.","method_r5":"Nasenbreite. Nasenbreite geteilt durch Gesichtsbreite. Der Durchschnitt liegt nahe 0.28.","method_r6":"Nasenlänge. Nasenlänge geteilt durch Gesichtshöhe. Der Durchschnitt ist 0.30.","method_r7":"Mundbreite. Mundbreite geteilt durch Gesichtsbreite. Der Durchschnitt liegt nahe 0.40.","method_r8":"Kieferbreite. Der breitere Teil des Kiefers geteilt durch die Gesichtsbreite. Der Durchschnitt ist 0.80.","method_r9":"Kinn. Kinnbreite geteilt durch Gesichtsbreite. Der Durchschnitt ist 0.32.","method_r10":"Mittelgesicht. Die Länge von den Augen zur Nasenspitze geteilt durch die Gesichtshöhe. Der Durchschnitt ist 0.25.","method_score_heading":"Wie die Punktzahl entsteht","method_score":"Jedes Verhältnis wird zu einem Abstand vom Durchschnitt und dann mit dem Profil jedes Tiers verglichen. Merkmale, die den Eindruck prägen, etwa die Augengröße, zählen etwas mehr. Merkmale, die von Foto zu Foto leicht schwanken, etwa die Kinnspitze, zählen weniger. Das nächste Tier erhält die höhere Punktzahl. Die Punktzahl endet bei 94. Sie zeigt nie 100, damit der Fehler eines Fotos nicht wie eine perfekte Übereinstimmung wirkt.","method_photo_heading":"Wenn dieselbe Person einen anderen Rang bekommt","method_photo":"Den Kopf drehen, die Augen zusammenkneifen, ein breites Lächeln, sehr schwaches Licht oder ein winziges Gesicht im Bild können den Rang ändern. Ein Foto von vorn, Augen auf Kamerahöhe und Mund geschlossen, lässt sich leichter vergleichen. Ein Brillengestell, das den äußeren Augenwinkel verdeckt, kann die Augenlänge verfälschen. Eine sehr nahe Weitwinkelaufnahme lässt die Gesichtsmitte runder wirken.","method_animals_heading":"Die neun Tierprofile","method_animals":"Jedes Tier sucht eine andere Mischung aus größeren und kleineren Verhältnissen. Wählen Sie einen Namen, um dieses Profil für sich zu lesen. Die Seiten wiederholen nicht einen Absatz und tauschen nur den Tiernamen aus.","about_title":"Über uns — Tiergesichter-Atlas","about_meta":"Was der Tiergesichter-Atlas vergleicht, wo das Foto bleibt und wie das Ergebnis zu lesen ist.","about_h1":"Über diesen Atlas","about_p1":"Der Tiergesichter-Atlas ist ein Browserprogramm, das Längenverhältnisse in einem Gesichtsfoto mit Profilen für Katze, Welpe, Fuchs, Hase, Eule, Bär, Löwe, Hirsch und Wolf vergleicht. Er verspricht eines: die Verhältnisse im gewählten Bereich messen und zeigen, welches der neun Profile am nächsten liegt.","about_p2":"Die Fotodatei wird nur in diesem Browser gelesen und nicht auf einen Analyseserver hochgeladen. Wenn Sie die Seite schließen, geht das Foto mit. Auf diesem Gerät bleiben nur die gewählte Sprache und das helle oder dunkle Thema.","about_p3":"Das Ergebnis ist ein spielerischer Vergleich. Das Werkzeug wurde nicht gebaut, um Persönlichkeit zu beschreiben, und nicht für Medizin, Genetik oder Identitätsprüfungen. Fragen zur Seite, zu Fehlern oder zum Datenschutz gehen an die Kontaktseite.","privacy_title":"Datenschutz — Tiergesichter-Atlas","privacy_meta":"Wie Gesichtsfotos, Spracheinstellung, Werbung, Kommentare und das Kontaktformular jeweils mit Informationen umgehen.","privacy_h1":"Datenschutz","privacy_photo_heading":"Gesichtsfotos","privacy_photo":"Ein mit der Kamera aufgenommenes oder zur Analyse hochgeladenes Gesichtsfoto wird nur im Speicher dieses Browsers verarbeitet. Es wird nicht an einen Server des Tiergesichter-Atlas gesendet und nicht in einem Konto gespeichert. Wenn Sie die Seite schließen oder ein anderes Foto wählen, bleibt das vorherige nicht erhalten.","privacy_store_heading":"Einstellungen auf diesem Gerät","privacy_store":"Die gewählte Sprache wird in diesem Browser unter dem Namen language_code gespeichert, das helle oder dunkle Thema unter theme_mode. Diese Werte stellen nur bei der nächsten Besuch dieselbe Ansicht wieder her. Sie werden nicht mit dem Gesichtsfoto gesendet.","privacy_ads_heading":"Werbung","privacy_ads":"Diese Website nutzt automatische Google-AdSense-Anzeigen. Wenn eine Anzeige erscheint, kann Google Cookies oder ähnliche Kennungen verwenden, um Anzeigen auszuwählen und zu messen. Googles Beschreibung der für Anzeigen genutzten Informationen steht unter https://policies.google.com/technologies/ads . Für den Nachweis der Website liegt die Publisher-ID ca-pub-8803401825336300 in einem Meta-Tag im Seitenkopf und in ads.txt im Stammverzeichnis.","privacy_disqus_heading":"Kommentare","privacy_disqus":"Kommentare erscheinen nur unten auf der Messseite und werden von Disqus verarbeitet. Einen Kommentar zu schreiben braucht eine Disqus-Anmeldung oder Registrierung, und Disqus kann eigene Cookies nutzen. Kommentartext wird getrennt von Gesichtsfotos gespeichert. Disqus beschreibt seine Datenschutzpraxis unter https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Kontaktformular","privacy_form":"Nur wenn Sie auf der Kontaktseite auf Senden drücken, werden Name, Firma oder Marke, Antwort-E-Mail und Nachricht an Formspree (https://formspree.io) übermittelt. Das Gesichtsfoto gehört nicht zu diesen Feldern. Wenn Sie das Formular nicht senden, wird der Text, den Sie gerade tippen, nicht gespeichert.","privacy_font_heading":"Schriften","privacy_font":"Die Schriftarten werden von Google Fonts geladen. Beim Öffnen der Seite fordert der Browser Schriftdateien von fonts.googleapis.com und fonts.gstatic.com an. Diese Anfrage kann die Seitenadresse und übliche Browserangaben enthalten.","privacy_ask_heading":"Fragen","privacy_ask":"Wenn hier etwas fehlt oder falsch ist, sagen Sie es uns auf der Kontaktseite. Gesichtsfotos liegen nicht auf einem Server, deshalb gibt es keine Datei zum Zurückgeben. Das Löschen von Kommentaren läuft über Disqus. Eine Bitte, eine bereits gesendete Anfrage zu löschen, kann über die Kontaktseite und das Postfach gehen, das sie erhalten hat.","contact_title":"Kontakt — Tiergesichter-Atlas","contact_meta":"Kontaktseite für Partnerschafts-, Fehler- und Datenschutzfragen zum Tiergesichter-Atlas.","contact_h1":"Kontakt","contact_help":"Hinterlassen Sie eine Frage zu Partnerschaft, Fehler oder Datenschutz. Das Gesichtsfoto hängt nicht an diesem Formular. Die Antwort geht an die E-Mail, die Sie angeben.","contact_name":"Name","contact_company":"Firma oder Marke","contact_email":"E-Mail für die Antwort","contact_message":"Nachricht","contact_send":"Nachricht senden","contact_subject":"Anfrage zum Tiergesichter-Atlas","contact_invalid":"Geben Sie Name, Antwort-E-Mail und Nachricht ein und senden Sie erneut.","contact_sending":"Ihre Nachricht wird gesendet.","contact_sent":"Ihre Nachricht wurde gesendet. Wir antworten an die angegebene E-Mail.","contact_fail":"Die Nachricht konnte nicht gesendet werden. Versuchen Sie es gleich noch einmal.","contact_network":"Die Nachricht konnte nicht gesendet werden. Prüfen Sie die Verbindung und versuchen Sie es erneut.","contact_teaser_title":"Kontakt","contact_teaser":"Fragen zu Partnerschaft, Fehlern oder Datenschutz gehören auf die Kontaktseite. Die Antwort geht an die E-Mail, die Sie angeben. Gesichtsfotos stehen nicht in der Nachricht.","atlas_help":"Wählen Sie einen Tiernamen, um das Profil zu lesen. Den Atlas können Sie ohne Gesichtsfoto durchsehen.","lead":"Der Vergleich nutzt Längenverhältnisse von Gesicht, Augen, Nase, Mund und Kiefer, nicht Haare oder Ohren. Die Punktzahl ist der Abstand zu neun Tierprofilen. Es ist kein Persönlichkeitstest und keine wissenschaftliche Einstufung.","cat_title":"Katzengesicht — Tiergesichter-Atlas","cat_meta":"Ein Profil für große Augen mit kleiner Nase und kleinem Mund, sodass die Züge zur Mitte hin zusammenrücken.","cat_h1":"Katzengesicht","cat_p1":"Ein Katzengesicht ist der Eindruck, dass Augen, Nase und Mund zur Mitte des Gesichts rücken. Das Katzenprofil dieses Atlas rückt näher, wenn das Gesicht etwas rund ist, die Augen groß sind und Nase und Mund kleiner als der Durchschnitt sind.","cat_p2":"Die Gesichtsbreite ist im Vergleich zur Höhe großzügig, und die Augen nehmen mehr von der Gesichtsbreite ein. Eine schmalere und kürzere Nase und ein kleinerer Mund neigen zur Katze. Das Mittelgesicht, von den Augen zur Nasenspitze, ist eher kurz.","cat_p3":"Eine hohe Punktzahl bedeutet, dass die zehn Verhältnisse zusammen dem Katzenprofil am nächsten sind. Große Augen allein machen kein Katzengesicht. Eine breite Nase und ein breiter Mund können näher am Bären oder Löwen liegen.","cat_p4":"Ein Lächeln macht den Mund breiter und kann das Ergebnis zum Welpen oder Löwen neigen. Dreht man den Kopf, wirken die Augen kleiner, als sie sind. Ein Foto von vorn mit geschlossenem Mund lässt sich mit diesem Profil leichter vergleichen.","dog_title":"Welpengesicht — Tiergesichter-Atlas","dog_meta":"Ein Profil für runde Augen und einen breiten Mund, der Blick, den dieser Atlas als sanft und freundlich liest.","dog_h1":"Welpengesicht","dog_p1":"Ein Welpengesicht ist der Eindruck runder Augen und eines breiten Mundes, sodass der Ausdruck sanft wirkt. Die Nase bleibt nahe am Durchschnitt, und ein etwas rundes Gesicht liegt näher am Welpenprofil.","dog_p2":"Das Welpenprofil rückt näher, wenn die Augenform, Augenhöhe geteilt durch Augenbreite, rund ist und der Mund im Gesicht breit ist. Ein etwas weiterer Augenabstand gehört zur selben Lesart.","dog_p3":"Ein breiter Mund allein ist kein Welpengesicht. Sind Nase und Kiefer ebenfalls breit, können Löwe oder Bär näher liegen. Schmale Augen verschieben das Ergebnis zum Fuchs oder Wolf.","dog_p4":"Ein großes Lächeln erhöht das Mundverhältnis. Wenn Sie den Alltagsausdruck wollen, messen Sie auch ein Foto mit geschlossenem Mund.","fox_title":"Fuchsgesicht — Tiergesichter-Atlas","fox_meta":"Ein Profil für ein langes Gesicht, ein schmales Kinn und scharfe Augen.","fox_h1":"Fuchsgesicht","fox_p1":"Ein Fuchsgesicht ist ein langer Umriss, ein schmales Kinn und scharfe Augen. Es trennt sich von einem langen Gesicht mit großen Augen, etwa dem Hirsch, durch die Augenform.","fox_p2":"Das Fuchsprofil rückt näher, wenn die Gesichtshöhe die Breite übersteigt, die Augen schmal sind und die Kinnspitze schlank ist. Die Nase ist schmal, aber lang, und die Augen sitzen etwas näher beieinander.","fox_p3":"Das Hirschprofil ist ebenfalls ein langes Gesicht mit schmalem Kiefer, aber der Hirsch sucht größere Augen und der Fuchs schmale, scharfe Augen. Liegen die Punktzahlen nah, lesen Sie die Augenform mit.","fox_p4":"Eine Seitenansicht lässt das Kinn noch schmaler wirken. Haare, die das Kinn bedecken, verbergen das Kinnverhältnis. Nutzen Sie ein Foto von vorn, auf dem die Kieferlinie sichtbar ist.","rabbit_title":"Hasengesicht — Tiergesichter-Atlas","rabbit_meta":"Ein Profil für große Augen und kleine Nase und kleinen Mund, hier als runder, weicher Eindruck gelesen.","rabbit_h1":"Hasengesicht","rabbit_p1":"Ein Hasengesicht hat große Augen und kleine Nase und kleinen Mund, deshalb ist der Eindruck rund und weich. Es ist eines der Profile in diesem Atlas, das am stärksten auf die Augengröße sieht.","rabbit_p2":"Das Gesicht ist rund, die Augen sind breit, die Augenform ist rund und der Augenabstand ist etwas weit. Nasenbreite, Nasenlänge und Mundbreite sind klein, und das Mittelgesicht ist kurz.","rabbit_p3":"Das Eulenprofil hat ebenfalls große Augen und ein rundes Gesicht. Die Eule neigt stärker zu weitem Augenabstand und einem kreisnäheren Umriss. Der Hase neigt zu großen Augen mit kleiner Nase und kleinem Mund.","rabbit_p4":"Sehr weit geöffnete Augen erhöhen die Augenhöhe und können das Ergebnis zum Hasen oder zur Eule verschieben. Für eine Alltagsgröße ist ein Foto mit natürlich geöffneten Augen besser.","owl_title":"Eulengesicht — Tiergesichter-Atlas","owl_meta":"Ein Profil für ein sehr rundes Gesicht, große Augen und einen weiten Augenabstand.","owl_h1":"Eulengesicht","owl_p1":"Ein Eulengesicht ist ein sehr rundes Gesicht mit großen Augen, deshalb wirken die Züge kreisförmig. Unter den neun Profilen zieht dieses die Gesichtsronde am stärksten.","owl_p2":"Gesichtsronde, Augengröße, runde Augenform und Augenabstand werden alle auf der großen Seite gelesen. Nase und Mund sind klein und kurz, die Kinnspitze ist weich breit und das Mittelgesicht ist kurz.","owl_p3":"Die Punktzahl liegt oft nahe am Hasen. Weiter Augenabstand und ein fast kreisförmiger Umriss neigen zur Eule. Sind nur Nase und Mund klein und bleibt etwas Gesichtslänge, lesen Sie Hase und Katze daneben.","owl_p4":"Eine sehr nahe Weitwinkelaufnahme verzerrt die Gesichtsmitte zu einer runderen Form. Aus mindestens einer Armlänge bläht sich der Umriss weniger auf.","bear_title":"Bärengesicht — Tiergesichter-Atlas","bear_meta":"Ein Profil für ein breites Gesicht, eine breite Nase und einen breiten Kiefer mit kleineren Augen.","bear_h1":"Bärengesicht","bear_p1":"Ein Bärengesicht ist ein breites Gesicht, eine breite Nase und ein breiter Kiefer mit kleineren Augen, der Eindruck, den dieser Atlas als fest und gelassen liest. Es sieht mehr auf die Gesichtsbreite als auf die Augengröße.","bear_p2":"Nasenbreite, Kieferbreite und Kinn sind breiter als der Durchschnitt, und die Augengröße ist eher klein. Der Mund ist etwas breit. Das Mittelgesicht bleibt nahe am Durchschnitt.","bear_p3":"Das Löwenprofil hat ebenfalls eine breite Nase und einen breiten Kiefer. Der Löwe legt mehr Gewicht auf Mund und Kiefer, und die Augen müssen nicht sehr klein sein. Kleine Augen mit Breite über das ganze Gesicht liegen näher am Bären.","bear_p4":"Ein Bart, eine Maske oder eine Hand verdeckt den Rand von Nase und Kiefer. Fotografieren Sie so, dass Nasenspitze und Kieferlinie sichtbar sind.","lion_title":"Löwengesicht — Tiergesichter-Atlas","lion_meta":"Ein Profil für breite Nase, breiten Mund und breiten Kiefer, sodass die Züge weit wirken.","lion_h1":"Löwengesicht","lion_p1":"Ein Löwengesicht hat eine breite Nase, einen breiten Mund und einen breiten Kiefer, deshalb wirken die Züge kräftig. Dieses Profil sieht mehr auf die Breite der unteren Gesichtshälfte als auf Augengröße oder Gesichtslänge.","lion_p2":"Nasenbreite, Mundbreite und Kieferbreite werden auf der breiten Seite gelesen. Die Augengröße ist etwas kleiner als der Durchschnitt, und die Runde des ganzen Gesichts entfernt sich nicht weit vom Durchschnitt.","lion_p3":"Das Welpenprofil hat ebenfalls einen breiten Mund, aber mit runden, freundlichen Augen. Die Löwenpunktzahl wird mehr von der Breite von Nase, Mund und Kiefer gezogen als von den Augen.","lion_p4":"Lächeln oder Sprechen macht den Mund breiter. Vergleichen Sie mit einem Foto bei geschlossenem Mund, ob der Ausdruck den Unterschied erzeugt hat.","deer_title":"Hirschgesicht — Tiergesichter-Atlas","deer_meta":"Ein Profil für ein langes Gesicht, große Augen und schmalen Kiefer und schmales Kinn.","deer_h1":"Hirschgesicht","deer_p1":"Ein Hirschgesicht ist ein langes Gesicht mit großen Augen und schmalem Kiefer, eine feine und sanfte Linie in diesem Atlas. Unter langen Gesichtern wird das mit den größeren Augen als Hirsch gelesen.","deer_p2":"Die Gesichtshöhe ist lang, die Augen sind groß, die Nase ist schmal, Kiefer und Kinnspitze sind schlank und das Mittelgesicht ist lang. Die Augenform muss nicht so schmal sein wie beim Fuchs.","deer_p3":"Fuchs und Wolf sind ebenfalls lange Gesichter. Der Hirsch ist die Verbindung aus großen Augen und schlankem Kiefer. Der Wolf ist die Verbindung aus schmalen Augen und langem Mittelgesicht.","deer_p4":"Eine Kamera von oben verkürzt den Kiefer. Steht die Kamera auf Augenhöhe, wird die Gesichtshöhe weniger verzerrt.","wolf_title":"Wolfsgesicht — Tiergesichter-Atlas","wolf_meta":"Ein Profil für schmale Augen und ein langes Mittelgesicht und eine lange Nase.","wolf_h1":"Wolfsgesicht","wolf_p1":"Ein Wolfsgesicht hat schmale Augen und ein langes Mittelgesicht, deshalb wirkt der Umriss scharf. Der Mund bleibt nahe am Durchschnitt, und das lange Gesicht wird am Abstand zwischen Augen und Nase gelesen.","wolf_p2":"Die Augenhöhe ist kurz, die Augen sitzen näher beieinander, und sowohl die Nase als auch die Strecke von den Augen zur Nasenspitze sind lang. Das Gesicht ist eher lang, und die Kinnspitze wird als schmal gelesen.","wolf_p3":"Das Fuchsprofil ist oft der Nachbar. Der Fuchs legt mehr Gewicht auf eine schlankere Kinnspitze und eine schmalere Nase. Der Wolf legt mehr Gewicht auf schmale Augen und die Länge des Mittelgesichts.","wolf_p4":"Zusammenkneifen kann die Wolfseite allein über das Augenform-Verhältnis anheben. Fotografieren Sie mit den Augen so offen, wie sie gewöhnlich sind."},"ru":{"nav_label":"Меню атласа","nav_tool":"Измерить лицо","nav_method":"Как устроено измерение","nav_about":"О проекте","nav_privacy":"Конфиденциальность","nav_contact":"Контакт","theme_group":"Тема","theme_light":"Свет","theme_dark":"Тьма","language_group":"Язык","footer":"Фото обрабатываются только в этом браузере и не загружаются. Результат — игровое сравнение пропорций лица, а не научный или личностный тест. Выражение, угол, очки и свет могут изменить порядок.","try_tool":"Измерить лицо по этому атласу","read_method":"Прочитать, как измеряются десять отношений","other_animals":"Другие профили животных","animal_ratio_heading":"Отношения, которые склоняются сюда","animal_score_heading":"Что значит близкий балл","animal_photo_heading":"Когда фото сдвигает место","name_cat":"Кошачье лицо","name_dog":"Щенячье лицо","name_fox":"Лисье лицо","name_rabbit":"Кроличье лицо","name_owl":"Совиное лицо","name_bear":"Медвежье лицо","name_lion":"Львиное лицо","name_deer":"Оленье лицо","name_wolf":"Волчье лицо","method_title":"Как устроено измерение — Атлас звериных лиц","method_meta":"Объясняет, как измеряются отношения длины лица, глаз, носа, рта и челюсти и как они сравниваются с девятью звериными профилями.","method_h1":"Как устроено измерение","method_lead":"Этот атлас не смотрит на волосы, уши и одежду. Он читает длины на лице в фото и сравнивает только эти длины, делённые на размер лица. Число пикселей меняется с расстоянием, поэтому сырое число пикселей — не балл.","method_measure":"Анализ идёт в этом браузере. Фото не отправляется на сервер. Если в выбранной области несколько лиц, берётся самое крупное. Средние ниже — стартовая точка этого атласа для фото анфас. Это не медицинская норма.","method_ratios_heading":"Десять отношений","method_r1":"Форма лица. Ширина лица, делённая на высоту лица. Большее число — более широкое лицо, меньшее — более длинное. Среднее этого атласа — 0.82.","method_r2":"Размер глаз. Ширина глаза, делённая на ширину лица. 0.20 значит, что ширина глаза составляет 20% ширины лица.","method_r3":"Форма глаз. Высота глаза, делённая на ширину глаза. Больше — круглее, меньше — уже и острее. Среднее здесь — 0.33.","method_r4":"Расстояние между глазами. Расстояние между глазами, делённое на ширину лица. Среднее близко к 0.25.","method_r5":"Ширина носа. Ширина носа, делённая на ширину лица. Среднее близко к 0.28.","method_r6":"Длина носа. Длина носа, делённая на высоту лица. Среднее — 0.30.","method_r7":"Ширина рта. Ширина рта, делённая на ширину лица. Среднее близко к 0.40.","method_r8":"Ширина челюсти. Более широкая часть челюсти, делённая на ширину лица. Среднее — 0.80.","method_r9":"Подбородок. Ширина подбородка, делённая на ширину лица. Среднее — 0.32.","method_r10":"Средняя часть лица. Длина от глаз до кончика носа, делённая на высоту лица. Среднее — 0.25.","method_score_heading":"Как получается балл","method_score":"Каждое отношение превращается в расстояние от среднего, затем сравнивается с профилем каждого животного. Черты, которые задают впечатление, например размер глаз, весят чуть больше. Черты, которые легко меняются от фото к фото, например кончик подбородка, весят меньше. Ближайшее животное получает более высокий балл. Балл останавливается на 94. Он никогда не показывает 100, чтобы ошибка одного фото не выглядела идеальным совпадением.","method_photo_heading":"Когда у того же человека другое место","method_photo":"Поворот головы, прищур, широкая улыбка, очень тусклый свет или крошечное лицо в кадре могут изменить место. Фото анфас, глаза на уровне камеры и закрытый рот сравнивать легче. Оправа, закрывающая внешний угол глаза, может исказить длину глаза. Очень близкий широкоугольный кадр делает середину лица круглее.","method_animals_heading":"Девять звериных профилей","method_animals":"Каждое животное ищет свою смесь больших и малых отношений. Выберите имя, чтобы прочитать этот профиль отдельно. Страницы не повторяют один абзац с подменой только имени животного.","about_title":"О проекте — Атлас звериных лиц","about_meta":"Что сравнивает Атлас звериных лиц, где остаётся фото и как читать результат.","about_h1":"Об этом атласе","about_p1":"Атлас звериных лиц — программа в браузере, которая сравнивает отношения длины на фото лица с профилями кошки, щенка, лисы, кролика, совы, медведя, льва, оленя и волка. Она обещает одно: измерить отношения в выбранной области и показать, какой из девяти профилей ближе.","about_p2":"Файл фото читается только в этом браузере и не загружается на сервер анализа. Когда вы закрываете страницу, фото уходит вместе с ней. На этом устройстве остаются только выбранный язык и светлая или тёмная тема.","about_p3":"Результат — игровое сравнение. Инструмент сделан не для описания личности и не для медицины, генетики или проверки личности. Вопросы о сайте, ошибках или конфиденциальности идут на страницу контакта.","privacy_title":"Конфиденциальность — Атлас звериных лиц","privacy_meta":"Как фото лица, язык, реклама, комментарии и форма контакта обращаются с информацией.","privacy_h1":"Конфиденциальность","privacy_photo_heading":"Фото лица","privacy_photo":"Фото лица, снятое камерой или загруженное для анализа, обрабатывается только в памяти этого браузера. Оно не отправляется на сервер Атласа звериных лиц и не сохраняется в учётной записи. Когда вы закрываете страницу или выбираете другое фото, предыдущее не остаётся.","privacy_store_heading":"Настройки на этом устройстве","privacy_store":"Выбранный язык хранится в этом браузере под именем language_code, а светлая или тёмная тема — под theme_mode. Эти значения только возвращают тот же вид при следующем визите. Вместе с фото лица они не отправляются.","privacy_ads_heading":"Реклама","privacy_ads":"Сайт использует автоматическую рекламу Google AdSense. Когда показ идёт, Google может использовать cookie или похожие идентификаторы, чтобы выбирать и измерять рекламу. Описание Google о данных для рекламы: https://policies.google.com/technologies/ads . Для подтверждения владельца сайта идентификатор издателя ca-pub-8803401825336300 указан в метатеге в начале страницы и в ads.txt в корне сайта.","privacy_disqus_heading":"Комментарии","privacy_disqus":"Комментарии есть только внизу страницы измерения, их обрабатывает Disqus. Чтобы написать комментарий, нужен вход или регистрация Disqus, и Disqus может использовать свои cookie. Текст комментария хранится отдельно от фото лица. Disqus описывает свою практику конфиденциальности здесь: https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Форма контакта","privacy_form":"Только когда вы нажимаете отправить на странице контакта, имя, компания или бренд, почта для ответа и сообщение передаются в Formspree (https://formspree.io). Фото лица в эти поля не входит. Если форму не отправить, набираемый текст не сохраняется.","privacy_font_heading":"Шрифты","privacy_font":"Шрифты загружаются из Google Fonts. При открытии страницы браузер запрашивает файлы шрифтов у fonts.googleapis.com и fonts.gstatic.com. В запрос могут входить адрес страницы и обычные сведения о браузере.","privacy_ask_heading":"Вопросы","privacy_ask":"Если здесь чего-то не хватает или есть ошибка, напишите на странице контакта. Фото лица нет на сервере, поэтому возвращать нечего. Удаление комментариев делается в Disqus. Просьбу удалить уже отправленный запрос можно передать через страницу контакта и ящик, который его получил.","contact_title":"Контакт — Атлас звериных лиц","contact_meta":"Страница контакта для вопросов о сотрудничестве, ошибках и конфиденциальности Атласа звериных лиц.","contact_h1":"Контакт","contact_help":"Оставьте вопрос о сотрудничестве, ошибке или конфиденциальности. Фото лица к этой форме не прикладывается. Ответ придёт на указанную почту.","contact_name":"Имя","contact_company":"Компания или бренд","contact_email":"Почта для ответа","contact_message":"Сообщение","contact_send":"Отправить","contact_subject":"Вопрос к Атласу звериных лиц","contact_invalid":"Введите имя, почту для ответа и сообщение, затем отправьте снова.","contact_sending":"Отправляем сообщение.","contact_sent":"Сообщение отправлено. Мы ответим на указанную почту.","contact_fail":"Сообщение не отправилось. Попробуйте ещё раз через минуту.","contact_network":"Сообщение не отправилось. Проверьте связь и попробуйте снова.","contact_teaser_title":"Контакт","contact_teaser":"Вопросы о сотрудничестве, ошибках или конфиденциальности — на странице контакта. Ответ придёт на указанную почту. Фото лица в сообщение не входит.","atlas_help":"Выберите имя животного, чтобы прочитать профиль. Атлас можно смотреть без фото лица.","lead":"Сравнение использует отношения длины лица, глаз, носа, рта и челюсти, а не волосы или уши. Балл — это расстояние до девяти звериных профилей. Это не тест личности и не научная классификация.","cat_title":"Кошачье лицо — Атлас звериных лиц","cat_meta":"Профиль крупных глаз с небольшими носом и ртом, из-за чего черты будто собираются к центру.","cat_h1":"Кошачье лицо","cat_p1":"Кошачье лицо — впечатление, что глаза, нос и рот сидят ближе к середине лица. Кошачий профиль этого атласа ближе, когда лицо чуть круглое, глаза крупные, а нос и рот меньше среднего.","cat_p2":"Ширина лица щедрая относительно высоты, и глаза занимают большую долю ширины лица. Более узкий и короткий нос и меньший рот склоняются к кошке. Средняя часть лица, от глаз до кончика носа, короткая.","cat_p3":"Высокий балл значит, что вместе десять отношений ближе всего к кошачьему профилю. Одни крупные глаза не делают кошачье лицо. Широкие нос и рот могут оказаться ближе к медведю или льву.","cat_p4":"Улыбка расширяет рот и может склонить результат к щенку или льву. Поворот головы делает глаза меньше, чем они есть. Фото анфас с закрытым ртом проще сравнивать с этим профилем.","dog_title":"Щенячье лицо — Атлас звериных лиц","dog_meta":"Профиль круглых глаз и широкого рта: вид, который этот атлас читает как мягкий и дружелюбный.","dog_h1":"Щенячье лицо","dog_p1":"Щенячье лицо — впечатление круглых глаз и широкого рта, поэтому выражение кажется мягким. Нос остаётся около среднего, а слегка круглое лицо ближе к щенячьему профилю.","dog_p2":"Щенячий профиль ближе, когда форма глаза, высота глаза делённая на ширину, круглая, а рот широк на лице. Чуть больший промежуток между глазами входит в то же чтение.","dog_p3":"Один широкий рот — ещё не щенячье лицо. Если нос и челюсть тоже широкие, ближе могут быть лев или медведь. Узкие глаза сдвигают результат к лисе или волку.","dog_p4":"Широкая улыбка увеличивает долю рта. Если нужно повседневное впечатление, измерьте и фото с закрытым ртом.","fox_title":"Лисье лицо — Атлас звериных лиц","fox_meta":"Профиль длинного лица, узкого подбородка и острых глаз.","fox_h1":"Лисье лицо","fox_p1":"Лисье лицо — длинный контур, узкий подбородок и острые глаза. От длинного лица с крупными глазами, как у оленя, его отделяет форма глаз.","fox_p2":"Лисий профиль ближе, когда высота лица больше ширины, глаза узкие, а кончик подбородка тонкий. Нос узкий, но длинный, и глаза сидят чуть ближе друг к другу.","fox_p3":"Олений профиль тоже длинное лицо с узкой челюстью, но олень ищет более крупные глаза, а лиса — узкие и острые. Если баллы близки, смотрите форму глаз вместе с ними.","fox_p4":"Вид сбоку делает подбородок ещё уже. Волосы, закрывающие подбородок, прячут его долю. Берите фото анфас, где видна линия челюсти.","rabbit_title":"Кроличье лицо — Атлас звериных лиц","rabbit_meta":"Профиль крупных глаз и небольших носа и рта, здесь это читается как круглое мягкое впечатление.","rabbit_h1":"Кроличье лицо","rabbit_p1":"У кроличьего лица крупные глаза и небольшие нос и рот, поэтому впечатление круглое и мягкое. Это один из профилей атласа, который сильнее всего смотрит на размер глаз.","rabbit_p2":"Лицо круглое, глаза широкие, форма глаза круглая, промежуток между глазами чуть шире. Ширина и длина носа и ширина рта малы, средняя часть лица короткая.","rabbit_p3":"У совиного профиля тоже крупные глаза и круглое лицо. Сова сильнее склоняется к широкому промежутку глаз и более круглому контуру. Кролик склоняется к крупным глазам с небольшими носом и ртом.","rabbit_p4":"Очень широко открытые глаза увеличивают высоту глаза и могут сдвинуть результат к кролику или сове. Для повседневного размера лучше фото с естественно открытыми глазами.","owl_title":"Совиное лицо — Атлас звериных лиц","owl_meta":"Профиль очень круглого лица, крупных глаз и широкого промежутка между глазами.","owl_h1":"Совиное лицо","owl_p1":"Совиное лицо — очень круглое лицо с крупными глазами, поэтому черты читаются круглыми. Среди девяти профилей этот сильнее всего тянет округлость лица.","owl_p2":"Округлость лица, размер глаз, круглая форма глаза и промежуток между глазами читаются на большой стороне. Нос и рот малы и коротки, кончик подбородка мягко широк, средняя часть лица короткая.","owl_p3":"Балл часто оказывается рядом с кроликом. Широкий промежуток глаз и контур, близкий к кругу, склоняются к сове. Если малы только нос и рот, а длина лица ещё есть, смотрите кролика и кошку рядом.","owl_p4":"Очень близкий широкоугольный кадр искажает середину лица в более круглую форму. Хотя бы с расстояния вытянутой руки контур раздувается меньше.","bear_title":"Медвежье лицо — Атлас звериных лиц","bear_meta":"Профиль широкого лица, носа и челюсти с меньшими глазами.","bear_h1":"Медвежье лицо","bear_p1":"Медвежье лицо — широкие лицо, нос и челюсть с меньшими глазами: впечатление, которое этот атлас читает как основательное и спокойное. Он больше смотрит на ширину лица, чем на размер глаз.","bear_p2":"Ширина носа, ширина челюсти и подбородок шире среднего, а размер глаз на малой стороне. Рот немного широк. Средняя часть лица остаётся около среднего.","bear_p3":"У львиного профиля тоже широкие нос и челюсть. Лев больше весит рот и челюсть, и глаза не обязаны быть очень маленькими. Малые глаза при ширине всего лица ближе к медведю.","bear_p4":"Борода, маска или рука скрывают край носа и челюсти. Снимайте так, чтобы были видны кончик носа и линия челюсти.","lion_title":"Львиное лицо — Атлас звериных лиц","lion_meta":"Профиль широких носа, рта и челюсти, из-за чего черты читаются широкими.","lion_h1":"Львиное лицо","lion_p1":"У львиного лица широкие нос, рот и челюсть, поэтому черты выглядят сильными. Этот профиль смотрит на ширину нижней части лица больше, чем на размер глаз или длину лица.","lion_p2":"Ширина носа, рта и челюсти читается на широкой стороне. Размер глаз чуть меньше среднего, а округлость всего лица недалеко уходит от среднего.","lion_p3":"У щенячьего профиля тоже широкий рот, но с круглыми дружелюбными глазами. Львиный балл тянут ширина носа, рта и челюсти сильнее, чем глаза.","lion_p4":"Улыбка или речь делают рот шире. Сравните с фото при закрытом рте, чтобы понять, создало ли разницу выражение.","deer_title":"Оленье лицо — Атлас звериных лиц","deer_meta":"Профиль длинного лица, крупных глаз и узких челюсти и подбородка.","deer_h1":"Оленье лицо","deer_p1":"Оленье лицо — длинное лицо с крупными глазами и узкой челюстью, тонкая и мягкая линия в этом атласе. Среди длинных лиц то, у которого глаза крупнее, читается как олень.","deer_p2":"Высота лица длинная, глаза крупные, нос узкий, челюсть и кончик подбородка тонкие, средняя часть лица длинная. Форма глаза не обязана быть такой узкой, как у лисы.","deer_p3":"Лиса и волк тоже длинные лица. Олень — сочетание крупных глаз и тонкой челюсти. Волк — сочетание узких глаз и длинной средней части лица.","deer_p4":"Камера сверху укорачивает челюсть. Когда камера на уровне глаз, высота лица искажается меньше.","wolf_title":"Волчье лицо — Атлас звериных лиц","wolf_meta":"Профиль узких глаз и длинных средней части лица и носа.","wolf_h1":"Волчье лицо","wolf_p1":"У волчьего лица узкие глаза и длинная средняя часть, поэтому контур выглядит острым. Рот остаётся около среднего, а длинное лицо читается по расстоянию между глазами и носом.","wolf_p2":"Высота глаза короткая, глаза сидят ближе, и нос, и отрезок от глаз до кончика носа длинные. Лицо скорее длинное, а кончик подбородка читается узким.","wolf_p3":"Лисий профиль часто рядом. Лиса больше весит более тонкий кончик подбородка и более узкий нос. Волк больше весит узкие глаза и длину средней части лица.","wolf_p4":"Прищур может поднять волчью сторону только за счёт отношения формы глаза. Снимайте с глазами, открытыми как обычно."},"vi":{"nav_label":"Mục lục sổ tay","nav_tool":"Đo khuôn mặt","nav_method":"Cách đo","nav_about":"Giới thiệu","nav_privacy":"Quyền riêng tư","nav_contact":"Liên hệ","theme_group":"Giao diện","theme_light":"Sáng","theme_dark":"Tối","language_group":"Ngôn ngữ","footer":"Ảnh chỉ được xử lý trong trình duyệt này và không được tải lên. Kết quả là so sánh vui các tỷ lệ khuôn mặt, không phải bài kiểm tra khoa học hay tính cách. Biểu cảm, góc chụp, kính và ánh sáng có thể đổi thứ hạng.","try_tool":"Đo khuôn mặt bằng sổ tay này","read_method":"Đọc cách đo mười tỷ lệ","other_animals":"Hồ sơ động vật khác","animal_ratio_heading":"Các tỷ lệ nghiêng về phía này","animal_score_heading":"Điểm gần có nghĩa gì","animal_photo_heading":"Khi ảnh làm đổi thứ hạng","name_cat":"Mặt mèo","name_dog":"Mặt cún","name_fox":"Mặt cáo","name_rabbit":"Mặt thỏ","name_owl":"Mặt cú","name_bear":"Mặt gấu","name_lion":"Mặt sư tử","name_deer":"Mặt hươu","name_wolf":"Mặt sói","method_title":"Cách đo — Sổ tay khuôn mặt động vật","method_meta":"Giải thích cách đo tỷ lệ chiều dài của mặt, mắt, mũi, miệng và hàm, rồi so với chín hồ sơ động vật.","method_h1":"Cách đo","method_lead":"Sổ tay này không nhìn tóc, tai hay quần áo. Nó đọc các chiều dài trên khuôn mặt trong ảnh và chỉ so sánh những chiều dài đó chia cho kích thước mặt. Số điểm ảnh đổi theo khoảng cách, nên số điểm ảnh thô không phải điểm số.","method_measure":"Phân tích chạy trong trình duyệt này. Ảnh không được gửi lên máy chủ. Nếu vùng bạn chọn có vài khuôn mặt, khuôn mặt lớn nhất được dùng. Các mức trung bình bên dưới là điểm xuất phát của sổ tay cho ảnh chính diện. Đó không phải khoảng bình thường y khoa.","method_ratios_heading":"Mười tỷ lệ","method_r1":"Dáng mặt. Rộng mặt chia cho cao mặt. Số lớn hơn là mặt rộng hơn, số nhỏ hơn là mặt dài hơn. Trung bình của sổ tay này là 0.82.","method_r2":"Cỡ mắt. Rộng mắt chia cho rộng mặt. 0.20 nghĩa là rộng mắt bằng 20% rộng mặt.","method_r3":"Dáng mắt. Cao mắt chia cho rộng mắt. Lớn hơn thì tròn hơn, nhỏ hơn thì hẹp và sắc hơn. Trung bình ở đây là 0.33.","method_r4":"Khoảng cách mắt. Khoảng cách hai mắt chia cho rộng mặt. Trung bình gần 0.25.","method_r5":"Rộng mũi. Rộng mũi chia cho rộng mặt. Trung bình gần 0.28.","method_r6":"Dài mũi. Dài mũi chia cho cao mặt. Trung bình là 0.30.","method_r7":"Rộng miệng. Rộng miệng chia cho rộng mặt. Trung bình gần 0.40.","method_r8":"Rộng hàm. Phần hàm rộng hơn chia cho rộng mặt. Trung bình là 0.80.","method_r9":"Cằm. Rộng cằm chia cho rộng mặt. Trung bình là 0.32.","method_r10":"Giữa mặt. Chiều dài từ mắt tới chóp mũi chia cho cao mặt. Trung bình là 0.25.","method_score_heading":"Điểm số được tạo ra thế nào","method_score":"Mỗi tỷ lệ được đổi thành khoảng cách so với trung bình, rồi so với hồ sơ của từng động vật. Đặc điểm tạo ấn tượng, như cỡ mắt, được tính nặng hơn một chút. Đặc điểm dễ đổi từ ảnh này sang ảnh khác, như chóp cằm, được tính nhẹ hơn. Động vật gần nhất được điểm cao hơn. Điểm dừng ở 94. Điểm không bao giờ hiện 100, để sai số của một ảnh không bị trình bày như một khớp hoàn hảo.","method_photo_heading":"Khi cùng một người nhận thứ hạng khác","method_photo":"Quay đầu, nheo mắt, cười rộng, ánh sáng rất yếu hoặc khuôn mặt rất nhỏ trong khung có thể đổi thứ hạng. Ảnh chính diện, mắt ngang camera và miệng ngậm, dễ so sánh hơn. Gọng kính che đuôi mắt có thể làm sai chiều dài mắt. Ảnh góc rộng chụp rất gần làm giữa mặt trông tròn hơn.","method_animals_heading":"Chín hồ sơ động vật","method_animals":"Mỗi động vật tìm một hỗn hợp tỷ lệ lớn và nhỏ khác nhau. Chọn một tên để đọc riêng hồ sơ đó. Các trang không lặp một đoạn chỉ bằng cách đổi tên động vật.","about_title":"Giới thiệu — Sổ tay khuôn mặt động vật","about_meta":"Sổ tay khuôn mặt động vật so sánh điều gì, ảnh nằm ở đâu, và cách đọc kết quả.","about_h1":"Về sổ tay này","about_p1":"Sổ tay khuôn mặt động vật là chương trình trình duyệt so sánh tỷ lệ chiều dài trong ảnh mặt với hồ sơ mèo, cún, cáo, thỏ, cú, gấu, sư tử, hươu và sói. Nó hứa một điều: đo các tỷ lệ trong vùng bạn chọn, rồi cho thấy hồ sơ nào trong chín hồ sơ là gần nhất.","about_p2":"Tệp ảnh chỉ được đọc trong trình duyệt này và không được tải lên máy chủ phân tích. Khi đóng trang, ảnh cũng đi theo. Trên thiết bị này chỉ giữ ngôn ngữ bạn chọn và giao diện sáng hoặc tối.","about_p3":"Kết quả là một phép so sánh vui. Công cụ không được làm để mô tả tính cách, cũng không dành cho y khoa, di truyền hay kiểm tra danh tính. Câu hỏi về trang, lỗi hoặc quyền riêng tư gửi tới trang liên hệ.","privacy_title":"Quyền riêng tư — Sổ tay khuôn mặt động vật","privacy_meta":"Ảnh khuôn mặt, cài đặt ngôn ngữ, quảng cáo, bình luận và biểu mẫu liên hệ xử lý thông tin ra sao.","privacy_h1":"Quyền riêng tư","privacy_photo_heading":"Ảnh khuôn mặt","privacy_photo":"Ảnh khuôn mặt chụp bằng camera hoặc tải lên để phân tích chỉ được xử lý trong bộ nhớ của trình duyệt này. Ảnh không được gửi tới máy chủ của Sổ tay khuôn mặt động vật và không được lưu vào tài khoản. Khi đóng trang hoặc chọn ảnh khác, ảnh trước không được giữ lại.","privacy_store_heading":"Cài đặt giữ trên thiết bị này","privacy_store":"Ngôn ngữ đã chọn được lưu trong trình duyệt này dưới tên language_code, giao diện sáng hoặc tối dưới theme_mode. Các giá trị đó chỉ khôi phục cùng một khung nhìn ở lần sau. Chúng không được gửi kèm ảnh khuôn mặt.","privacy_ads_heading":"Quảng cáo","privacy_ads":"Trang này dùng quảng cáo tự động của Google AdSense. Khi quảng cáo hiện, Google có thể dùng cookie hoặc mã nhận dạng tương tự để chọn và đo quảng cáo. Mô tả của Google về thông tin dùng cho quảng cáo nằm ở https://policies.google.com/technologies/ads . Để xác nhận chủ trang, mã nhà xuất bản ca-pub-8803401825336300 nằm trong thẻ meta ở đầu trang và trong ads.txt ở gốc trang.","privacy_disqus_heading":"Bình luận","privacy_disqus":"Bình luận chỉ hiện ở cuối trang đo và do Disqus xử lý. Viết bình luận cần đăng nhập hoặc đăng ký Disqus, và Disqus có thể dùng cookie riêng. Nội dung bình luận được lưu tách khỏi ảnh khuôn mặt. Disqus mô tả cách xử lý quyền riêng tư tại https://help.disqus.com/en/articles/1717103-disqus-privacy-policy .","privacy_form_heading":"Biểu mẫu liên hệ","privacy_form":"Chỉ khi bạn nhấn gửi ở trang liên hệ, tên, công ty hoặc thương hiệu, email nhận trả lời và nội dung mới được chuyển tới Formspree (https://formspree.io). Ảnh khuôn mặt không nằm trong các trường đó. Nếu không gửi biểu mẫu, chữ đang gõ không được lưu.","privacy_font_heading":"Phông chữ","privacy_font":"Phông chữ được tải từ Google Fonts. Khi mở trang, trình duyệt yêu cầu tệp phông từ fonts.googleapis.com và fonts.gstatic.com. Yêu cầu đó có thể gồm địa chỉ trang và thông tin trình duyệt thông thường.","privacy_ask_heading":"Câu hỏi","privacy_ask":"Nếu ở đây thiếu hoặc sai, hãy báo trên trang liên hệ. Ảnh khuôn mặt không nằm trên máy chủ, nên không có tệp để trả lại. Xóa bình luận được xử lý trong Disqus. Yêu cầu xóa một thư đã gửi có thể làm qua trang liên hệ và hộp thư đã nhận thư đó.","contact_title":"Liên hệ — Sổ tay khuôn mặt động vật","contact_meta":"Trang liên hệ cho câu hỏi hợp tác, lỗi và quyền riêng tư về Sổ tay khuôn mặt động vật.","contact_h1":"Liên hệ","contact_help":"Để lại câu hỏi hợp tác, lỗi hoặc quyền riêng tư. Ảnh khuôn mặt không được đính kèm biểu mẫu này. Thư trả lời gửi tới email bạn nhập.","contact_name":"Tên","contact_company":"Công ty hoặc thương hiệu","contact_email":"Email nhận trả lời","contact_message":"Nội dung","contact_send":"Gửi tin","contact_subject":"Câu hỏi Sổ tay khuôn mặt động vật","contact_invalid":"Nhập tên, email nhận trả lời và nội dung, rồi gửi lại.","contact_sending":"Đang gửi tin của bạn.","contact_sent":"Tin đã gửi. Chúng tôi sẽ trả lời tới email bạn đã nhập.","contact_fail":"Không gửi được tin. Hãy thử lại sau một lát.","contact_network":"Không gửi được tin. Kiểm tra kết nối rồi thử lại.","contact_teaser_title":"Liên hệ","contact_teaser":"Câu hỏi về hợp tác, lỗi hoặc quyền riêng tư gửi ở trang liên hệ. Thư trả lời gửi tới email bạn nhập. Ảnh khuôn mặt không nằm trong tin nhắn.","atlas_help":"Chọn tên động vật để đọc hồ sơ. Bạn có thể xem sổ tay mà không cần ảnh khuôn mặt.","lead":"Phép so sánh dùng tỷ lệ chiều dài của khuôn mặt, mắt, mũi, miệng và hàm, không dùng tóc hay tai. Điểm số là khoảng cách tới chín hồ sơ động vật. Đây không phải bài kiểm tra tính cách hay phân loại khoa học.","cat_title":"Mặt mèo — Sổ tay khuôn mặt động vật","cat_meta":"Hồ sơ mắt to, mũi và miệng nhỏ, nên các phần mặt trông tụ về giữa.","cat_h1":"Mặt mèo","cat_p1":"Mặt mèo là ấn tượng mắt, mũi và miệng nằm về phía giữa mặt. Hồ sơ mèo của sổ tay này gần hơn khi mặt hơi tròn, mắt to, mũi và miệng nhỏ hơn trung bình.","cat_p2":"Rộng mặt rộng rãi so với cao mặt, và mắt chiếm nhiều hơn phần rộng mặt. Mũi hẹp hơn và ngắn hơn, cùng miệng nhỏ hơn, nghiêng về mèo. Giữa mặt, từ mắt tới chóp mũi, nằm ở phía ngắn.","cat_p3":"Điểm cao nghĩa là mười tỷ lệ gộp lại gần hồ sơ mèo nhất. Chỉ mắt to không tạo thành mặt mèo. Mũi và miệng rộng có thể gần gấu hoặc sư tử hơn.","cat_p4":"Cười làm miệng rộng ra và có thể đẩy kết quả về cún hoặc sư tử. Quay đầu khiến mắt trông nhỏ hơn thực tế. Ảnh chính diện, miệng ngậm, dễ so với hồ sơ này hơn.","dog_title":"Mặt cún — Sổ tay khuôn mặt động vật","dog_meta":"Hồ sơ mắt tròn và miệng rộng, vẻ mà sổ tay này đọc là hiền và thân thiện.","dog_h1":"Mặt cún","dog_p1":"Mặt cún là ấn tượng mắt tròn và miệng rộng, nên biểu cảm trông hiền. Mũi ở gần trung bình, và mặt hơi tròn nằm gần hồ sơ cún hơn.","dog_p2":"Hồ sơ cún gần hơn khi dáng mắt, cao mắt chia cho rộng mắt, tròn và miệng rộng trên mặt. Khoảng cách mắt hơi rộng cũng thuộc cùng cách đọc.","dog_p3":"Riêng miệng rộng không phải mặt cún. Nếu mũi và hàm cũng rộng, sư tử hoặc gấu có thể gần hơn. Mắt hẹp đẩy kết quả về cáo hoặc sói.","dog_p4":"Cười lớn làm tăng tỷ lệ miệng. Nếu muốn ấn tượng hằng ngày, hãy đo thêm một ảnh miệng ngậm.","fox_title":"Mặt cáo — Sổ tay khuôn mặt động vật","fox_meta":"Hồ sơ mặt dài, cằm hẹp và mắt sắc.","fox_h1":"Mặt cáo","fox_p1":"Mặt cáo là đường nét dài, cằm hẹp và mắt sắc. Nó tách khỏi mặt dài có mắt to, như hươu, nhờ dáng mắt.","fox_p2":"Hồ sơ cáo gần hơn khi cao mặt vượt rộng mặt, mắt hẹp và chóp cằm thanh. Mũi hẹp nhưng dài, và hai mắt ngồi gần nhau hơn một chút.","fox_p3":"Hồ sơ hươu cũng là mặt dài với hàm hẹp, nhưng hươu tìm mắt lớn hơn còn cáo tìm mắt hẹp và sắc. Nếu hai điểm gần nhau, hãy đọc dáng mắt cùng lúc.","fox_p4":"Góc nghiêng làm cằm trông còn hẹp hơn. Tóc che cằm sẽ giấu tỷ lệ cằm. Hãy dùng ảnh chính diện thấy được đường hàm.","rabbit_title":"Mặt thỏ — Sổ tay khuôn mặt động vật","rabbit_meta":"Hồ sơ mắt to, mũi và miệng nhỏ, được đọc ở đây là ấn tượng tròn và mềm.","rabbit_h1":"Mặt thỏ","rabbit_p1":"Mặt thỏ có mắt to, mũi và miệng nhỏ, nên ấn tượng tròn và mềm. Đây là một hồ sơ trong sổ tay nhìn mạnh nhất vào cỡ mắt.","rabbit_p2":"Mặt tròn, mắt rộng, dáng mắt tròn, và khoảng cách mắt hơi rộng. Rộng mũi, dài mũi và rộng miệng đều nhỏ, giữa mặt ngắn.","rabbit_p3":"Hồ sơ cú cũng có mắt to và mặt tròn. Cú nghiêng hơn về khoảng cách mắt rộng và đường nét gần hình tròn. Thỏ nghiêng về mắt to với mũi và miệng nhỏ.","rabbit_p4":"Mở mắt rất to làm tăng cao mắt và có thể đẩy kết quả về thỏ hoặc cú. Với cỡ hằng ngày, ảnh mắt mở tự nhiên tốt hơn.","owl_title":"Mặt cú — Sổ tay khuôn mặt động vật","owl_meta":"Hồ sơ mặt rất tròn, mắt to và khoảng cách mắt rộng.","owl_h1":"Mặt cú","owl_p1":"Mặt cú là mặt rất tròn với mắt to, nên các phần mặt đọc như hình tròn. Trong chín hồ sơ, hồ sơ này kéo độ tròn của mặt mạnh nhất.","owl_p2":"Độ tròn mặt, cỡ mắt, dáng mắt tròn và khoảng cách mắt đều được đọc ở phía lớn. Mũi và miệng nhỏ và ngắn, chóp cằm mềm rộng, giữa mặt ngắn.","owl_p3":"Điểm thường nằm gần thỏ. Khoảng cách mắt rộng và đường nét gần hình tròn nghiêng về cú. Nếu chỉ mũi và miệng nhỏ mà mặt vẫn còn độ dài, hãy đọc thỏ và mèo cùng lúc.","owl_p4":"Góc rộng chụp rất gần bóp giữa mặt thành hình tròn hơn. Từ ít nhất một sải tay, đường nét phồng ít hơn.","bear_title":"Mặt gấu — Sổ tay khuôn mặt động vật","bear_meta":"Hồ sơ mặt, mũi và hàm rộng với mắt nhỏ hơn.","bear_h1":"Mặt gấu","bear_p1":"Mặt gấu là mặt, mũi và hàm rộng với mắt nhỏ hơn, ấn tượng mà sổ tay này đọc là chắc và điềm đạm. Nó nhìn rộng mặt nhiều hơn cỡ mắt.","bear_p2":"Rộng mũi, rộng hàm và cằm rộng hơn trung bình, cỡ mắt ở phía nhỏ. Miệng hơi rộng. Giữa mặt ở gần trung bình.","bear_p3":"Hồ sơ sư tử cũng có mũi và hàm rộng. Sư tử đặt nặng hơn vào miệng và hàm, và mắt không cần rất nhỏ. Mắt nhỏ với độ rộng khắp mặt nằm gần gấu hơn.","bear_p4":"Râu, khẩu trang hoặc bàn tay che mép mũi và hàm. Hãy chụp sao cho thấy chóp mũi và đường hàm.","lion_title":"Mặt sư tử — Sổ tay khuôn mặt động vật","lion_meta":"Hồ sơ mũi, miệng và hàm rộng, nên các phần mặt đọc là rộng.","lion_h1":"Mặt sư tử","lion_p1":"Mặt sư tử có mũi, miệng và hàm rộng, nên các phần mặt trông mạnh. Hồ sơ này nhìn độ rộng nửa dưới mặt nhiều hơn cỡ mắt hay độ dài mặt.","lion_p2":"Rộng mũi, rộng miệng và rộng hàm được đọc ở phía rộng. Cỡ mắt nhỏ hơn trung bình một chút, và độ tròn của cả mặt không rời trung bình nhiều.","lion_p3":"Hồ sơ cún cũng có miệng rộng, nhưng với mắt tròn và thân thiện. Điểm sư tử bị kéo bởi độ rộng mũi, miệng và hàm nhiều hơn bởi mắt.","lion_p4":"Cười hoặc nói làm miệng rộng hơn. Hãy so với ảnh miệng ngậm để xem biểu cảm có tạo ra khác biệt không.","deer_title":"Mặt hươu — Sổ tay khuôn mặt động vật","deer_meta":"Hồ sơ mặt dài, mắt to, hàm và cằm hẹp.","deer_h1":"Mặt hươu","deer_p1":"Mặt hươu là mặt dài với mắt to và hàm hẹp, một đường nét thanh và hiền trong sổ tay này. Trong các mặt dài, mặt có mắt lớn hơn được đọc là hươu.","deer_p2":"Cao mặt dài, mắt to, mũi hẹp, hàm và chóp cằm thanh, giữa mặt dài. Dáng mắt không cần hẹp như cáo.","deer_p3":"Cáo và sói cũng là mặt dài. Hươu là sự kết hợp mắt to và hàm thanh. Sói là sự kết hợp mắt hẹp và giữa mặt dài.","deer_p4":"Camera nhìn từ trên xuống làm hàm ngắn lại. Khi camera ngang mắt, cao mặt ít bị méo hơn.","wolf_title":"Mặt sói — Sổ tay khuôn mặt động vật","wolf_meta":"Hồ sơ mắt hẹp, giữa mặt và mũi dài.","wolf_h1":"Mặt sói","wolf_p1":"Mặt sói có mắt hẹp và giữa mặt dài, nên đường nét trông sắc. Miệng ở gần trung bình, và mặt dài được đọc từ khoảng cách giữa mắt và mũi.","wolf_p2":"Cao mắt ngắn, hai mắt ngồi gần hơn, mũi và đoạn từ mắt tới chóp mũi đều dài. Mặt ở phía dài, chóp cằm được đọc là hẹp.","wolf_p3":"Hồ sơ cáo thường là hàng xóm. Cáo đặt nặng hơn vào chóp cằm thanh hơn và mũi hẹp hơn. Sói đặt nặng hơn vào mắt hẹp và độ dài giữa mặt.","wolf_p4":"Nheo mắt có thể nâng phía sói chỉ từ tỷ lệ dáng mắt. Hãy chụp khi mắt mở như thường ngày."}};
  var FORM_URL = "https://formspree.io/f/xqppylkl";
  var is_sending = false;

  // 저장값과 브라우저 언어에서 지금 쓸 언어를 고른다.
  var KNOWN_LANGUAGE = { ko: true, en: true, ja: true, zh: true, "zh-Hant": true, hi: true, es: true, pt: true, ar: true, fr: true, id: true, de: true, ru: true, vi: true };

  // 페이지에 이미 적힌 언어 코드만 안내 문구에 쓴다.
  function current_language() {
    var from_page = document.documentElement.getAttribute("data-language");
    if (KNOWN_LANGUAGE[from_page]) {
      return from_page;
    }
    return "ko";
  }

  // 문구 키를 현재 언어의 문장으로 바꾼다. 없으면 한국어를 쓴다.
  function translate(key) {
    var language_code = current_language();
    var table = TEXT[language_code] || TEXT.ko;
    var template = table[key] || (TEXT.ko && TEXT.ko[key]) || "";
    if (!template) {
      console.error("안내 문구를 찾지 못했습니다.", key);
      return "";
    }
    return template;
  }

  // 화면에 적힌 고정 글을 현재 언어로 다시 채운다.
  function apply_static_text() {
    document.querySelectorAll("[data-i18n]").forEach(function (node) {
      var text = translate(node.getAttribute("data-i18n"));
      if (text) {
        node.textContent = text;
      }
    });
    document.querySelectorAll("[data-i18n-aria]").forEach(function (node) {
      var text = translate(node.getAttribute("data-i18n-aria"));
      if (text) {
        node.setAttribute("aria-label", text);
      }
    });
    document.querySelectorAll("[data-i18n-content]").forEach(function (node) {
      var text = translate(node.getAttribute("data-i18n-content"));
      if (text) {
        node.setAttribute("content", text);
      }
    });
    document.querySelectorAll("[data-i18n-value]").forEach(function (node) {
      var text = translate(node.getAttribute("data-i18n-value"));
      if (text) {
        node.value = text;
      }
    });
    var title_key = document.body.getAttribute("data-title-key");
    if (title_key) {
      var title_text = translate(title_key);
      if (title_text) {
        document.title = title_text;
      }
    }
    ["ko", "en", "ja", "zh", "zh-Hant", "hi", "es", "pt", "ar", "fr", "id", "de", "ru", "vi"].forEach(function (code) {
      var button = document.getElementById("button_language_" + code);
      if (!button) {
        return;
      }
      var is_selected = code === current_language();
      button.classList.toggle("is_selected", is_selected);
      button.setAttribute("aria-pressed", is_selected ? "true" : "false");
    });
  }

  // 언어를 바꾸고 다음 방문에도 남긴다.
  function apply_language(language_code, is_persist) {
    var next_language = KNOWN_LANGUAGE[language_code] ? language_code : "ko";
    document.documentElement.lang = next_language;
    document.documentElement.setAttribute("data-language", next_language);
    document.documentElement.dir = next_language === "ar" ? "rtl" : "ltr";
    if (is_persist) {
      try {
        localStorage.setItem("language_code", next_language);
      } catch (error) {
        console.error("언어 선택을 저장하지 못했습니다.", error);
      }
    }
    apply_static_text();
  }

  // 화면 색과 모드 버튼 표시를 함께 바꾼다.
  function apply_theme(theme_mode) {
    var is_dark = theme_mode === "dark";
    document.documentElement.setAttribute("data-theme", is_dark ? "dark" : "light");
    var theme_color = document.querySelector('meta[name="theme-color"]');
    if (theme_color) {
      theme_color.setAttribute("content", is_dark ? "#101c16" : "#f4f1ea");
    }
    var light_button = document.getElementById("button_theme_light");
    var dark_button = document.getElementById("button_theme_dark");
    if (light_button && dark_button) {
      light_button.classList.toggle("is_selected", !is_dark);
      dark_button.classList.toggle("is_selected", is_dark);
      light_button.setAttribute("aria-pressed", String(!is_dark));
      dark_button.setAttribute("aria-pressed", String(is_dark));
    }
  }

  // 고른 모드를 바로 적용하고, 다음 방문에도 남도록 저장한다.
  function choose_theme(theme_mode) {
    var next_theme = theme_mode === "dark" ? "dark" : "light";
    try {
      apply_theme(next_theme);
      localStorage.setItem("theme_mode", next_theme);
    } catch (error) {
      console.error("화면 모드를 저장하지 못했습니다.", error);
      apply_theme(next_theme);
    }
  }

  // 문의 상태 문장을 바꾸고, 실패면 붉은색으로 표시한다.
  function set_contact_status(key, is_error) {
    var status = document.getElementById("contact_status");
    if (!status) {
      return;
    }
    status.textContent = translate(key);
    status.classList.toggle("is_error", Boolean(is_error));
  }

  // 입력한 문의를 Formspree로 보내고, 페이지는 그대로 둔다.
  async function submit_contact_form(event) {
    event.preventDefault();
    var form = document.getElementById("contact_form");
    var send_button = document.getElementById("contact_send");
    if (!form || is_sending) {
      return;
    }
    var form_data = new FormData(form);
    if (String(form_data.get("_gotcha") || "").trim()) {
      console.error("자동 입력으로 보이는 문의는 보내지 않았습니다.");
      form.reset();
      set_contact_status("contact_sent", false);
      return;
    }
    var name_value = String(form_data.get("이름") || "").trim();
    var email_value = String(form_data.get("email") || "").trim();
    var message_value = String(form_data.get("문의") || "").trim();
    form_data.set("이름", name_value);
    form_data.set("email", email_value);
    form_data.set("문의", message_value);
    form_data.set("회사", String(form_data.get("회사") || "").trim());
    var subject = translate("contact_subject");
    if (subject) {
      form_data.set("_subject", subject);
    }
    if (!name_value || !email_value || !message_value || !form.checkValidity()) {
      set_contact_status("contact_invalid", true);
      form.reportValidity();
      return;
    }
    is_sending = true;
    if (send_button) {
      send_button.disabled = true;
    }
    set_contact_status("contact_sending", false);
    try {
      var response = await fetch(FORM_URL, {
        method: "POST",
        body: form_data,
        headers: { Accept: "application/json" }
      });
      if (!response.ok) {
        var error_detail = "";
        try {
          error_detail = await response.text();
        } catch (read_error) {
          console.error("문의 오류 내용을 읽지 못했습니다.", read_error);
        }
        console.error("문의를 보내지 못했습니다.", response.status, error_detail);
        set_contact_status("contact_fail", true);
        return;
      }
      form.reset();
      set_contact_status("contact_sent", false);
    } catch (error) {
      console.error("문의 전송 중 네트워크 오류가 났습니다.", error);
      set_contact_status("contact_network", true);
    } finally {
      is_sending = false;
      if (send_button) {
        send_button.disabled = false;
      }
    }
  }

  try {
    apply_theme(document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light");
    apply_language(current_language(), false);
    var light_button = document.getElementById("button_theme_light");
    var dark_button = document.getElementById("button_theme_dark");
    if (light_button) {
      light_button.addEventListener("click", function () { choose_theme("light"); });
    }
    if (dark_button) {
      dark_button.addEventListener("click", function () { choose_theme("dark"); });
    }
    ["ko", "en", "ja", "zh", "zh-Hant", "hi", "es", "pt", "ar", "fr", "id", "de", "ru", "vi"].forEach(function (code) {
      var button = document.getElementById("button_language_" + code);
      if (!button) {
        return;
      }
      button.addEventListener("click", function () {
        try {
          apply_language(code, true);
        } catch (error) {
          console.error("언어를 바꾸지 못했습니다.", error);
        }
      });
    });
    var contact_form = document.getElementById("contact_form");
    if (contact_form) {
      contact_form.addEventListener("submit", function (event) {
        submit_contact_form(event);
      });
    }
  } catch (error) {
    console.error("안내 페이지를 시작하지 못했습니다.", error);
  }
})();
